/** Cache em memória: chave raca (`race` string) → URL do ícone PNG. */
const __ygoRaceIconUrlCache = new Map();
/** Cache em memória: chave tipo de carta (`type`) → URL do JPG de ícone. */
const __ygoMonsterTypeIconUrlCache = new Map();
/** Limite de entradas nos caches de ícone; ao exceder, o mapa é limpo para evitar crescimento indefinido. */
const YGO_CDN_ICON_URL_CACHE_MAX = 400;

/**
 * URL do PNG de ícone de raça (`race`) no CDN YGOPRODeck (subtipo de magia/armadilha ou raça de monstro).
 *
 * @param {string|null|undefined} race Valor `race` da API (será normalizado com `String`; null → '').
 * @returns {string}
 */
function ygoRaceIconUrl(race) {
  const k = race == null ? '' : String(race);
  if (!k.trim()) return '';
  let u = __ygoRaceIconUrlCache.get(k);
  if (u !== undefined) return u;
  // Sempre CDN: ícones de raça/subtipo (incl. magia/armadilha) não vêm no repo; `npm run vendor:ygo-deck-icons` espelha-os opcionalmente.
  u = `https://images.ygoprodeck.com/images/cards/icons/race/${encodeURIComponent(k)}.png`;
  if (__ygoRaceIconUrlCache.size > YGO_CDN_ICON_URL_CACHE_MAX) __ygoRaceIconUrlCache.clear();
  __ygoRaceIconUrlCache.set(k, u);
  return u;
}

/**
 * URL do JPG de ícone da linha de tipo (`type`) no CDN YGOPRODeck (`"Effect Monster"`, `"Continuous Spell Card"`, …).
 *
 * @param {string|null|undefined} monsterType Valor `type` da API (ex.: `"Dragon"`); null → `''`.
 * @returns {string}
 */
function ygoMonsterTypeIconUrl(monsterType) {
  const k = monsterType == null ? '' : String(monsterType);
  if (!k.trim()) return '';
  let u = __ygoMonsterTypeIconUrlCache.get(k);
  if (u !== undefined) return u;
  // Sempre CDN: `assets/icons/types/` só existe após vendor opcional; o monólito já usava este URL.
  u = `https://images.ygoprodeck.com/images/cards/icons/${encodeURIComponent(k)}.jpg`;
  if (__ygoMonsterTypeIconUrlCache.size > YGO_CDN_ICON_URL_CACHE_MAX)
    __ygoMonsterTypeIconUrlCache.clear();
  __ygoMonsterTypeIconUrlCache.set(k, u);
  return u;
}

/** Cache: segmento de atributo sanitizado → URL do ícone (SVG). */
const __ygoAttribIconUrlCache = new Map();
/** Teto de entradas antes de limpar `__ygoAttribIconUrlCache`. */
const YGO_ATTRIB_ICON_URL_CACHE_MAX = 96;

/**
 * Ícone de atributo (SVG Yu-Gi-Oh! Wiki em `assets/icons/attributes/`; monólito usa URL Fandom).
 *
 * @param {string|null|undefined} sanitizedAttribSeg Segmento seguro (ex.: `DARK`); falsy → `UNKNOWN`.
 * @returns {string}
 */
function ygoAttribIconUrl(sanitizedAttribSeg) {
  const seg = sanitizedAttribSeg ? String(sanitizedAttribSeg) : 'UNKNOWN';
  const key = seg.toUpperCase();
  let u = __ygoAttribIconUrlCache.get(seg);
  if (u !== undefined) return u;
  if (deckbuilderIsMonolithWithoutAssets()) {
    u = MONOLITH_ATTR_ICON_SVG_URL[key] || MONOLITH_ATTR_ICON_SVG_URL.UNKNOWN;
  } else {
    u = `${ICON_ROOT}/attributes/${seg}.svg`;
  }
  if (__ygoAttribIconUrlCache.size > YGO_ATTRIB_ICON_URL_CACHE_MAX) __ygoAttribIconUrlCache.clear();
  __ygoAttribIconUrlCache.set(seg, u);
  return u;
}

/**
 * URL do ícone da linha de atributo em cartões em modo lista (resultados, fila do deck, modal aleatório).
 * Magias e armadilhas não trazem `attribute` na API; usam os SVG de frame SPELL/TRAP como no tooltip.
 *
 * @param {object} card Objeto carta.
 * @param {string} ft {@link getFrameType}(card).
 * @param {string} cardTypeRaw Valor bruto de `card.type`.
 * @param {string} sanitizedAttribSeg Resultado de {@link sanitizeYgoCdnAttribFileSegment}(card.attribute).
 * @returns {string}
 */
function attrIconUrlForCardListRow(card, ft, cardTypeRaw, sanitizedAttribSeg) {
  if (card.attribute) return ygoAttribIconUrl(sanitizedAttribSeg);
  const t = String(cardTypeRaw || '');
  if (frameTypeIsSpell(ft) || t.includes('Spell')) return STATIC_ICON_SPELL_FRAME_SVG;
  if (frameTypeIsTrap(ft) || t.includes('Trap')) return STATIC_ICON_TRAP_FRAME_SVG;
  return '';
}

