// Cache leve de elementos por id (não cacheia `null`, e revalida `isConnected`).
const __elByIdCache = new Map();

/**
 * Obtém elemento por `id` com cache curto; ignora cache se o nó foi removido do DOM.
 *
 * @param {string|null|undefined} id Valor do atributo HTML `id` (convertido com `String`; falsy → sem lookup).
 * @returns {HTMLElement|null} Elemento encontrado ou null.
 */
function getEl(id) {
  const key = String(id || '');
  // Evita `getElementById('')` e chaves estranhas.
  if (!key) return null;
  const cached = __elByIdCache.get(key);
  // Reaproveita só se o nó ainda estiver ligado ao documento.
  if (cached && cached.isConnected) return cached;
  const el = document.getElementById(key);
  if (el) __elByIdCache.set(key, el);
  return el || null;
}

// Cache por referência ao array `card_images` (WeakMap evita churn ao alternar entre cartas diferentes).
const __cardImagesPickCache = /* @__PURE__ */ new WeakMap();

/**
 * Resolve objeto de imagem e índice dentro de `fullCard.card_images` para um `imgId` pedido.
 *
 * @param {object|null|undefined} fullCard Objeto carta da API com possível array `card_images`.
 * @param {string|number|null|undefined} imgId Identificador da variante de arte desejada.
 * @returns {{ imageObj: object|null, index: number }} Objeto escolhido (ou primeira entrada) e índice ou `-1`.
 */
function pickCardImageByImgId(fullCard, imgId) {
  const arr = fullCard && Array.isArray(fullCard.card_images) ? fullCard.card_images : null;
  if (!arr || !arr.length) return { imageObj: null, index: -1 };
  let slot = __cardImagesPickCache.get(arr);
  // Monta índices Maps só na primeira vez que este array `card_images` é visto.
  if (!slot) {
    const byId = new Map();
    const byIdx = new Map();
    for (let i = 0; i < arr.length; i++) {
      const ci = arr[i];
      // Ignora slots vazios no array da API.
      if (!ci) continue;
      const k = String(ci.id);
      // Primeira ocorrência do id ganha (evita duplicatas inconsistentes).
      if (!byId.has(k)) {
        byId.set(k, ci);
        byIdx.set(k, i);
      }
    }
    slot = { byId, byIdx };
    __cardImagesPickCache.set(arr, slot);
  }
  const key = String(imgId);
  const imageObj = slot.byId.get(key) || arr[0] || null;
  const index = slot.byIdx.has(key) ? slot.byIdx.get(key) : -1;
  return { imageObj, index: typeof index === 'number' ? index : -1 };
}

/**
 * Converte valores de um `Map` em array na ordem de iteração do Map.
 *
 * @param {Map<any, any>|null|undefined} m Mapa fonte (ausente ou vazio → `[]`).
 * @returns {any[]} Array com `.length === m.size` quando `m` não é vazio.
 */
function arrayFromMapValues(m) {
  if (!m) return [];
  const n = m.size;
  if (n === 0) return [];
  const out = new Array(n);
  let i = 0;
  for (const v of m.values()) out[i++] = v;
  return out;
}

/**
 * Converte chaves de um `Map` em array na ordem de iteração do Map.
 *
 * @param {Map<any, any>|null|undefined} m Mapa fonte (ausente ou vazio → `[]`).
 * @returns {any[]} Array com `.length === m.size` quando `m` não é vazio.
 */
function arrayFromMapKeys(m) {
  if (!m) return [];
  const n = m.size;
  if (n === 0) return [];
  const out = new Array(n);
  let i = 0;
  for (const k of m.keys()) out[i++] = k;
  return out;
}

/**
 * Converte um `Set` em array na ordem de iteração do Set.
 *
 * @param {Set<any>|null|undefined} s Conjunto fonte (ausente ou vazio → `[]`).
 * @returns {any[]} Array com um elemento por membro do Set.
 */
function arrayFromSet(s) {
  if (!s || !s.size) return [];
  const n = s.size;
  const out = new Array(n);
  let i = 0;
  for (const v of s) out[i++] = v;
  return out;
}

/**
 * Indica se a linha veio de um ramo “traduzido” da API (marca interna `__lang`).
 *
 * @param {object|null|undefined} row Objeto carta ou resultado enriquecido.
 * @returns {boolean} true se existe `__lang` diferente de `'en'`.
 */
function isTranslatedApiRow(row) {
  return row && row.__lang && row.__lang !== 'en';
}

/** Cache WeakMap: objeto carta → último nome para ordenação (`cardSortName`). */
const __cardSortNameCache = new WeakMap();
/** Cache WeakMap: objeto carta → nome em minúsculas para ordenação. */
const __cardSortNameLowerCache = new WeakMap();
/** Cache WeakMap: objeto carta → id estável como string. */
const __cardSortIdStrCache = new WeakMap();
/** Cache WeakMap auxiliar para nome exibido por “faixa” de API (detalhes em `displayNameForApiCard`). */
const __displayNameForApiLaneCache = new WeakMap();
/** Contador monotônico: ao incrementar, invalida caches de texto/collator derivados da carta. */
let __cardDerivedTextGen = 0;
/** Map cache key `${locale}\\0${optsKey}` → instância `Intl.Collator`. */
const __sortCollatorCache = new Map();

/**
 * Obtém collator ICU memoizado para ordenação lexicográfica de texto de cartas.
 *
 * @param {string|null|undefined} locale Código BCP 47 (ex.: `'pt'`, `'en'`); falsy usa `'en'` (padrão: `'en'`).
 * @param {string|null|undefined} optsKey Modo interno: `'base'`, `'base_num'` ou outro falsy para collator default (padrão: collator default).
 * @returns {Intl.Collator} Collator configurado conforme `optsKey`.
 */
function getSortCollator(locale, optsKey) {
  const loc = locale || 'en';
  const key = `${loc}\0${optsKey || ''}`;
  const cached = __sortCollatorCache.get(key);
  if (cached) return cached;
  let c;
  // Desempate numérico nos nomes quando solicitado (ex.: sufixos com dígitos).
  if (optsKey === 'base_num') c = new Intl.Collator(loc, { sensitivity: 'base', numeric: true });
  else if (optsKey === 'base') c = new Intl.Collator(loc, { sensitivity: 'base' });
  else c = new Intl.Collator(loc);
  __sortCollatorCache.set(key, c);
  return c;
}

/** Geração memoizada associada a `__sortTextLocaleMemoVal`; `-1` força miss na primeira checagem. */
let __sortTextLocaleMemoGen = -1;
/** Locale BC47 usado para ordenar texto derivado das cartas (invalidado quando `__cardDerivedTextGen` muda). */
let __sortTextLocaleMemoVal = '';

/**
 * Resolve locale para ordenação conforme modo inglês vs idioma da UI (`getUiLang`).
 *
 * @returns {string} Código tipo `'pt'`, `'en'`, `'fr'`, `'de'` ou `'it'`.
 */
function getCardTextSortLocale() {
  const g = __cardDerivedTextGen;
  // Memoização barata: mesmo gen + valor já calculado → reutiliza.
  if (__sortTextLocaleMemoGen === g && __sortTextLocaleMemoVal) return __sortTextLocaleMemoVal;
  let loc = 'pt';
  if (isEnglishMode()) loc = 'en';
  else {
    const L = getUiLang();
    if (L === 'pt') loc = 'pt';
    else if (L === 'fr' || L === 'de' || L === 'it') loc = L;
  }
  __sortTextLocaleMemoVal = loc;
  __sortTextLocaleMemoGen = g;
  return loc;
}

/** Collators típicos de `compareCardsBySortCriterion`; invalida junto da geração de texto/idioma. */
let __compareCollatorBundleKey = '';
/** Pacote memoizado de quatro collators (locale atual + inglês, com e sem modo numérico). */
let __compareCollatorBundle = null;

/**
 * Invalida o pacote `__compareCollatorBundle` para ser recriado na próxima ordenação.
 *
 * @returns {void}
 */
function bumpCompareSortCollatorBundle() {
  __compareCollatorBundleKey = '';
  __compareCollatorBundle = null;
}

/**
 * Devolve bundle de collators alinhado ao `__cardDerivedTextGen` e ao locale de texto atual.
 *
 * @returns {{ collBase: Intl.Collator, collBaseNum: Intl.Collator, collEnBase: Intl.Collator, collEnNum: Intl.Collator }}
 */
function getCompareSortCollatorBundle() {
  const locale = getCardTextSortLocale();
  const gen = __cardDerivedTextGen;
  const cacheKey = `${gen}\0${locale}`;
  if (__compareCollatorBundleKey === cacheKey && __compareCollatorBundle)
    return __compareCollatorBundle;
  __compareCollatorBundleKey = cacheKey;
  __compareCollatorBundle = {
    collBase: getSortCollator(locale, 'base'),
    collBaseNum: getSortCollator(locale, 'base_num'),
    collEnBase: getSortCollator('en', 'base'),
    collEnNum: getSortCollator('en', 'base_num'),
  };
  return __compareCollatorBundle;
}

/**
 * Incrementa geração derivada do texto das cartas e limpa bundle de collators acoplado.
 *
 * @returns {void}
 */
function bumpCardDerivedTextCaches() {
  __cardDerivedTextGen = (__cardDerivedTextGen + 1) | 0;
  bumpCompareSortCollatorBundle();
}

/**
 * Fingerprint estável dos campos `name` / `name_en` / `name_pt` para invalidar caches WeakMap.
 *
 * @param {object|null|undefined} card Objeto carta.
 * @returns {string} Três segmentos unidos por `\\0`, ou `''` se `card` inválido ou erro ao ler campos.
 */
function cardDisplayedNameFingerprint(card) {
  if (!card || typeof card !== 'object') return '';
  try {
    return `${String(card.name ?? '')}\0${String(card.name_en ?? '')}\0${String(card.name_pt ?? '')}`;
  } catch (_) {
    return '';
  }
}

/**
 * Nome utilizado para ordenar uma carta (via `displayNameForApiCard`), com cache por objeto e fingerprint.
 *
 * @param {object|null|undefined} card Objeto carta da API ou mesclado na UI.
 * @returns {string} Texto de ordenação ou `''`.
 */
function cardSortName(card) {
  if (!card || typeof card !== 'object') return '';
  const fp = cardDisplayedNameFingerprint(card);
  const gen = __cardDerivedTextGen;
  const cached = __cardSortNameCache.get(card);
  if (cached && cached.g === gen && cached.fp === fp) return cached.v;
  let v = '';
  try {
    v = String(displayNameForApiCard(card) || '');
  } catch (_) {
    v = '';
  }
  __cardSortNameCache.set(card, { g: gen, fp, v });
  return v;
}

/**
 * Versão minúscula de `cardSortName` com o mesmo critério de invalidação de cache.
 *
 * @param {object|null|undefined} card Objeto carta.
 * @returns {string} `cardSortName(card).toLowerCase()` ou `''`.
 */
function cardSortNameLower(card) {
  if (!card || typeof card !== 'object') return '';
  const fp = cardDisplayedNameFingerprint(card);
  const gen = __cardDerivedTextGen;
  const cached = __cardSortNameLowerCache.get(card);
  if (cached && cached.g === gen && cached.fp === fp) return cached.v;
  const v = cardSortName(card).toLowerCase();
  __cardSortNameLowerCache.set(card, { g: gen, fp, v });
  return v;
}

/**
 * Identificador da carta como string estável para ordenação/desempate (cache por objeto carta).
 *
 * @param {object|null|undefined} card Objeto carta com propriedade `id`.
 * @returns {string} `String(card.id ?? '')`.
 */
function cardSortIdStr(card) {
  if (!card || typeof card !== 'object') return '';
  const cached = __cardSortIdStrCache.get(card);
  if (cached !== undefined) return cached;
  const v = String(card.id ?? '');
  __cardSortIdStrCache.set(card, v);
  return v;
}

/**
 * Lê `.value` de input/select/textarea identificado por `id`.
 *
 * @param {string|null|undefined} id `id` HTML do controle.
 * @param {string} [fallback=''] Valor devolvido se elemento ausente ou sem propriedade `value` (padrão: `''`).
 * @returns {string} Valor atual ou `fallback`.
 */
function getVal(id, fallback = '') {
  const el = getEl(id);
  if (!el) return fallback;
  // inputs, selects e textareas têm `value`; outros elementos podem não ter.
  return 'value' in el ? (el.value ?? fallback) : fallback;
}

/**
 * Atribui `.value` ao controle identificado por `id`.
 *
 * @param {string|null|undefined} id `id` HTML do controle.
 * @param {string|null|undefined} value Novo valor (`null`/`undefined` viram `''`).
 * @returns {boolean} true se o elemento existe e aceita `value`.
 */
function setVal(id, value) {
  const el = getEl(id);
  if (!el || !('value' in el)) return false;
  el.value = value ?? '';
  return true;
}

/**
 * Verifica se `<select>` possui `<option value="…">` igual a `want` (comparação por string).
 *
 * @param {HTMLSelectElement|null|undefined} sel Elemento select.
 * @param {string|null|undefined} want Valor de opção desejado.
 * @returns {boolean} true se encontrada opção com esse `value`.
 */
function selectHasOptionValue(sel, want) {
  if (!sel || !sel.options) return false;
  const w = String(want);
  for (let i = 0; i < sel.options.length; i++) {
    if (String(sel.options[i].value) === w) return true;
  }
  return false;
}

/**
 * Define `textContent` no elemento `id`.
 *
 * @param {string|null|undefined} id `id` HTML do nó.
 * @param {string|null|undefined} text Texto (seguro — sem interpretar HTML).
 * @returns {boolean} true se o elemento foi encontrado e atualizado.
 */
function setText(id, text) {
  const el = getEl(id);
  if (!el) return false;
  el.textContent = text ?? '';
  return true;
}

/**
 * Define `innerHTML` no elemento `id` (conteúdo interpretado pelo navegador — usar só com HTML confiável).
 *
 * @param {string|null|undefined} id `id` HTML do nó.
 * @param {string|null|undefined} html Fragmento HTML.
 * @returns {boolean} true se o elemento foi encontrado e atualizado.
 */
function setHtml(id, html) {
  const el = getEl(id);
  if (!el) return false;
  el.innerHTML = html ?? '';
  return true;
}

/**
 * Lê estado `checked` de checkbox/radio pelo `id`.
 *
 * @param {string|null|undefined} id `id` do input.
 * @returns {boolean} true se marcado; false se ausente ou não aplicável.
 */
function isChecked(id) {
  const el = getEl(id);
  return !!(el && 'checked' in el && el.checked);
}

/**
 * Define `checked` em checkbox/radio.
 *
 * @param {string|null|undefined} id `id` do input.
 * @param {boolean|null|undefined} checked Estado desejado (coerced para boolean).
 * @returns {boolean} true se o elemento aceita `checked`.
 */
function setChecked(id, checked) {
  const el = getEl(id);
  if (!el || !('checked' in el)) return false;
  el.checked = !!checked;
  return true;
}

/**
 * Lê número finito do valor textual do controle `id`.
 *
 * @param {string|null|undefined} id `id` do controle com `.value`.
 * @param {number} [fallback=NaN] Retorno se vazio ou não numérico (padrão: `NaN`).
 * @returns {number} Número finito ou `fallback`.
 */
function numVal(id, fallback = NaN) {
  const raw = String(getVal(id, '') ?? '').trim();
  if (!raw) return fallback;
  const n = Number(raw);
  return Number.isFinite(n) ? n : fallback;
}

/**
 * Interpreta inteiro na base 10 a partir de string ou valor convertível.
 *
 * @param {unknown} value Entrada bruta (ex.: valor de cookie ou dataset).
 * @param {number} [fallback=NaN] Retorno se parse falhar (padrão: `NaN`).
 * @returns {number} Inteiro ou `fallback`.
 */
function int10(value, fallback = NaN) {
  const n = parseInt(String(value ?? '').trim(), 10);
  return Number.isNaN(n) ? fallback : n;
}

/**
 * Interpreta número em ponto flutuante a partir de string ou valor convertível.
 *
 * @param {unknown} value Entrada bruta.
 * @param {number} [fallback=NaN] Retorno se parse falhar (padrão: `NaN`).
 * @returns {number} Float ou `fallback`.
 */
function floatNum(value, fallback = NaN) {
  const n = parseFloat(String(value ?? '').trim());
  return Number.isNaN(n) ? fallback : n;
}

/** Regex singleton: qualquer caractere Unicode considerado espaço por `\s`. */
const __GRID_COL_TOK_WS = /\s/;

/**
 * Conta tokens separados por espaço (regex `\s`), sem alocar array intermediário.
 * Equivale semanticamente a `s.split(/\s+/).filter(Boolean).length`.
 *
 * @param {string|null|undefined} s Texto de entrada.
 * @returns {number} Quantidade de tokens não vazios.
 */
function countWhitespaceSeparatedTokens(s) {
  const str = typeof s === 'string' ? s : String(s ?? '');
  let count = 0;
  let i = 0;
  const len = str.length;
  const wsTest = __GRID_COL_TOK_WS;
  while (i < len) {
    // Consome sequência de whitespace.
    while (i < len && wsTest.test(str[i])) i++;
    if (i >= len) break;
    count++;
    // Consome token até próximo whitespace.
    while (i < len && !wsTest.test(str[i])) i++;
  }
  return count;
}

/**
 * Conta segmentos separados **apenas** por espaço ASCII (código 32), com comprimento mínimo `minLen`.
 *
 * @param {string|null|undefined} str Texto de entrada.
 * @param {number} minLen Comprimento mínimo do segmento para contar (>= 1 típico).
 * @returns {number} Quantidade de segmentos que satisfazem `minLen`.
 */
function countAsciiSpaceDelimitedSegmentsMinLen(str, minLen) {
  const s = typeof str === 'string' ? str : String(str ?? '');
  let count = 0;
  let i = 0;
  const len = s.length;
  while (i < len) {
    while (i < len && s.charCodeAt(i) === 32) i++;
    if (i >= len) break;
    const start = i;
    while (i < len && s.charCodeAt(i) !== 32) i++;
    if (i - start >= minLen) count++;
  }
  return count;
}

/**
 * Empurra para `out` segmentos separados por espaço ASCII com comprimento ≥ `minLen`, em MAIÚSCULAS (ex.: OCR).
 *
 * @param {string|null|undefined} str Texto de entrada.
 * @param {number} minLen Comprimento mínimo por segmento.
 * @param {string[]} out Array mutável que recebe `push` dos tokens.
 * @returns {void}
 */
function pushAsciiSpaceDelimitedSegmentsUpperMinLen(str, minLen, out) {
  const s = typeof str === 'string' ? str : String(str ?? '');
  let i = 0;
  const len = s.length;
  while (i < len) {
    while (i < len && s.charCodeAt(i) === 32) i++;
    if (i >= len) break;
    const start = i;
    while (i < len && s.charCodeAt(i) !== 32) i++;
    if (i - start >= minLen) out.push(s.slice(start, i).toUpperCase());
  }
}

