/**
 * Lê preferência persistida: tenta cookie primeiro; se vazio, usa `localStorage`; falhas retornam `''`.
 *
 * @param {string} key Uma das entradas de {@link UI_PREF_KEYS}.
 * @returns {string} Valor armazenado ou string vazia.
 */
function getUiPref(key) {
  try {
    const c = getCookie(key);
    if (c != null && String(c) !== '') return c;
  } catch (_) {}
  try {
    const v = localStorage.getItem(key);
    return v == null ? '' : String(v);
  } catch (_) {
    return '';
  }
}

/**
 * Persiste preferência em cookie ({@link UI_PREF_DAYS}) e espelha em `localStorage`.
 *
 * @param {string} key Uma das entradas de {@link UI_PREF_KEYS}.
 * @param {string|number|null|undefined} value Valor convertido para string (`null`/`undefined` viram `''`).
 * @returns {void}
 */
function setUiPref(key, value) {
  const v = value == null ? '' : String(value);
  try {
    setCookie(key, v, UI_PREF_DAYS);
  } catch (_) {}
  try {
    localStorage.setItem(key, v);
  } catch (_) {}
}

// Idioma do texto das cartas na API (en = padrão sem `language=`; pt/fr/de/it conforme guia YGOPRODeck).
/** Códigos aceitos para texto de carta na API (`en` omite parâmetro `language`).
 * @constant {ReadonlySet<string>}
 */
const API_CARD_LANG_CODES = new Set(['en', 'pt', 'fr', 'de', 'it']);
/** Preferência atual do usuário para idioma das cartas (`getUiLang` / normalização).
 * @type {string}
 */
let uiLang = 'pt';
/**
 * Normaliza texto livre para um código suportado por {@link API_CARD_LANG_CODES}.
 *
 * @param {unknown} v Valor cru (selector, cookie, etc.).
 * @returns {'en'|'pt'|'fr'|'de'|'it'} Código válido ou `'pt'` se inválido.
 */
function normalizeApiCardLangPref(v) {
  const s = String(v == null ? '' : v)
    .trim()
    .toLowerCase();
  return API_CARD_LANG_CODES.has(s) ? s : 'pt';
}
/**
 * Idioma atual das cartas vindas da API / mesclas bilíngues na UI.
 *
 * @returns {'en'|'pt'|'fr'|'de'|'it'}
 */
function getUiLang() {
  return normalizeApiCardLangPref(uiLang);
}
/** Texto das cartas na API em ingl\u00eas (sem `language=`). */
function isEnglishMode() {
  return getUiLang() === 'en';
}
/** R\u00f3tulos da interface no estilo portugu\u00eas; en/fr/de/it usam STRINGS[L] com fallback `en`, ou texto inline internacional. */
function siteUiIsPt() {
  return getUiLang() === 'pt';
}
function getDocumentElementHtmlLang() {
  const L = getUiLang();
  if (L === 'pt') return 'pt-BR';
  if (L === 'en') return 'en';
  if (L === 'fr') return 'fr';
  if (L === 'de') return 'de';
  if (L === 'it') return 'it';
  return 'en';
}
/** `language=` em cardinfo; `null` = ingl\u00eas (omitir par\u00e2metro). */
function getCardinfoLanguageParam() {
  const L = getUiLang();
  return L === 'en' ? null : L;
}

/**
 * Nome amigável para UI conforme o idioma atual e campos disponíveis (`name_en`, `name_pt`, `name`).
 *
 * @param {Record<string, unknown>|null|undefined} card Objeto carta (cache/API).
 * @returns {string} Nome não vazio ou string vazia se `card` ausente.
 */
function displayNameForApiCard(card) {
  if (!card) return '';
  const lk = isEnglishMode() ? 'en' : getUiLang() === 'pt' ? 'pt' : 'other';
  const gen = __cardDerivedTextGen;
  const fp = cardDisplayedNameFingerprint(card);
  let bucket = __displayNameForApiLaneCache.get(card);
  if (
    bucket &&
    bucket.g === gen &&
    bucket.fp === fp &&
    Object.prototype.hasOwnProperty.call(bucket, lk)
  ) {
    return bucket[lk];
  }
  if (!bucket || bucket.g !== gen || bucket.fp !== fp) bucket = { g: gen, fp };

  let out = '';
  if (lk === 'en') out = String(card.name_en || card.name || '').trim();
  else if (lk === 'pt') out = String(card.name_pt || card.name || '').trim();
  else out = String(card.name || '').trim();

  bucket[lk] = out;
  __displayNameForApiLaneCache.set(card, bucket);
  return out;
}

/**
 * Normaliza texto para comparar nomes beta vs oficiais (minúsculas, espaços colapsados).
 *
 * @param {unknown} s Texto cru.
 * @returns {string}
 */
function betaTooltipNorm(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * beta_name na YGOPRODeck vem apenas em inglês (mesmo com `language=pt` na API).
 * Após mescla EN+segunda língua, `beta_name` na raiz pode ser sobrescrito — preferimos `beta_name_en`.
 *
 * @param {Record<string, unknown>|null|undefined} card Objeto carta (`beta_name_en`, `beta_name` ou `misc_info[0].beta_name`).
 * @returns {string} Nome beta para exibição ou string vazia.
 */
function getCardBetaNameForTooltip(card) {
  if (!card) return '';
  const m = card.misc_info && card.misc_info[0];
  const fromEn =
    card.beta_name_en != null && String(card.beta_name_en).trim()
      ? String(card.beta_name_en).trim()
      : '';
  const fromRoot =
    card.beta_name != null && String(card.beta_name).trim() ? String(card.beta_name).trim() : '';
  const fromMisc =
    m && m.beta_name != null && String(m.beta_name).trim() ? String(m.beta_name).trim() : '';
  return fromEn || fromRoot || fromMisc;
}

/**
 * Decide se o tooltip deve destacar o nome beta (somente quando difere do nome oficial em inglês).
 *
 * @param {Record<string, unknown>|null|undefined} card Objeto carta.
 * @returns {boolean}
 */
function shouldShowBetaNameInTooltip(card) {
  const beta = getCardBetaNameForTooltip(card);
  const officialEn = String(card.name != null ? card.name : '').trim();
  if (!beta || !officialEn) return false;
  return betaTooltipNorm(beta) !== betaTooltipNorm(officialEn);
}

/**
 * Mescla carta já carregada com versão localizada sem descartar `beta_name` preservado em inglês.
 *
 * @param {Record<string, unknown>} existing Objeto carta base (tipicamente EN).
 * @param {Record<string, unknown>} localizedCard Sobreposição da API com `language=` traduzido.
 * @param {string} trLang Código da língua da sobreposição (gravado em `__lang`).
 * @returns {Record<string, unknown>} Novo objeto mesclado com `beta_name_en` estável quando aplicável.
 */
function mergedCardDualLangPreserveBeta(existing, localizedCard, trLang) {
  const merged = { ...existing, ...localizedCard, __lang: trLang };
  const prevEnglishBeta =
    existing.beta_name_en != null && String(existing.beta_name_en).trim()
      ? String(existing.beta_name_en).trim()
      : existing.beta_name != null && String(existing.beta_name).trim()
        ? String(existing.beta_name).trim()
        : '';
  if (prevEnglishBeta) {
    merged.beta_name_en =
      merged.beta_name_en != null && String(merged.beta_name_en).trim()
        ? String(merged.beta_name_en).trim()
        : prevEnglishBeta;
  }
  return merged;
}
/**
 * Invalida caches derivados do idioma e esvazia caches de API em memória ao mudar idioma da UI.
 *
 * @returns {void}
 */
function clearLanguageSensitiveApiCaches() {
  bumpCardDerivedTextCaches();
  try {
    cardCacheAPI && cardCacheAPI.clear && cardCacheAPI.clear();
  } catch (_) {}
  try {
    fnameRawCache && fnameRawCache.clear && fnameRawCache.clear();
  } catch (_) {}
}

