/** Geração de texto derivado ({@link bumpCardDerivedTextCaches}) na última vez que o memo sem variáveis foi invalidado.
 * @type {number}
 */
let __tStringMemoGen = -1;
/** Cache de {@link T}(key) sem `vars`, por idioma atual + chave (evita alocações repetidas).
 * @type {Map<string, string>}
 */
let __tStringNoVarsMemo = new Map();

/**
 * Resolve string traduzida para o idioma UI atual ({@link getUiLang}), com fallback `en` → `pt` → própria chave.
 *
 * @param {string} key Identificador em {@link STRINGS}.
 * @param {Record<string, string|number>|null|undefined} [vars] Mapa opcional para substituir `{token}` na mensagem.
 * @returns {string} Texto final (placeholders ausentes em `vars` viram string vazia).
 */
function T(key, vars) {
  const L = getUiLang();
  const g = __cardDerivedTextGen;
  if (!vars) {
    if (__tStringMemoGen !== g) {
      __tStringMemoGen = g;
      __tStringNoVarsMemo = new Map();
    }
    const memoKey = `${L}\0${key}`;
    const hit = __tStringNoVarsMemo.get(memoKey);
    if (hit !== undefined) return hit;
  }
  const row = STRINGS[key];
  if (!row) return key;
  let s = row[L];
  if (s == null || s === '') s = row.en ?? row.pt ?? key;
  if (vars && typeof s === 'string') {
    s = s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] != null ? String(vars[k]) : ''));
  }
  if (!vars) __tStringNoVarsMemo.set(`${L}\0${key}`, s);
  return s;
}

