/**
 * Sincroniza o `<select id="select-api-card-lang">`: valor atual, `aria-label`/`title`, texto das opções (emoji) e tooltips ({@link T}).
 *
 * @returns {void}
 */
function updateCardLangSelect() {
  const sel = getEl('select-api-card-lang');
  if (!sel) return;
  const v = getUiLang();
  if (selectHasOptionValue(sel, v)) sel.value = v;
  sel.setAttribute('aria-label', T('lang.switch_aria'));
  sel.setAttribute('title', T('lang.switch_aria'));
  const _langOpts = sel.querySelectorAll('option');
  for (let _lo = 0; _lo < _langOpts.length; _lo++) {
    const opt = _langOpts[_lo];
    const code = String(opt.value || '').toLowerCase();
    const ch = API_SITE_LANG_FLAG_EMOJI[code];
    if (ch) opt.textContent = ch;
    const lab = T('lang.opt_' + code);
    opt.setAttribute('title', lab);
    opt.setAttribute('aria-label', lab);
  }
  try {
    syncNativeCustomSelectTrigger('select-api-card-lang');
  } catch (_) {}
}

/**
 * Altera idioma do texto das cartas na API, persiste em {@link UI_PREF_KEYS.lang}, reaplica UI e refaz busca/cache sensível ao idioma.
 *
 * @param {unknown} next Valor cru (mesmo formato aceito por {@link normalizeApiCardLangPref}).
 * @returns {void}
 */
function setApiCardLang(next) {
  const lang = normalizeApiCardLangPref(next);
  if (getUiLang() === lang) return;
  uiLang = lang;
  setUiPref(UI_PREF_KEYS.lang, uiLang);
  applyUiLanguage();
  try {
    updateDeckValidationToggleUi();
  } catch (_) {}

  clearLanguageSensitiveApiCaches();
  currentPage = 1;
  try {
    performSearch(true);
  } catch (_) {
    try {
      performSearch();
    } catch (_) {}
  }
}

