/**
 * Extrai versão e data amigável da resposta JSON de `checkDBVer.php` e preenche globais de versão.
 *
 * @param {unknown} j Corpo JSON (array ou objeto único).
 * @returns {void}
 */
function applyCheckDbVerJson(j) {
  const rows = Array.isArray(j) ? j : j && typeof j === 'object' ? [j] : [];
  const row = rows[0];
  if (!row || row.database_version == null || String(row.database_version).trim() === '') {
    ygoprodeckDbVersionShort = '';
    ygoprodeckDbVersionTitle = '';
    return;
  }
  const ver = String(row.database_version).trim();
  const raw =
    row.last_update != null && String(row.last_update).trim() !== ''
      ? String(row.last_update).trim()
      : row.date != null
        ? String(row.date).trim()
        : '';
  ygoprodeckDbVersionShort = ver;
  ygoprodeckDbVersionTitle = raw
    ? `Banco YGOPRODeck · versão ${ver} · atualizado em ${raw}`
    : `Banco YGOPRODeck · versão ${ver}`;
}

/**
 * Consulta a API pública `checkDBVer.php`, atualiza labels de versão e redesenha cabeçalho compacto.
 *
 * @returns {Promise<void>}
 */
async function refreshYgoprodeckDbVersion() {
  try {
    const res = await deckbuilderPublicApiFetch('https://db.ygoprodeck.com/api/v7/checkDBVer.php');
    if (!res.ok) return;
    applyCheckDbVerJson(await res.json());
  } catch (e) {
    console.warn('checkDBVer:', e);
  }
  refreshViewControlsHeaderCompact();
}

