/**
 * Troca tema visual (`theme-*` na raiz), opcionalmente sem persistir quando `opts.preview`.
 *
 * @param {string} themeName Uma das entradas de {@link UI_THEME_CLASSES} ou string vazia para limpar.
 * @param {{ preview?: boolean }|null|undefined} [opts] Se `preview` truthy, não grava preferência nem `localStorage` legado.
 * @returns {void}
 */
function changeTheme(themeName, opts) {
  const root = document.documentElement;
  const utc = UI_THEME_CLASSES;
  for (let ti = 0; ti < utc.length; ti++) root.classList.remove(utc[ti]);
  if (themeName) root.classList.add(themeName);
  if (!opts || !opts.preview) {
    setUiPref(UI_PREF_KEYS.theme, themeName);
    try {
      localStorage.setItem('selectedTheme', themeName);
    } catch (_) {}
  }
  requestCardSurfaceFeedback('theme');
  renderResults();
}

/**
 * Pagina lista de resultados (`currentPage`) e rola o painel ao topo; sincroniza URL de filtros quando aplicável.
 *
 * @param {number} step Delta de páginas (típicamente `+1` ou `-1`).
 * @returns {void}
 */
function changePage(step) {
  const totalPages = Math.ceil(searchResults.length / getItemsPerPage());
  const newPage = currentPage + step;
  if (newPage >= 1 && newPage <= totalPages) {
    requestCardSurfaceFeedback('page');
    currentPage = newPage;
    renderResults();
    const rv = getEl('results-view');
    if (rv) rv.scrollTop = 0;
    // Atualiza a URL imediatamente (file:// pode não respeitar bem timers curtos).
    try {
      pushDeckbuilderFilterUrlToHistory();
    } catch (_) {}
    scheduleDeckbuilderFilterUrlSync();
  }
}

/**
 * Filtra cartas pela faixa USD (TCGPlayer) usando campos já calculados na carta.
 * Comportamento legado: `max` ausente ou normalizado como `0` vira sem limite superior (`Infinity`).
 *
 * @param {Array<Record<string, unknown>>} cards Lista de cartas já carregadas (filtro só no cliente).
 * @returns {Array<Record<string, unknown>>}
 */
function filterByPrice(cards) {
  const minPrice = floatNum(getVal('filter-price-min', ''), NaN) || 0;
  // Mantém comportamento antigo: max=0 vira Infinity por causa do `||`.
  const maxPrice = floatNum(getVal('filter-price-max', ''), NaN) || Infinity;
  return cards.filter((card) => {
    const price = getTcgplayerPriceUsd(card);
    return price >= minPrice && price <= maxPrice;
  });
}

