/** Cache da lista ordenada de subtipos fallback (até existir scan completo `catalogMonsterSubtypeOpts`).
 * @type {null|Array<{ v: string, labelPt: string, hints: string[] }>}
 */
let monsterSubtypeFallbackOptsCached = null;

/**
 * Monta opções de subtipo monstro a partir de {@link MONSTER_TYPE_LABEL_PT} / {@link MONSTER_TYPE_HINTS}, ordenadas por rótulo PT.
 *
 * @returns {Array<{ v: string, labelPt: string, hints: string[] }>}
 */
function monsterSubtypeFallbackOpts() {
  if (!monsterSubtypeFallbackOptsCached) {
    const collPtLbl = getSortCollator('pt', 'base');
    monsterSubtypeFallbackOptsCached = Object.keys(MONSTER_TYPE_LABEL_PT)
      .map((v) => ({
        v,
        labelPt: MONSTER_TYPE_LABEL_PT[v],
        hints: MONSTER_TYPE_HINTS[v] || [],
      }))
      .sort((a, b) => collPtLbl.compare(String(a.labelPt || ''), String(b.labelPt || '')));
  }
  return monsterSubtypeFallbackOptsCached;
}

/**
 * Opções de subtipo de monstro exibidas no filtro: preferencialmente catálogo do scan `cardinfo`; senão {@link monsterSubtypeFallbackOpts}.
 *
 * @returns {Array<{ v: string, labelPt?: string, hints?: string[], label?: string }>}
 */
function getMonsterSubtypeOpts() {
  if (window.catalogMonsterSubtypeOpts && window.catalogMonsterSubtypeOpts.length)
    return window.catalogMonsterSubtypeOpts;
  return monsterSubtypeFallbackOpts();
}

/** Cache para resolver texto do usuário → valor API de subtipo (`ref` aponta para snapshot de opções).
 * @type {{ ref: unknown, byLabelLow: Map<string, unknown>|null, byVLow: Map<string, unknown>|null, byVExact: Map<string, unknown>|null, hintLowToV: Map<string, unknown>|null }}
 */
let __subtypeInputResolveCache = {
  ref: null,
  byLabelLow: null,
  byVLow: null,
  byVExact: null,
  hintLowToV: null,
};

/** Memoização do conjunto de valores `v` válidos para subtipo atual ({@link getMonsterSubtypeOpts}).
 * @type {{ ref: unknown, set: ReadonlySet<string>|null }}
 */
let __monsterSubtypeOptsVSetCache = { ref: null, set: null };

/**
 * @returns {ReadonlySet<string>} Conjunto dos valores `type` de monstro aceitos pelas opções atuais.
 */
function getMonsterSubtypeOptsVSet() {
  const o = getMonsterSubtypeOpts();
  if (__monsterSubtypeOptsVSetCache.ref !== o) {
    __monsterSubtypeOptsVSetCache.ref = o;
    __monsterSubtypeOptsVSetCache.set = Object.freeze(new Set(o.map((r) => r.v)));
  }
  return __monsterSubtypeOptsVSetCache.set;
}

