/**
 * Rótulo de raça ou tipo spell/trap para exibição conforme idioma UI (`pt` usa {@link FILTER_RACES}; FR/DE/IT via {@link RACE_UI_I18N}).
 *
 * @param {'Monster'|'Spell Card'|'Trap Card'} cat Categoria grossa da carta.
 * @param {string} apiKey Valor retornado pela API (ex.: `Dragon`, `Quick-Play`).
 * @returns {string}
 */
function getRaceDisplayLabel(cat, apiKey) {
  const L = getUiLang();
  if (L === 'en') return apiKey;
  if (L === 'pt') {
    const m = FILTER_RACES[cat];
    return (m && m[apiKey]) || apiKey;
  }
  const block = RACE_UI_I18N[L];
  const m = block && block[cat];
  return (m && m[apiKey]) || apiKey;
}

/** Cache por categoria de chaves API de raça/tipo: depende do idioma e do catálogo estendido `catalogRaceKeys`.
 * @type {Record<string, { lang: string, extRef: unknown[]|null, sorted: string[] }>}
 */
const __raceApiKeysForCategoryCache = Object.create(null);

/**
 * Lista ordenada de chaves de raça (ou tipo spell/trap) para a categoria, unindo mapa estático e catálogo escaneado.
 *
 * @param {'Monster'|'Spell Card'|'Trap Card'} cat
 * @returns {string[]}
 */
function raceApiKeysForCategory(cat) {
  const m = FILTER_RACES[cat];
  if (!m) return [];
  const lang = getUiLang();
  const ext = window.catalogRaceKeys && window.catalogRaceKeys[cat];
  const extRef = ext && ext.length ? ext : null;
  const slot = __raceApiKeysForCategoryCache[cat];
  if (slot && slot.lang === lang && slot.extRef === extRef) return slot.sorted;

  const keys = new Set(Object.keys(m));
  if (extRef) {
    for (let _xr = 0; _xr < extRef.length; _xr++) {
      const k = extRef[_xr];
      if (k) keys.add(String(k));
    }
  }
  const loc = { en: 'en', pt: 'pt', fr: 'fr', de: 'de', it: 'it' }[lang] ?? 'en';
  const raceColl = getSortCollator(loc, 'base');
  const sorted = [];
  for (const k of keys) sorted.push(k);
  sorted.sort((a, b) =>
    raceColl.compare(String(getRaceDisplayLabel(cat, a)), String(getRaceDisplayLabel(cat, b)))
  );
  __raceApiKeysForCategoryCache[cat] = { lang, extRef, sorted };
  return sorted;
}

