/** Rótulo PT do atributo em minúsculas → chave API (`dark`, …), derivado de {@link FILTER_ATTR_LABEL_PT}.
 * @constant {Readonly<Record<string, string>>}
 */
const FILTER_ATTR_PT_LABEL_LOWER_TO_API = Object.freeze(
  (() => {
    const m = Object.create(null);
    for (const api in FILTER_ATTR_LABEL_PT) {
      if (!Object.prototype.hasOwnProperty.call(FILTER_ATTR_LABEL_PT, api)) continue;
      const lab = FILTER_ATTR_LABEL_PT[api];
      m[String(lab).toLowerCase()] = api;
    }
    return m;
  })()
);

/** Alias digitável em minúsculas → chave API de atributo; ordem em {@link FILTER_ATTR_OPTS} define prioridade em colisão.
 * @constant {Readonly<Record<string, string>>}
 */
const FILTER_ATTR_ALIAS_LOWER_TO_API = Object.freeze(
  (() => {
    const m = Object.create(null);
    for (const [api, aliases] of Object.entries(FILTER_ATTR_OPTS)) {
      if (m[api] == null) m[api] = api;
      for (const a of aliases) {
        const ak = String(a).toLowerCase();
        if (m[ak] == null) m[ak] = api;
      }
    }
    return m;
  })()
);

