/**
 * Traduz string composta de tipo de carta exibida na UI (FR/DE/IT) aplicando substituições regex em ordem.
 * Para `pt`/`en` ou idiomas sem cadeia definida devolve o texto original da API.
 *
 * @param {unknown} raw Valor bruto de `type` ou fragmento concatenado na UI.
 * @param {string} lang Código UI (`fr`, `de`, `it`, …).
 * @returns {string}
 */
function translateCardTypeUiStr(raw, lang) {
  if (!raw || lang === 'en') return String(raw || '');
  const chains = CARD_TYPE_UI_REPLACE_CHAINS[lang];
  if (!chains) return String(raw);
  let t = String(raw);
  for (let i = 0; i < chains.length; i++) {
    const row = chains[i];
    t = t.replace(row.re, row.to);
  }
  return t;
}

