/**
 * Rótulo humano para um par categoria de chip + valor armazenado (mesmo valor enviado à API ou chave interna).
 *
 * @param {string} key Campo em {@link window.filterChipState} (`typeCategory`, `race`, `banlist`, …).
 * @param {string} val Valor bruto do chip.
 * @returns {string} Texto para exibir no chip ou `val` se não houver mapeamento.
 */
function filterChipLabel(key, val) {
  if (key === 'typeCategory') {
    const L = getUiLang();
    const tab = FILTER_CHIP_TYPE_CATEGORY_BY_LANG[L] || FILTER_CHIP_TYPE_CATEGORY_BY_LANG.en;
    return tab[val] || val;
  }
  if (key === 'subtype') {
    if (siteUiIsPt()) return MONSTER_TYPE_LABEL_PT[val] || val;
    const L = getUiLang();
    if (L === 'en') return val;
    return translateCardTypeUiStr(val, L);
  }
  if (key === 'race') {
    const cat = getFilterTypeCategory();
    return getRaceDisplayLabel(cat, val);
  }
  if (key === 'attribute') {
    const L = getUiLang();
    if (L === 'pt') return FILTER_CHIP_ATTR_PT_SHORT[val] || val;
    if (L === 'fr') return FILTER_ATTR_LABEL_FR[val] || val;
    if (L === 'de') return FILTER_ATTR_LABEL_DE[val] || val;
    if (L === 'it') return FILTER_ATTR_LABEL_IT[val] || val;
    return FILTER_CHIP_ATTR_EN_SHORT[val] || val;
  }
  if (key === 'level') {
    const lab = formatApiNumericFilterValueForLabel(val);
    const L = getUiLang();
    if (L === 'pt') return `Nv. ${lab}`;
    if (L === 'fr') return `Niv. ${lab}`;
    if (L === 'de') return `St. ${lab}`;
    if (L === 'it') return `Liv. ${lab}`;
    return `Level ${lab}`;
  }
  if (key === 'linkval') return `LINK-${val}`;
  if (key === 'scale') {
    const L = getUiLang();
    if (L === 'pt') return `Escala ${val}`;
    if (L === 'fr') return `Échelle ${val}`;
    if (L === 'de') return `Skala ${val}`;
    if (L === 'it') return `Scala ${val}`;
    return `Scale ${val}`;
  }
  if (key === 'linkmarker') {
    const L = getUiLang();
    if (L === 'pt') return FILTER_CHIP_LINKMARKER_PT[val] || val;
    if (L === 'fr') return FILTER_CHIP_LINKMARKER_FR[val] || val;
    if (L === 'de') return FILTER_CHIP_LINKMARKER_DE[val] || val;
    if (L === 'it') return FILTER_CHIP_LINKMARKER_IT[val] || val;
    return FILTER_CHIP_LINKMARKER_EN[val] || val;
  }
  if (key === 'era') {
    return FILTER_ERA_KEY_TO_LABEL[val] || val;
  }
  if (key === 'dateRegion') {
    if (getUiLang() !== 'pt') {
      if (val === 'ocg') return T('filteropt.date_ocg');
      return T('filteropt.date_tcg');
    }
    return (
      FILTER_DATE_REGION_V_TO_LABEL[val] ??
      (val === 'ocg' ? 'OCG — lançamento japonês' : 'TCG — lançamento ocidental')
    );
  }
  if (key === 'banlist') {
    if (siteUiIsPt()) return FILTER_BANLIST_V_TO_LABEL_PT[val] || val;
    return cachedFilterRowsBanlistVToLabel()[val] || FILTER_BANLIST_V_TO_LABEL_PT[val] || val;
  }
  if (key === 'staple') {
    if (siteUiIsPt()) return FILTER_STAPLE_V_TO_LABEL_PT[val] || val;
    return cachedFilterRowsStapleVToLabel()[val] || FILTER_STAPLE_V_TO_LABEL_PT[val] || val;
  }
  if (key === 'hasEffect') {
    if (siteUiIsPt()) return FILTER_HASEFFECT_V_TO_LABEL_PT[val] || val;
    return cachedFilterRowsHasEffectVToLabel()[val] || FILTER_HASEFFECT_V_TO_LABEL_PT[val] || val;
  }
  if (key === 'archetype') return val;
  return val;
}

/**
 * Mostra ou esconde a linha do botão “limpar” associada a um grupo de chips.
 *
 * @param {string} buttonId `id` do botão dentro de `.filter-clear-stack`.
 * @param {boolean} visible Se o botão/linha deve aparecer.
 * @returns {void}
 */
function setChipClearRowVisible(buttonId, visible) {
  const btn = getEl(buttonId);
  if (!btn) return;
  const wrap = btn.closest('.filter-clear-stack');
  if (wrap) wrap.style.display = visible ? 'flex' : 'none';
  else btn.style.display = visible ? 'block' : 'none';
}

