/**
 * Preenche datalists estáticos do painel de filtros (tipo, nível, atributo, era, região, banlist, staple, has_effect, link, marker, escala).
 * Chamado ao mudar idioma e na montagem inicial da UI.
 *
 * @returns {void}
 */
function fillStaticComboDatalists() {
  const uiPt = siteUiIsPt();
  const tdl = getEl('datalist-filter-type');
  if (tdl) {
    tdl.innerHTML = uiPt ? DATALIST_FILTER_TYPE_HTML_PT : DATALIST_FILTER_TYPE_HTML_EN;
  }
  const lvDl = getEl('datalist-filter-level');
  if (lvDl) {
    lvDl.innerHTML = getLevelDatalistInnerHtml();
  }
  const attrDl = getEl('datalist-filter-attribute');
  if (attrDl) {
    if (!uiPt) {
      attrDl.innerHTML = getAttrDatalistInnerHtmlNonPt();
    } else {
      attrDl.innerHTML = DATALIST_ATTR_OPTIONS_HTML_PT;
    }
  }
  const eraDl = getEl('datalist-filter-era');
  if (eraDl) {
    eraDl.innerHTML = DATALIST_ERA_OPTIONS_HTML;
  }
  const drDl = getEl('datalist-date-region');
  if (drDl) {
    drDl.innerHTML = getDateRegionDatalistInnerHtml();
  }
  const bDl = getEl('datalist-filter-banlist');
  if (bDl) {
    bDl.innerHTML = getBanlistDatalistInnerHtml();
  }

  const stapleDl = getEl('datalist-filter-staple');
  if (stapleDl) {
    stapleDl.innerHTML = getStapleDatalistInnerHtml();
  }
  const hefDl = getEl('datalist-filter-haseffect');
  if (hefDl) {
    hefDl.innerHTML = getHasEffectDatalistInnerHtml();
  }

  const linkDl = getEl('datalist-filter-linkval');
  if (linkDl) {
    linkDl.innerHTML = DATALIST_LINKVAL_OPTIONS_HTML;
  }
  const lmDl = getEl('datalist-filter-linkmarker');
  if (lmDl) {
    lmDl.innerHTML = uiPt
      ? DATALIST_LINKMARKER_OPTIONS_HTML_PT
      : DATALIST_LINKMARKER_OPTIONS_HTML_EN;
  }
  const scDl = getEl('datalist-filter-scale');
  if (scDl) {
    scDl.innerHTML = DATALIST_SCALE_OPTIONS_HTML;
  }
}

/**
 * Normaliza texto do campo Link rating (`1`–`6`), opcionalmente após prefixo `link`/`Link:`.
 * Só aplica quando o tipo filtrado é Monstro.
 *
 * @param {unknown} raw Entrada do usuário.
 * @returns {string|null} String numérica ou `null` se inválido/fora do intervalo ou tipo não-monstro.
 */
function resolveLinkValInput(raw) {
  if (getFilterTypeCategory() !== 'Monster') return null;
  let q = String(raw || '')
    .trim()
    .toLowerCase();
  if (!q) return null;
  q = q.replace(/^(link)\s*[-:]?\s*/i, '');
  const n = int10(q, NaN);
  if (Number.isNaN(n) || n < 1 || n > 6) return null;
  return String(n);
}

/** Sinônimos por chave API de link marker (`top-left`, …) aceitos na caixa de filtro.
 * @constant {Readonly<Record<string, readonly string[]>>}
 */
const LINK_MARKER_ALIAS_MAP = Object.freeze({
  'top-left': Object.freeze([
    'top-left',
    'top left',
    'tl',
    'sup-esq',
    'sup esq',
    'superior esquerdo',
    '↖',
  ]),
  top: Object.freeze(['top', 't', 'cima', '↑']),
  'top-right': Object.freeze([
    'top-right',
    'top right',
    'tr',
    'sup-dir',
    'sup dir',
    'superior direito',
    '↗',
  ]),
  left: Object.freeze(['left', 'l', 'esq', 'esquerda', '←']),
  right: Object.freeze(['right', 'r', 'dir', 'direita', '→']),
  'bottom-left': Object.freeze([
    'bottom-left',
    'bottom left',
    'bl',
    'inf-esq',
    'inf esq',
    'inferior esquerdo',
    '↙',
  ]),
  bottom: Object.freeze(['bottom', 'b', 'baixo', '↓']),
  'bottom-right': Object.freeze([
    'bottom-right',
    'bottom right',
    'br',
    'inf-dir',
    'inf dir',
    'inferior direito',
    '↘',
  ]),
});

/** Ordem estável dos marcadores Link ao montar parâmetros e validar entrada.
 * @constant {readonly string[]}
 */
const LINK_MARKER_API_KEYS_ORDER = Object.freeze([
  'top-left',
  'top',
  'top-right',
  'left',
  'right',
  'bottom-left',
  'bottom',
  'bottom-right',
]);

/** Conjunto das chaves API válidas em {@link LINK_MARKER_API_KEYS_ORDER}.
 * @constant {ReadonlySet<string>}
 */
const LINK_MARKER_API_KEYS_SET = Object.freeze(new Set(LINK_MARKER_API_KEYS_ORDER));

/**
 * Texto normalizado (minúsculas, espaços colapsados) → chave API; primeira entrada em {@link LINK_MARKER_ALIAS_MAP} ganha em empate.
 *
 * @constant {Readonly<Record<string, string>>}
 */
const LINK_MARKER_ALIAS_NORMALIZED_TO_API = Object.freeze(
  (() => {
    const m = Object.create(null);
    const norm = (s) => String(s).toLowerCase().replace(/\s+/g, ' ').trim();
    for (const [api, aliases] of Object.entries(LINK_MARKER_ALIAS_MAP)) {
      const nk = norm(api);
      if (m[nk] == null) m[nk] = api;
      for (const a of aliases) {
        const ak = norm(a);
        if (m[ak] == null) m[ak] = api;
      }
    }
    return m;
  })()
);

/**
 * Resolve entrada do usuário para chave API de link marker; aceita aliases PT/EN e valores compactos (`top-left` sem espaços).
 *
 * @param {unknown} raw Texto da combo ou datalist.
 * @returns {string|null}
 */
function resolveLinkMarkerInput(raw) {
  if (getFilterTypeCategory() !== 'Monster') return null;
  const q0 = String(raw || '').trim();
  if (!q0) return null;
  const q = q0.toLowerCase().replace(/\s+/g, ' ').trim();
  const byAlias = LINK_MARKER_ALIAS_NORMALIZED_TO_API[q];
  if (byAlias) return byAlias;
  const qCompact = q.replace(/\s/g, '');
  return LINK_MARKER_API_KEYS_SET.has(qCompact) ? qCompact : null;
}

/**
 * Escala de Pêndulo `0`–`13`; permite prefixos `scale`/`escala`. Apenas com tipo Monstro ativo.
 *
 * @param {unknown} raw
 * @returns {string|null}
 */
function resolveScaleInput(raw) {
  if (getFilterTypeCategory() !== 'Monster') return null;
  let q = String(raw || '')
    .trim()
    .toLowerCase();
  if (!q) return null;
  q = q.replace(/^(scale|escala)\s*[-:]?\s*/i, '');
  const n = int10(q, NaN);
  if (Number.isNaN(n) || n < 0 || n > 13) return null;
  return String(n);
}

/**
 * Mapeia texto livre para `Monster` | `Spell Card` | `Trap Card` usando {@link FILTER_TYPE_CATEGORY_ALIAS_TO_V}.
 *
 * @param {string} raw Texto já trimmed esperado pelo chamador.
 * @returns {string|null}
 */
function resolveTypeCategoryInput(raw) {
  const q = raw.trim().toLowerCase();
  if (!q) return null;
  return FILTER_TYPE_CATEGORY_ALIAS_TO_V[q] || null;
}

/**
 * Resolve subtipo de monstro (`type` API) por label PT, valor EN, hints ou correspondência parcial única.
 *
 * @param {string} raw Texto do campo (usa `.trim()` internamente).
 * @returns {string|null}
 */
function resolveSubtypeInput(raw) {
  if (getFilterTypeCategory() !== 'Monster') return null;
  const q0 = raw.trim();
  if (!q0) return null;
  const q = q0.toLowerCase();
  const opts = getMonsterSubtypeOpts();
  if (__subtypeInputResolveCache.ref !== opts) {
    const byLabelLow = Object.create(null);
    const byVLow = Object.create(null);
    const byVExact = Object.create(null);
    const hintLowToV = Object.create(null);
    for (const o of opts) {
      const v = o.v;
      const lp = (o.labelPt || '').toLowerCase();
      if (lp && byLabelLow[lp] == null) byLabelLow[lp] = v;
      if (byVExact[v] == null) byVExact[v] = v;
      const vl = v.toLowerCase();
      if (byVLow[vl] == null) byVLow[vl] = v;
      for (const h of o.hints || []) {
        const hl = String(h).toLowerCase();
        if (hintLowToV[hl] == null) hintLowToV[hl] = v;
      }
    }
    __subtypeInputResolveCache = {
      ref: opts,
      byLabelLow,
      byVLow,
      byVExact,
      hintLowToV,
    };
  }
  const c = __subtypeInputResolveCache;
  const hitLabel = c.byLabelLow[q];
  if (hitLabel) return hitLabel;
  const ex = c.byVExact[q0] || c.byVLow[q];
  if (ex) return ex;
  const byHint = c.hintLowToV[q];
  if (byHint) return byHint;
  const partials = opts.filter(
    (o) =>
      (o.labelPt || '').toLowerCase().includes(q) ||
      o.v.toLowerCase().includes(q) ||
      (o.hints || []).some((h) => h.toLowerCase().includes(q))
  );
  if (partials.length === 1) return partials[0].v;
  return null;
}

/**
 * Resolve raça ou subtipo spell/trap para chave API conforme categoria atual e {@link raceApiKeysForCategory}.
 *
 * @param {string} raw
 * @returns {string|null}
 */
function resolveRaceInput(raw) {
  const cat = getFilterTypeCategory();
  if (!cat || !FILTER_RACES[cat]) return null;
  const q = raw.trim();
  if (!q) return null;
  const low = q.toLowerCase();
  const keys = raceApiKeysForCategory(cat);
  for (const k of keys) {
    if (k === q) return k;
    if (k.toLowerCase() === low) return k;
    const lab = getRaceDisplayLabel(cat, k);
    if (lab.toLowerCase() === low) return k;
  }
  const partials = keys.filter((k) => {
    const lab = getRaceDisplayLabel(cat, k);
    return k.toLowerCase().includes(low) || lab.toLowerCase().includes(low);
  });
  if (partials.length === 1) return partials[0];
  return null;
}

/**
 * Converte rótulo PT ou alias para chave de atributo da API (`dark`, …).
 *
 * @param {string} raw
 * @returns {string|null}
 */
function resolveAttributeInput(raw) {
  const q = raw.trim().toLowerCase();
  if (!q) return null;
  const fromPtLabel = FILTER_ATTR_PT_LABEL_LOWER_TO_API[q];
  if (fromPtLabel) return fromPtLabel;
  return FILTER_ATTR_ALIAS_LOWER_TO_API[q] || null;
}

/**
 * Nível `0`–`13`; remove prefixos `nível`/`level`/`Nv.`.
 *
 * @param {string} raw
 * @returns {string|null} `null` para vazio ou palavra “todos”.
 */
function resolveLevelInput(raw) {
  let q = raw.trim().toLowerCase();
  if (q === '' || q === 'todos') return null;
  q = q.replace(/^(nível|nivel|level)\s*/i, '').replace(/^nv\.?\s*/i, '');
  const n = int10(q, NaN);
  if (Number.isNaN(n) || n < 0 || n > 13) return null;
  return String(n);
}

/**
 * Resolve era Yu-Gi-Oh! por rótulo completo, chave canônica ou sinônimo ({@link FILTER_ERA_SYNONYM_TO_KEY}).
 *
 * @param {string} raw Texto trimmed.
 * @returns {string|null}
 */
function resolveEraInput(raw) {
  const q0 = raw.trim();
  if (!q0) return null;
  const q = q0.toLowerCase();
  const fromFullLabel = FILTER_ERA_LABEL_LOWER_TO_KEY[q];
  if (fromFullLabel) return fromFullLabel;
  if (FILTER_ERAS[q]) return q;
  const eraSyn = FILTER_ERA_SYNONYM_TO_KEY[q];
  if (eraSyn) return eraSyn;
  return FILTER_ERA_KEY_LOWER_TO_KEY[q] || null;
}

