// Chrome bloqueia vibrate sem gesto do usuário; além disso, evita flood de warnings no console.
let __hasUserGesture = false;
(() => {
  const mark = () => {
    __hasUserGesture = true;
    window.removeEventListener('pointerdown', mark, true);
    window.removeEventListener('touchstart', mark, true);
    window.removeEventListener('keydown', mark, true);
  };
  window.addEventListener('pointerdown', mark, true);
  window.addEventListener('touchstart', mark, true);
  window.addEventListener('keydown', mark, true);
})();

/**
 * Durações em ms para `navigator.vibrate` por família ({@link mapReasonToSurfaceFamily}); arrays congelados (sem realocação por toque).
 */
const SURFACE_HAPTIC_PATTERNS = Object.freeze({
  pop: Object.freeze([16, 36, 20]),
  sink: Object.freeze([32, 28, 40]),
  shuffle: Object.freeze([18, 22, 18]),
  sift: Object.freeze([12, 28, 12, 28, 14]),
  slide: Object.freeze([20, 30, 22]),
  tilt: Object.freeze([14, 18, 14, 18, 20]),
  aura: Object.freeze([10, 20, 10, 20, 10, 25]),
  layout: Object.freeze([22, 35, 22]),
  rail: Object.freeze([18, 28, 22, 28, 20]),
  dock: Object.freeze([24, 32, 24, 38, 22]),
  screen: Object.freeze([20, 45, 28, 50, 22]),
  pdfui: Object.freeze([18, 26, 18, 26, 20]),
  tipui: Object.freeze([12, 22, 12, 22, 16]),
  alert: Object.freeze([40, 25, 40]),
  spin: Object.freeze([18, 40, 22, 35, 18]),
});

/**
 * Dispara vibração curta mapeada pela família de `kind`, se houver gesto do utilizador e API disponível.
 *
 * @param {string} kind Motivo de feedback.
 * @returns {void}
 */
function pulseCardSurfaceHaptic(kind) {
  if (!__hasUserGesture || !navigator.vibrate) return;
  const fam = mapReasonToSurfaceFamily(kind);
  const pat = SURFACE_HAPTIC_PATTERNS[fam];
  if (pat) navigator.vibrate(pat);
  else navigator.vibrate(22);
}

/** Ícone textual (uma glifo) por família superficial no toast temático. */
const SURFACE_TOAST_ICONS = Object.freeze({
  pop: '▴',
  sink: '▾',
  shuffle: '⎔',
  sift: '◎',
  slide: '↦',
  tilt: '↕',
  aura: '◉',
  layout: '▣',
  rail: '◧',
  dock: '▤',
  screen: '⛶',
  pdfui: '▤',
  tipui: 'ⓘ',
  alert: '⚠',
  spin: '✧',
  generic: '✦',
});

/** Razões em que não se mostra toast de superfície (evita spam). */
const SURFACE_TOAST_SKIP_REASONS = new Set(['random_restore', 'random_pick', 'search_toast']);

/**
 * Mapeamento `reason` → chave i18n para {@link surfaceToastMessageForReason} (exceto `page`, que usa `currentPage`).
 */
const SURFACE_TOAST_MESSAGE_KEYS = Object.freeze({
  filter_reset: 'toast.filters_reset',
  theme: 'toast.surface.theme',
  suggestions_view: 'toast.surface.suggestions_view',
  deck_view: 'toast.surface.deck_view',
  sort: 'toast.surface.sort',
  filter: 'toast.surface.filter',
  banlist_deck: 'toast.surface.banlist_deck',
  deck_add: 'toast.surface.deck_add',
  deck_remove: 'toast.surface.deck_remove',
  deck_change: 'toast.surface.deck_change',
  deck_sort: 'toast.surface.deck_sort',
  filters_column_show: 'toast.surface.filters_column_show',
  filters_column_hide: 'toast.surface.filters_column_hide',
  deck_column_hide: 'toast.surface.deck_col_hidden',
  deck_column_normal: 'toast.surface.deck_col_normal',
  deck_column_wide: 'toast.surface.deck_col_wide',
  fullscreen_enter: 'toast.surface.fullscreen_enter',
  fullscreen_exit: 'toast.surface.fullscreen_exit',
  pdf_preview_show: 'toast.surface.pdf_preview_show',
  pdf_preview_hide: 'toast.surface.pdf_preview_hide',
  tooltip_on: 'toast.surface.tooltip_on',
  tooltip_off: 'toast.surface.tooltip_off',
});

/**
 * Toast estilizado com classe por família e ícone de {@link SURFACE_TOAST_ICONS}.
 *
 * @param {string} msg Texto já resolvido (será escapado).
 * @param {string} [surfaceKind] Motivo para derivar família visual.
 * @returns {void}
 */
function showSurfaceToast(msg, surfaceKind) {
  const container = getEl('toast-container');
  if (!container || !msg) return;
  const family = mapReasonToSurfaceFamily(surfaceKind || 'generic');
  const toast = document.createElement('div');
  toast.className = `toast toast-surface toast-sfc-${family}`;
  toast.innerHTML = `<span class="toast-surface-ic" aria-hidden="true">${SURFACE_TOAST_ICONS[family] || '✦'}</span> ${escapeHtml(msg)}`;
  container.appendChild(toast);
  setTimeout(() => toast.remove(), 2200);
}

/**
 * Mensagem localizada para toast de superfície; caso `page`, inclui {@link currentPage}.
 *
 * @param {string} reason Chave lógica do evento.
 * @returns {string}
 */
function surfaceToastMessageForReason(reason) {
  if (reason === 'page') return T('toast.surface.page', { n: currentPage });
  const msgKey = SURFACE_TOAST_MESSAGE_KEYS[reason];
  return msgKey ? T(msgKey) : T('toast.surface.filter');
}

/**
 * Incrementa profundidade de supressão: {@link paintCardSurfaceEnterAnimations} não aplica animação (re-renders em cadeia).
 *
 * @returns {void}
 */
function pushSuppressCardSurfaceEnterAnimation() {
  suppressCardSurfaceEnterAnimDepth++;
}

/**
 * Decrementa a profundidade de supressão (pares com {@link pushSuppressCardSurfaceEnterAnimation}).
 *
 * @returns {void}
 */
function popSuppressCardSurfaceEnterAnimation() {
  if (suppressCardSurfaceEnterAnimDepth > 0) suppressCardSurfaceEnterAnimDepth--;
}

/** Sufixos CSS `card-surface-enter--*` correspondentes às famílias usadas em animação. */
const SFC_CARD_ANIM_SUFFIXES = [
  'pop',
  'sink',
  'shuffle',
  'sift',
  'slide',
  'tilt',
  'aura',
  'layout',
  'rail',
  'dock',
  'alert',
  'spin',
  'generic',
];

/** Coluna/elemento alvo: `filters` = col-filters||layout; `deck` = col-preview||layout; `layout` = só app-layout. */
const LAYOUT_SURFACE_PULSE_BY_REASON = Object.freeze({
  filters_column_show: Object.freeze({ target: 'filters', cls: 'layout-sfc-pulse-filters' }),
  filters_column_hide: Object.freeze({ target: 'filters', cls: 'layout-sfc-pulse-filters' }),
  deck_column_hide: Object.freeze({ target: 'deck', cls: 'layout-sfc-pulse-deck' }),
  deck_column_normal: Object.freeze({ target: 'deck', cls: 'layout-sfc-pulse-deck' }),
  deck_column_wide: Object.freeze({ target: 'deck', cls: 'layout-sfc-pulse-deck' }),
  fullscreen_enter: Object.freeze({ target: 'layout', cls: 'layout-sfc-pulse-fullscreen' }),
  fullscreen_exit: Object.freeze({ target: 'layout', cls: 'layout-sfc-pulse-fullscreen' }),
  pdf_preview_show: Object.freeze({ target: 'deck', cls: 'layout-sfc-pulse-pdf' }),
  pdf_preview_hide: Object.freeze({ target: 'deck', cls: 'layout-sfc-pulse-pdf' }),
});

/**
 * Aplica classe de pulso temporária na coluna/layout conforme {@link LAYOUT_SURFACE_PULSE_BY_REASON}.
 *
 * @param {string|null|undefined} reason Motivo de UI (colunas filtros/deck, fullscreen, PDF).
 * @returns {void}
 */
function flashLayoutSurfacePulse(reason) {
  if (!reason) return;
  const spec = LAYOUT_SURFACE_PULSE_BY_REASON[reason];
  if (!spec) return;
  const layout = getEl('app-layout');
  const colFilters = getEl('col-filters');
  const colDeck = getEl('col-preview');
  /**
   * Remove classes de pulso anteriores, força reflow e aplica `cls` por ~580 ms.
   *
   * @param {HTMLElement|null|undefined} el Alvo (coluna ou `#app-layout`).
   * @param {string} cls Uma das classes `layout-sfc-pulse-*`.
   * @returns {void}
   */
  function pulseEl(el, cls) {
    if (!el) return;
    el.classList.remove(
      'layout-sfc-pulse-filters',
      'layout-sfc-pulse-deck',
      'layout-sfc-pulse-fullscreen',
      'layout-sfc-pulse-pdf'
    );
    void el.offsetWidth;
    el.classList.add(cls);
    window.setTimeout(() => {
      el.classList.remove(cls);
    }, 580);
  }
  const el =
    spec.target === 'filters'
      ? colFilters || layout
      : spec.target === 'deck'
        ? colDeck || layout
        : layout;
  pulseEl(el, spec.cls);
}

/**
 * Aplica animação escalonada de entrada nos nós `itemSelector` dentro de `rootSelector`, conforme {@link getCardSurfacePaintKind}.
 * Respeita {@link suppressCardSurfaceEnterAnimDepth}; ignora `silent` ou ausência de motivo.
 *
 * @param {string|null|undefined} rootSelector Seletor do contentor (ex. `#results-view`).
 * @param {string} itemSelector Seletor de cada carta/item (ex. `.suggestion-item`).
 * @returns {void}
 */
function paintCardSurfaceEnterAnimations(rootSelector, itemSelector) {
  if (suppressCardSurfaceEnterAnimDepth > 0) return;
  const root = rootSelector ? document.querySelector(rootSelector) : null;
  if (!root) return;
  const items = root.querySelectorAll(itemSelector);
  const paintKind = getCardSurfacePaintKind();
  // Sem motivo explícito: não animar (evita “piscar” em re-renders encadeados — layout/lista, refit, rAF).
  // 'silent' suprime som/toast mas não deve forçar entrada genérica a cada passo.
  if (!paintKind || paintKind === 'silent') return;
  const family = mapReasonToSurfaceFamily(paintKind);
  const nSurf = items.length;
  const sfx = SFC_CARD_ANIM_SUFFIXES;
  const sfxLen = sfx.length;
  for (let si = 0; si < nSurf; si++) {
    const el = items[si];
    el.classList.remove('card-surface-enter');
    for (let sj = 0; sj < sfxLen; sj++) el.classList.remove('card-surface-enter--' + sfx[sj]);
    el.style.animationDelay = '';
  }
  requestAnimationFrame(() => {
    for (let si = 0; si < nSurf; si++) {
      const el = items[si];
      el.classList.add('card-surface-enter', 'card-surface-enter--' + family);
      el.style.animationDelay = `${Math.min(si * 26, 380)}ms`;
    }
  });
}

/**
 * Dispara feedback completo: pulso de layout (se aplicável), toast superficial, chime WebAudio e vibração.
 * `filter` / `filter_reset` executam com debounce curto.
 *
 * @param {string|null|undefined} reason Motivo; `silent` ou vazio não faz nada.
 * @returns {void}
 */
function applyCardSurfaceFeedback(reason) {
  if (!reason || reason === 'silent') return;
  const debounced = reason === 'filter' || reason === 'filter_reset';
  const run = () => {
    flashLayoutSurfacePulse(reason);
    let toastReason = reason;
    if (toastReason === 'deck_add' && window.innerWidth < 900) toastReason = null;
    if (toastReason && !SURFACE_TOAST_SKIP_REASONS.has(reason)) {
      showSurfaceToast(surfaceToastMessageForReason(toastReason), toastReason);
    }
    playCardSurfaceChime(reason);
    pulseCardSurfaceHaptic(reason);
  };
  if (debounced) {
    clearTimeout(surfaceFilterFxTimer);
    surfaceFilterFxTimer = setTimeout(() => {
      surfaceFilterFxTimer = null;
      run();
    }, 340);
    return;
  }
  run();
}

/**
 * Indica se tooltips ao hover estão ligados conforme estado do botão `#btn-toggle-tooltip`.
 *
 * @returns {boolean} Default `true` se o botão não existir no DOM.
 */
function isTooltipEnabled() {
  const btn = getEl('btn-toggle-tooltip');
  if (!btn) return true;
  return btn.classList.contains('active');
}

/**
 * Sincroniza o toggle de tooltip com `getUiPref(UI_PREF_KEYS.tooltip)`: valor vazio ou `'1'` → ligado.
 *
 * @returns {void}
 */
function applyTooltipFromPref() {
  const btn = getEl('btn-toggle-tooltip');
  if (!btn) return;
  const pref = getUiPref(UI_PREF_KEYS.tooltip);
  const on = pref === '' ? true : pref === '1';
  btn.classList.toggle('active', on);
  btn.setAttribute('aria-pressed', on ? 'true' : 'false');
  btn.title = on
    ? 'Tooltip ao passar o rato: ligado (clique para desligar)'
    : 'Tooltip ao passar o rato: desligado (clique para ligar)';
}

/**
 * Inverte estado do botão, grava pref e dispara feedback superficial (`tooltip_on` / `tooltip_off`).
 *
 * @returns {void}
 */
function toggleTooltipButton() {
  const btn = getEl('btn-toggle-tooltip');
  if (!btn) return;
  btn.classList.toggle('active');
  const on = btn.classList.contains('active');
  btn.setAttribute('aria-pressed', on ? 'true' : 'false');
  btn.title = on
    ? 'Tooltip ao passar o rato: ligado (clique para desligar)'
    : 'Tooltip ao passar o rato: desligado (clique para ligar)';
  try {
    setUiPref(UI_PREF_KEYS.tooltip, on ? '1' : '0');
  } catch (_) {}
  applyCardSurfaceFeedback(on ? 'tooltip_on' : 'tooltip_off');
}

/**
 * Mostra ou oculta a coluna de filtros (`#app-layout.filters-col-hidden`), atualiza toolbar e pref {@link UI_PREF_KEYS.filtersColVisible}.
 *
 * @param {boolean} hidden `true` para ocultar a coluna.
 * @returns {void}
 */
function applyFiltersColumnVisibility(hidden) {
  const layout = getEl('app-layout');
  const btn = getEl('btn-toggle-filters-column');
  const icon = getEl('icon-toggle-filters-column') || (btn ? btn.querySelector('i') : null);
  if (layout) layout.classList.toggle('filters-col-hidden', !!hidden);
  if (btn) {
    btn.classList.toggle('active', !hidden);
    btn.setAttribute('aria-pressed', hidden ? 'false' : 'true');
    btn.title = hidden ? 'Mostrar coluna de filtros' : 'Ocultar coluna de filtros';
  }
  // Ícone deve indicar a ação/estado seguinte (o que vai acontecer ao clicar).
  if (icon) icon.className = hidden ? 'fas fa-filter' : 'fas fa-eye-slash';
  try {
    setUiPref(UI_PREF_KEYS.filtersColVisible, hidden ? '0' : '1');
  } catch (_) {}
  try {
    refreshViewControlsHeaderCompact();
  } catch (_) {}
}

/**
 * Liga o botão `#btn-toggle-filters-column` uma vez e aplica visibilidade inicial a partir da pref guardada.
 *
 * @returns {void}
 */
function initFiltersColumnToolbar() {
  const btn = getEl('btn-toggle-filters-column');
  if (!btn || btn.dataset.init === '1') return;
  btn.dataset.init = '1';
  const vis = getUiPref(UI_PREF_KEYS.filtersColVisible);
  applyFiltersColumnVisibility(vis === '0');
  btn.addEventListener('click', () => {
    const layout = getEl('app-layout');
    const currentlyHidden = !!(layout && layout.classList.contains('filters-col-hidden'));
    applyFiltersColumnVisibility(!currentlyHidden);
    const hiddenAfter = !!(layout && layout.classList.contains('filters-col-hidden'));
    requestCardSurfaceFeedback(hiddenAfter ? 'filters_column_hide' : 'filters_column_show');
    try {
      renderResults();
    } catch (_) {}
  });
}

/**
 * Marca grupos `.filter-group` com classe `--inline-add` quando há botão stack na linha de ação (layout ajuda/desabilitado).
 *
 * @returns {void}
 */
function syncHelpDisabledInlineAddFilterLayout() {
  try {
    const filGrps = document.querySelectorAll('.sidebar-content .filter-group');
    for (let gi = 0; gi < filGrps.length; gi++) {
      const g = filGrps[gi];
      const isInlineAdd = !!g.querySelector('.filter-action-row .icon-btn-stack--tool');
      g.classList.toggle('filter-group--inline-add', isInlineAdd);
    }
  } catch (_) {}
}

/**
 * Elemento atualmente em tela cheia (prefixos vendor).
 *
 * @returns {Element|null}
 */
function getFullscreenElement() {
  return (
    document.fullscreenElement ||
    document.webkitFullscreenElement ||
    document.mozFullScreenElement ||
    document.msFullscreenElement ||
    null
  );
}

/**
 * Alterna fullscreen no `documentElement` ou sai do modo fullscreen (várias APIs vendor).
 *
 * @returns {void}
 */
function togglePageFullscreen() {
  try {
    if (getFullscreenElement()) {
      if (document.exitFullscreen) document.exitFullscreen();
      else if (document.webkitExitFullscreen) document.webkitExitFullscreen();
      else if (document.mozCancelFullScreen) document.mozCancelFullScreen();
      else if (document.msExitFullscreen) document.msExitFullscreen();
    } else {
      const el = document.documentElement;
      const req =
        el.requestFullscreen ||
        el.webkitRequestFullscreen ||
        el.mozRequestFullScreen ||
        el.msRequestFullscreen;
      if (req) {
        req.call(el);
      } else {
        showToast(T('toast.fullscreen_no'));
      }
    }
  } catch (_) {
    showToast(T('toast.fullscreen_fail'));
  }
}

/**
 * Atualiza `#btn-toggle-fullscreen`: classe ativa, ícone, `title`, `aria-*` conforme {@link getFullscreenElement}.
 *
 * @returns {void}
 */
function updateFullscreenButtonUi() {
  const btn = getEl('btn-toggle-fullscreen');
  if (!btn) return;
  const fs = !!getFullscreenElement();
  const icon = getEl('icon-toggle-fullscreen') || btn.querySelector('i');
  btn.classList.toggle('active', fs);
  btn.title = fs ? 'Sair da tela inteira (como voltar do F11)' : 'Tela inteira (como F11)';
  btn.setAttribute('aria-label', fs ? 'Sair da tela inteira' : 'Entrar em tela inteira');
  btn.setAttribute('aria-pressed', fs ? 'true' : 'false');
  if (icon) icon.className = fs ? 'fas fa-compress' : 'fas fa-expand';
}

/** Quando falso, ignoram-se escritas da pref `fullscreen` até o startup estabilizar. */
let persistFullscreenPref = false;
/** Último estado fullscreen conhecido (para detectar transição em listeners). */
let __uiFsWasFullscreen = false;
/** Timestamp até ao qual não se emite feedback superficial ao entrar/sair de fullscreen (restauração inicial). */
let __uiFsSurfaceGateUntil = 0;

/**
 * Persiste estado atual de fullscreen na pref {@link UI_PREF_KEYS.fullscreen} se {@link persistFullscreenPref} permitir.
 *
 * @returns {void}
 */
function persistFullscreenPrefNow() {
  if (!persistFullscreenPref) return;
  try {
    setUiPref(UI_PREF_KEYS.fullscreen, getFullscreenElement() ? '1' : '0');
  } catch (_) {}
}

/** Nomes de evento `fullscreenchange` em diferentes motores (WebKit/Moz/MS). */
const __fsEvNames = [
  'fullscreenchange',
  'webkitfullscreenchange',
  'mozfullscreenchange',
  'MSFullscreenChange',
];
for (let _fs = 0; _fs < __fsEvNames.length; _fs++) {
  const ev = __fsEvNames[_fs];
  document.addEventListener(ev, () => {
    updateFullscreenButtonUi();
    persistFullscreenPrefNow();
    const fs = !!getFullscreenElement();
    if (Date.now() < __uiFsSurfaceGateUntil) {
      __uiFsWasFullscreen = fs;
      return;
    }
    if (__uiFsWasFullscreen !== fs) {
      applyCardSurfaceFeedback(fs ? 'fullscreen_enter' : 'fullscreen_exit');
    }
    __uiFsWasFullscreen = fs;
  });
}
updateFullscreenButtonUi();

/** Listener singleton Escape/Enter para {@link openDeckNameModal}. */
let deckNameModalKeyHandler = null;

/**
 * Abre o modal `#deck-name-modal`, foca o input e regista callbacks até fechar.
 *
 * @param {{
 *   title?: string,
 *   defaultValue?: string|number,
 *   allowEmpty?: boolean,
 *   onCancel?: () => void,
 *   onConfirm?: (trimmedName: string, ctx: { input: HTMLInputElement, modal: HTMLElement }) => void|false
 * }} opts `onConfirm` pode retornar `false` para cancelar o fecho.
 * @returns {void}
 */
function openDeckNameModal(opts) {
  const modal = getEl('deck-name-modal');
  const input = getEl('deck-name-modal-input');
  const titleEl = getEl('deck-name-modal-title');
  const okBtn = getEl('deck-name-modal-ok');
  const cancelBtn = getEl('deck-name-modal-cancel');
  const backdrop = getEl('deck-name-modal-backdrop');
  if (!modal || !input || !titleEl || !okBtn || !cancelBtn || !backdrop) return;

  if (deckNameModalKeyHandler) {
    document.removeEventListener('keydown', deckNameModalKeyHandler);
    deckNameModalKeyHandler = null;
  }

  titleEl.textContent = opts.title || 'Nome do deck';
  input.value = opts.defaultValue != null ? String(opts.defaultValue) : '';

  /**
   * Remove listeners e estado visual do modal de nome.
   * @returns {void}
   */
  function close() {
    modal.classList.remove('is-open');
    modal.setAttribute('aria-hidden', 'true');
    okBtn.removeEventListener('click', onOk);
    cancelBtn.removeEventListener('click', onClose);
    backdrop.removeEventListener('click', onClose);
    if (deckNameModalKeyHandler) {
      document.removeEventListener('keydown', deckNameModalKeyHandler);
      deckNameModalKeyHandler = null;
    }
  }

  /**
   * Cancela edição: fecha o modal e chama `opts.onCancel` se existir.
   * @returns {void}
   */
  function onClose() {
    close();
    if (opts.onCancel) opts.onCancel();
  }

  /**
   * Confirma nome: valida vazio, chama `onConfirm` (pode abortar com `false`) e fecha.
   * @returns {void}
   */
  function onOk() {
    const t = String(input.value || '').trim();
    if (!t && !opts.allowEmpty) {
      showToast(T('toast.enter_name'));
      input.focus();
      return;
    }
    if (opts.onConfirm) {
      const ctx = { input, modal };
      const result = opts.onConfirm(t, ctx);
      if (result === false) return;
    }
    close();
  }

  /**
   * Listener global `keydown`: Escape cancela; Enter confirma como o botão OK.
   *
   * @param {KeyboardEvent} e Evento de teclado.
   * @returns {void}
   */
  deckNameModalKeyHandler = (e) => {
    if (!modal.classList.contains('is-open')) return;
    if (e.key === 'Escape') {
      e.preventDefault();
      onClose();
    } else if (e.key === 'Enter') {
      e.preventDefault();
      onOk();
    }
  };

  okBtn.addEventListener('click', onOk);
  cancelBtn.addEventListener('click', onClose);
  backdrop.addEventListener('click', onClose);
  document.addEventListener('keydown', deckNameModalKeyHandler);

  modal.classList.add('is-open');
  modal.setAttribute('aria-hidden', 'false');
  setTimeout(() => {
    input.focus();
    input.select();
  }, 0);
}

/** Listener Escape para {@link openHelpMouseModal}. */
let helpMouseModalKeyHandler = null;

/**
 * Abre o modal de ajuda ao rato/teclado (`#help-mouse-modal`), foco no botão fechar.
 *
 * @returns {void}
 */
function openHelpMouseModal() {
  const modal = getEl('help-mouse-modal');
  const closeBtn = getEl('help-mouse-modal-close');
  const backdrop = getEl('help-mouse-modal-backdrop');
  if (!modal || !closeBtn || !backdrop) return;

  if (helpMouseModalKeyHandler) {
    document.removeEventListener('keydown', helpMouseModalKeyHandler);
    helpMouseModalKeyHandler = null;
  }

  /**
   * Remove listeners e estado visual do modal de ajuda ao rato.
   * @returns {void}
   */
  function close() {
    modal.classList.remove('is-open');
    modal.setAttribute('aria-hidden', 'true');
    closeBtn.removeEventListener('click', onClose);
    backdrop.removeEventListener('click', onClose);
    if (helpMouseModalKeyHandler) {
      document.removeEventListener('keydown', helpMouseModalKeyHandler);
      helpMouseModalKeyHandler = null;
    }
  }

  /**
   * Fecha o modal de ajuda (atalho comum a botão fechar e backdrop).
   * @returns {void}
   */
  function onClose() {
    close();
  }

  /**
   * Listener global `keydown`: Escape fecha o modal de ajuda ao rato.
   *
   * @param {KeyboardEvent} e Evento de teclado.
   * @returns {void}
   */
  helpMouseModalKeyHandler = (e) => {
    if (!modal.classList.contains('is-open')) return;
    if (e.key === 'Escape') {
      e.preventDefault();
      onClose();
    }
  };

  closeBtn.addEventListener('click', onClose);
  backdrop.addEventListener('click', onClose);
  document.addEventListener('keydown', helpMouseModalKeyHandler);

  modal.classList.add('is-open');
  modal.setAttribute('aria-hidden', 'false');
  setTimeout(() => {
    try {
      closeBtn.focus();
    } catch (_) {}
  }, 0);
}

/** Evita duplicar listeners em {@link initCreditsModal}. */
let __creditsModalInitDone = false;
/** Listener Escape do modal de créditos. */
let __creditsModalKeyHandler = null;
/** Timeout que liberta o botão fechar após {@link creditsLockCloseForMs}. */
let __creditsModalUnlockTimer = null;
/** Timestamp mínimo (`Date.now()`) a partir do qual fechar é permitido; `0` = sempre. */
let __creditsCloseAllowedAt = 0;

/**
 * @returns {boolean} Se o utilizador já pode fechar o modal de créditos (após countdown opcional).
 */
function creditsIsCloseAllowed() {
  return Date.now() >= (__creditsCloseAllowedAt || 0);
}

/**
 * Mostra/oculta botão fechar e classe `credits-locked` conforme {@link creditsIsCloseAllowed}.
 *
 * @returns {void}
 */
function creditsUpdateCloseUi() {
  const modal = getEl('credits-modal');
  const closeBtn = getEl('credits-modal-close');
  if (!modal || !closeBtn) return;
  const locked = !creditsIsCloseAllowed();
  modal.classList.toggle('credits-locked', locked);
  closeBtn.style.display = locked ? 'none' : '';
}

/**
 * Impede fecho do modal de créditos durante `ms` ms (ex.: splash inicial); `0` liberta de imediato.
 *
 * @param {number} ms Duração em milissegundos.
 * @returns {void}
 */
function creditsLockCloseForMs(ms) {
  if (__creditsModalUnlockTimer) {
    clearTimeout(__creditsModalUnlockTimer);
    __creditsModalUnlockTimer = null;
  }
  const n = Number(ms || 0);
  __creditsCloseAllowedAt = n > 0 ? Date.now() + n : 0;
  creditsUpdateCloseUi();
  if (n > 0) {
    __creditsModalUnlockTimer = setTimeout(() => {
      __creditsModalUnlockTimer = null;
      creditsUpdateCloseUi();
    }, n + 30);
  }
}

/**
 * Fecha `#credits-modal` se aberto; respeita bloqueio temporal salvo que `force` seja verdadeiro.
 *
 * @param {boolean} force Ignora {@link creditsIsCloseAllowed}.
 * @returns {void}
 */
function closeCreditsModal(force) {
  const modal = getEl('credits-modal');
  if (!modal || !modal.classList.contains('is-open')) return;
  if (!force && !creditsIsCloseAllowed()) return;
  modal.classList.remove('is-open');
  modal.setAttribute('aria-hidden', 'true');
  creditsLockCloseForMs(0);
  if (__creditsModalKeyHandler) {
    document.removeEventListener('keydown', __creditsModalKeyHandler);
    __creditsModalKeyHandler = null;
  }
}

/**
 * Abre o modal de créditos; opcionalmente atrasa permissão de fecho ({@link creditsLockCloseForMs}).
 *
 * @param {{ lockCloseForMs?: number }} [opts]
 * @returns {void}
 */
function openCreditsModal(opts) {
  const modal = getEl('credits-modal');
  if (!modal) return;
  const o = opts || {};
  creditsLockCloseForMs(o.lockCloseForMs || 0);
  try {
    creditsSyncMediaVisibility();
  } catch (_) {}
  if (__creditsModalKeyHandler) {
    document.removeEventListener('keydown', __creditsModalKeyHandler);
    __creditsModalKeyHandler = null;
  }
  /**
   * Listener global `keydown`: Escape pede fecho do modal de créditos (`userInitiated=false`).
   *
   * @param {KeyboardEvent} e Evento de teclado.
   * @returns {void}
   */
  __creditsModalKeyHandler = (e) => {
    if (!modal.classList.contains('is-open')) return;
    if (e.key === 'Escape') {
      e.preventDefault();
      closeCreditsModal(false);
    }
  };
  document.addEventListener('keydown', __creditsModalKeyHandler);
  modal.classList.add('is-open');
  modal.setAttribute('aria-hidden', 'false');
  setTimeout(() => {
    try {
      getEl('credits-modal-close')?.focus();
    } catch (_) {}
  }, 0);
}

/**
 * Ajusta layout do modal quando imagens ficam ocultas (`credits-text-only`, QR, marca).
 *
 * @returns {void}
 */
function creditsSyncMediaVisibility() {
  const modal = getEl('credits-modal');
  if (!modal) return;
  let anyVisible = false;
  const credImgs = modal.querySelectorAll('img');
  for (let _cim = 0; _cim < credImgs.length; _cim++) {
    const im = credImgs[_cim];
    if (im && im.style.display !== 'none') {
      anyVisible = true;
      break;
    }
  }
  modal.classList.toggle('credits-text-only', !anyVisible);
  const qrRow = modal.querySelector('.credits-qr-row');
  if (qrRow) {
    let rowAny = false;
    const qrImgs = qrRow.querySelectorAll('img');
    for (let _qim = 0; _qim < qrImgs.length; _qim++) {
      const im = qrImgs[_qim];
      if (im && im.style.display !== 'none') {
        rowAny = true;
        break;
      }
    }
    qrRow.style.display = rowAny ? '' : 'none';
  }
  const apiLogo = modal.querySelector('.credits-api-logo');
  if (apiLogo && apiLogo.style.display === 'none') {
    // mantém só texto da API
  }
  const brand = modal.querySelector('.credits-brand-stack');
  if (brand) {
    let bAny = false;
    const brImgs = brand.querySelectorAll('img');
    for (let _bim = 0; _bim < brImgs.length; _bim++) {
      const im = brImgs[_bim];
      if (im && im.style.display !== 'none') {
        bAny = true;
        break;
      }
    }
    brand.style.display = bAny ? '' : 'none';
  }
}

/**
 * Em todas as `<img>` do modal de créditos, oculta em `error` e recalcula visibilidade ({@link creditsSyncMediaVisibility}).
 *
 * @returns {void}
 */
function creditsBindMediaFallbacks() {
  const modal = getEl('credits-modal');
  if (!modal) return;
  const cimgs = modal.querySelectorAll('img');
  for (let ci = 0; ci < cimgs.length; ci++) {
    const img = cimgs[ci];
    if (img.dataset.creditsBound === '1') continue;
    img.dataset.creditsBound = '1';
    img.addEventListener('error', () => {
      img.style.display = 'none';
      creditsSyncMediaVisibility();
    });
  }
  creditsSyncMediaVisibility();
}

/**
 * Liga fechar, backdrop, botão `#btn-credits` e fallbacks de mídia uma única vez.
 *
 * @returns {void}
 */
function initCreditsModal() {
  if (__creditsModalInitDone) return;
  const modal = getEl('credits-modal');
  const closeBtn = getEl('credits-modal-close');
  const backdrop = getEl('credits-modal-backdrop');
  if (!modal || !closeBtn || !backdrop) return;
  __creditsModalInitDone = true;

  /**
   * Fecha o modal de créditos respeitando o lock temporal (`userInitiated=false`).
   * @returns {void}
   */
  function tryClose() {
    closeCreditsModal(false);
  }

  closeBtn.addEventListener('click', tryClose);
  backdrop.addEventListener('click', tryClose);

  getEl('btn-credits')?.addEventListener('click', () => {
    openCreditsModal({ lockCloseForMs: 0 });
  });

  creditsUpdateCloseUi();
  creditsBindMediaFallbacks();
}

/** Estado global do modo ajuda (botões guia / stacks extras na toolbar). */
let uiHelpEnabled = false;

/**
 * @returns {boolean} Se o modo ajuda está ativo ({@link setHelpEnabled}).
 */
function isHelpEnabled() {
  return !!uiHelpEnabled;
}

/**
 * Aplica classe `help-enabled` em `:root` e visibilidade/ARIA do `#btn-help-toggle` e `#btn-help-mouse`.
 *
 * @returns {void}
 */
function applyHelpUi() {
  const root = document.documentElement;
  root.classList.toggle('help-enabled', isHelpEnabled());
  const btn = getEl('btn-help-toggle');
  if (btn) {
    btn.classList.toggle('active', isHelpEnabled());
    btn.setAttribute('aria-pressed', isHelpEnabled() ? 'true' : 'false');
    const k = isHelpEnabled() ? 'ui.help_toggle_on' : 'ui.help_toggle_off';
    btn.setAttribute('title', '');
    btn.setAttribute('aria-label', T(k));
  }
  const mouseBtn = getEl('btn-help-mouse');
  if (mouseBtn) {
    const wrap = mouseBtn.closest('.icon-btn-stack');
    if (wrap) wrap.style.display = isHelpEnabled() ? '' : 'none';
    else mouseBtn.style.display = isHelpEnabled() ? '' : 'none';
    mouseBtn.setAttribute('title', '');
    mouseBtn.setAttribute('aria-label', T('ui.help_mouse_btn'));
  }
}

/**
 * Define modo ajuda, persiste em `UI_PREF_KEYS.help` e chama {@link applyHelpUi}.
 *
 * @param {boolean} next Novo estado.
 * @returns {void}
 */
function setHelpEnabled(next) {
  uiHelpEnabled = !!next;
  try {
    setUiPref(UI_PREF_KEYS.help, isHelpEnabled() ? '1' : '0');
  } catch (_) {}
  applyHelpUi();
}

/** Último pedido para exibir link de referência YGOPRODeck dentro do tooltip (controlado durante o preenchimento). */
let __tooltipShowYgoprodeckRef = false;

/**
 * URL canônica da carta em ygoprodeck.com: usa `ygoprodeck_url` se host confiável; senão monta query por nome.
 *
 * @param {object|null|undefined} card Objeto carta.
 * @returns {string} URL https ou string vazia se impossível.
 */
function getYgoprodeckCardUrl(card) {
  const canon = card && card.ygoprodeck_url != null ? String(card.ygoprodeck_url).trim() : '';
  if (canon) {
    try {
      const u = new URL(canon);
      const h = u.hostname.toLowerCase();
      if (h === 'ygoprodeck.com' || h === 'www.ygoprodeck.com') return u.href;
    } catch (_) {
      /* falha de parse ou host inesperado → fallback por nome */
    }
  }
  const q = String((card && (card.name_en || card.name || '')) || '').trim();
  if (!q) return '';
  return `https://ygoprodeck.com/card/?search=${encodeURIComponent(q)}`;
}

/**
 * @param {boolean} next Se o bloco de referência ao site deve ser mostrado no próximo {@link fillTooltipData}.
 * @returns {void}
 */
function tooltipSetShowYgoprodeckRef(next) {
  __tooltipShowYgoprodeckRef = !!next;
}

/**
 * Mostra `#card-tooltip` para `card` se {@link isTooltipEnabled}; viewport &lt; 900 usa overlay fullscreen leve.
 *
 * @param {object} card Objeto carta.
 * @param {MouseEvent|TouchEvent|{ clientX?: number, clientY?: number }} e Evento de posição para {@link moveTooltip} no desktop.
 * @returns {void}
 */
function showTooltip(card, e) {
  if (!card) return;
  if (!isTooltipEnabled()) return;
  tooltipSetShowYgoprodeckRef(false);
  const tt = getEl('card-tooltip');
  if (!tt) return;
  if (window.innerWidth < 900) {
    setTimeout(() => {
      tt.style.top = '0';
      tt.style.left = '0';
      tt.style.width = '100%';
      tt.style.height = '100%';
      tt.style.transform = 'none';
      tt.style.margin = '0';
      tt.style.display = 'block';
      document.documentElement.style.overflow = 'hidden';
      document.body.style.overflow = 'hidden';
      fillTooltipData(card);
    }, 50);
    return;
  }
  tt.style.display = 'block';
  fillTooltipData(card);
  moveTooltip(e);
}

/** Mapa inglês API → rótulo PT curto nas grelhas de impressões no tooltip. */
const SET_RARITY_PT = {
  Common: 'Comum',
  Rare: 'Rara',
  'Super Rare': 'Super rara',
  'Ultra Rare': 'Ultra rara',
  'Secret Rare': 'Secret rara',
  'Ultimate Rare': 'Ultimate rara',
  'Ghost Rare': 'Ghost rara',
  'Short Print': 'Short print',
  'Super Short Print': 'Super short print',
  'Starfoil Rare': 'Starfoil rara',
  'Mosaic Rare': 'Mosaic rara',
  'Starlight Rare': 'Starlight rara',
  'Prismatic Secret Rare': 'Prismatic Secret',
  'Platinum Secret Rare': 'Platinum Secret',
  'Quarter Century Secret Rare': 'QCR Secret',
  "Collector's Rare": "Collector's rara",
  'Gold Rare': 'Gold rara',
  'Premium Gold Rare': 'Premium Gold',
  'Parallel Rare': 'Parallel rara',
  'Ghost Gold Rare': 'Ghost Gold',
  'Shatterfoil Rare': 'Shatterfoil',
  "Ultra Pharaoh's Rare": "Ultra Pharaoh's",
  'Duel Terminal Technology Common': 'DT Comum',
  'Duel Terminal Normal Parallel Rare': 'DT Normal Parallel',
  'Duel Terminal Rare Parallel Rare': 'DT Rara Parallel',
  'Duel Terminal Super Parallel Rare': 'DT Super Parallel',
  'Duel Terminal Ultra Parallel Rare': 'DT Ultra Parallel',
  'Duel Terminal Secret Parallel Rare': 'DT Secret Parallel',
};

/**
 * @param {string|null|undefined} s `set_rarity` bruto da API.
 * @returns {string} PT traduzido ou o texto original.
 */
function setRarityForTooltip(s) {
  const t = String(s || '—').trim();
  return SET_RARITY_PT[t] || t;
}

/**
 * Escolhe a raridade de impressão «melhor» entre `card_sets` (mesma heurística de score que outros picks do app).
 *
 * @param {object|null|undefined} card Objeto carta.
 * @returns {string|null} Raridade original (EN) ou `null`.
 */
function pickBestPrintingRarity(card) {
  if (!card || !Array.isArray(card.card_sets) || !card.card_sets.length) return null;
  const score = (r) => {
    const x = String(r || '').toLowerCase();
    if (x.includes('starlight')) return 110;
    if (x.includes('quarter century')) return 109;
    if (x.includes('prismatic')) return 108;
    if (x.includes('ghost')) return 107;
    if (x.includes('ultimate')) return 106;
    if (x.includes('collector')) return 105;
    if (x.includes('secret')) return 100;
    if (x.includes('ultra')) return 90;
    if (x.includes('super')) return 80;
    if (/\brare\b/.test(x)) return 70;
    if (x.includes('common')) return 10;
    return 50;
  };
  let best = null;
  let bestN = -1;
  for (const s of card.card_sets) {
    const r = String(s?.set_rarity || '').trim();
    if (!r) continue;
    const n = score(r);
    if (n > bestN) {
      bestN = n;
      best = r;
    }
  }
  return best;
}

/** Teto de linhas de `card_sets` renderizadas no tooltip; lista completa em {@link openCardSetsPanel}. */
const TOOLTIP_CARDSETS_MAX = 18;

/**
 * HTML em blocos `<div class="tt-set-line">` para painel ou trechos longos (código, raridade, preço opcional, nome expansão).
 *
 * @param {object|null|undefined} card Objeto com `card_sets`.
 * @param {number} [max] Se &gt; 0, faz `slice`; senão usa todas.
 * @returns {string} Fragmento HTML ou vazio.
 */
function formatCardSetsLinesHtml(card, max) {
  if (!card || !card.card_sets || !card.card_sets.length) return '';
  const list = typeof max === 'number' && max > 0 ? card.card_sets.slice(0, max) : card.card_sets;
  return list
    .map((s) => {
      const code = escAttr(s.set_code || '—');
      const rar = escAttr(s.set_rarity || '—');
      const sp =
        s.set_price !== undefined && s.set_price !== null && String(s.set_price).trim() !== ''
          ? ` · <span class="tt-set-price" style="opacity:0.95;">$${escAttr(String(s.set_price))}</span>`
          : '';
      const sname = s.set_name
        ? `<div style="font-size:10px;opacity:0.85;margin-top:2px;">${escAttr(s.set_name)}</div>`
        : '';
      return `<div class="tt-set-line"><span class="tt-set-code">${code}</span> — <span>${rar}</span>${sp}${sname}</div>`;
    })
    .join('');
}

/**
 * HTML compacto em células `<span class="tt-cardsets-cell">` para grelha do tooltip (raridade via {@link setRarityForTooltip}).
 *
 * @param {object|null|undefined} card Objeto com `card_sets`.
 * @param {number} [max] Limite opcional de entradas.
 * @returns {string}
 */
function formatCardSetsTooltipGridHtml(card, max) {
  if (!card || !card.card_sets || !card.card_sets.length) return '';
  const list = typeof max === 'number' && max > 0 ? card.card_sets.slice(0, max) : card.card_sets;
  return list
    .map((s) => {
      const code = escAttr(s.set_code || '—');
      const rar = escAttr(setRarityForTooltip(s.set_rarity));
      const prRaw =
        s.set_price !== undefined && s.set_price !== null && String(s.set_price).trim() !== ''
          ? `$${String(s.set_price)}`
          : '—';
      const pr = escAttr(prRaw);
      return `<span class="tt-cardsets-cell" role="listitem"><span class="tt-cardsets-code">${code}</span> <span class="tt-cardsets-rar">${rar}</span> <span class="tt-cardsets-pr">${pr}</span></span>`;
    })
    .join('');
}

/** Listener Escape singleton para {@link openCardSetsPanel}. */
let cardSetsPanelEscHandler = null;

/**
 * Abre painel lateral/modal `#card-sets-panel` com todas as impressões (prioriza cópia em {@link cardCache}).
 *
 * @param {object|null|undefined} card Objeto carta (com `id` para resolver cache).
 * @returns {void}
 */
function openCardSetsPanel(card) {
  const full = card && card.id != null && cardCache[card.id] ? cardCache[card.id] : card;
  if (!full || !full.card_sets || !full.card_sets.length) {
    showToast(T('toast.no_sets_card'));
    return;
  }
  hideTooltip();
  const panel = getEl('card-sets-panel');
  const title = getEl('card-sets-panel-title');
  const body = getEl('card-sets-panel-body');
  if (!panel || !title || !body) return;
  const cspName = displayNameForApiCard(full);
  title.textContent = T('ui.card_sets_title', { name: cspName });
  body.innerHTML = formatCardSetsLinesHtml(full);
  panel.classList.add('is-open');
  panel.setAttribute('aria-hidden', 'false');
  document.body.style.overflow = 'hidden';
  if (cardSetsPanelEscHandler) document.removeEventListener('keydown', cardSetsPanelEscHandler);
  /**
   * Listener `keydown` enquanto o painel está aberto: Escape delega a {@link closeCardSetsPanel}.
   *
   * @param {KeyboardEvent} ev Evento de teclado.
   * @returns {void}
   */
  cardSetsPanelEscHandler = (ev) => {
    if (ev.key === 'Escape') closeCardSetsPanel();
  };
  document.addEventListener('keydown', cardSetsPanelEscHandler);
  const closeBtn = getEl('card-sets-panel-close');
  if (closeBtn) closeBtn.focus();
}

/**
 * Fecha o painel de impressões, restaura scroll e remove listener Escape.
 *
 * @returns {void}
 */
function closeCardSetsPanel() {
  const panel = getEl('card-sets-panel');
  if (!panel || !panel.classList.contains('is-open')) return;
  panel.classList.remove('is-open');
  panel.setAttribute('aria-hidden', 'true');
  document.body.style.overflow = '';
  document.body.style.overflowX = 'hidden';
  if (cardSetsPanelEscHandler) {
    document.removeEventListener('keydown', cardSetsPanelEscHandler);
    cardSetsPanelEscHandler = null;
  }
}

/**
 * Handler HTML: abre painel lateral de expansões/impressões da carta.
 * @type {typeof openCardSetsPanel}
 */
window.openCardSetsPanel = openCardSetsPanel;
/**
 * Handler HTML: fecha o painel de expansões.
 * @type {typeof closeCardSetsPanel}
 */
window.closeCardSetsPanel = closeCardSetsPanel;

/**
 * Preenche `#card-tooltip`: layout mobile vs desktop, nome, imagem, beta/arquétipo, banlist, stats, texto e impressões.
 *
 * @param {object|null|undefined} card Objeto carta da API ou mesclado.
 * @returns {void}
 */
function fillTooltipData(card) {
  const tt = getEl('card-tooltip');
  if (!tt) return;
  const description = isEnglishMode()
    ? card.desc || card.desc_pt || ''
    : getUiLang() === 'pt'
      ? card.desc_pt || card.desc || ''
      : card.desc || card.desc_pt || '';
  const isMobile = window.innerWidth < 900;
  const colorKey = getTypeColorKeyFromCardType(card.type);
  const cardColor = RESULT_TYPE_COLORS[colorKey] || 'var(--accent)';
  const oldBtn = getEl('mobile-close-x');
  if (oldBtn) oldBtn.remove();
  if (isMobile) {
    tt.style.pointerEvents = 'auto';
    tt.style.setProperty('position', 'fixed', 'important');
    tt.style.setProperty('top', '0', 'important');
    tt.style.setProperty('left', '0', 'important');
    tt.style.setProperty('transform', 'none', 'important');
    tt.style.width = '100vw';
    tt.style.height = '100vh';
    tt.style.maxWidth = '100vw';
    tt.style.boxSizing = 'border-box';
    tt.style.margin = '0';
    tt.style.zIndex = '10000';
    tt.style.overflowY = 'auto';
    tt.style.borderRadius = '0';
    const closeBtn = document.createElement('button');
    closeBtn.id = 'mobile-close-x';
    closeBtn.innerHTML = '<i class="fas fa-times"></i>';
    closeBtn.onclick = (e) => {
      e.stopPropagation();
      hideTooltip();
    };
    Object.assign(closeBtn.style, {
      position: 'fixed',
      top: '15px',
      right: '15px',
      width: '35px',
      height: '35px',
      borderRadius: '50%',
      backgroundColor: 'var(--accent)',
      color: '#000',
      border: 'none',
      zIndex: '10001',
      fontSize: '18px',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      cursor: 'pointer',
      boxShadow: '0 2px 10px rgba(0,0,0,0.5)',
    });
    tt.appendChild(closeBtn);
  } else {
    tt.style.position = 'absolute';
    tt.style.height = 'auto';
    tt.style.width = '';
    tt.style.maxWidth = '';
    tt.style.top = '';
    tt.style.left = '';
    tt.style.pointerEvents = 'none';
  }
  tt.style.borderLeft = isMobile ? 'none' : `6px solid ${cardColor}`;
  const nameElement = getEl('tooltip-name');
  if (nameElement) {
    nameElement.innerText = displayNameForApiCard(card);
    nameElement.style.color = cardColor;
    nameElement.style.fontSize = isMobile ? '1.3em' : '1.0em';
    nameElement.style.fontWeight = 'bold';
  }
  const imgEl = getEl('tooltip-img');
  if (imgEl && card && card.card_images && card.card_images[0])
    imgEl.src = card.card_images[0].image_url;
  const betaRowEl = getEl('tooltip-beta-name-row');
  if (betaRowEl) {
    if (shouldShowBetaNameInTooltip(card)) {
      const beta = getCardBetaNameForTooltip(card);
      betaRowEl.innerHTML = `<span class="tt-beta-name-label">${escapeHtml(T('ui.tooltip_beta_name'))}</span><span class="tt-beta-name-value">${escapeHtml(beta)}</span>`;
      betaRowEl.style.display = 'block';
      betaRowEl.setAttribute('aria-hidden', 'false');
    } else {
      betaRowEl.innerHTML = '';
      betaRowEl.style.display = 'none';
      betaRowEl.setAttribute('aria-hidden', 'true');
    }
  }
  const archRowEl = getEl('tooltip-archetype-row');
  const archListTt = getCardArchetypes(card);
  if (archRowEl) {
    if (archListTt.length) {
      const archJoined = archListTt
        .map((a) => `<span>${escAttr(a)}</span>`)
        .join(' <span style="opacity:.55">·</span> ');
      archRowEl.innerHTML = `<span style="color:var(--accent);font-weight:600;">${T('ui.archetype_prefix')}</span> ${archJoined}`;
      archRowEl.style.display = 'block';
    } else {
      archRowEl.innerHTML = '';
      archRowEl.style.display = 'none';
    }
  }
  const banlistType = getBanlistTypeForCardBadges();
  const status = card.banlist_info ? card.banlist_info[banlistInfoKeyForType(banlistType)] : null;
  const oldBadge = document.querySelector('.tt-ban-container');
  if (oldBadge) oldBadge.remove();
  if (status && banlistType) {
    let icon = '',
      label = '',
      cssClass = '';
    if (status === 'Banned' || status === 'Forbidden') {
      icon = '<i class="fa-solid fa-ban"></i>';
      label = T('ban.banned');
      cssClass = 'tt-ban-banned';
    } else if (status === 'Limited') {
      icon = '<i class="fa-solid fa-1"></i>';
      label = T('ban.limited');
      cssClass = 'tt-ban-limited';
    } else if (status === 'Semi-Limited') {
      icon = '<i class="fa-solid fa-2"></i>';
      label = T('ban.semi');
      cssClass = 'tt-ban-semi';
    }
    const banContainer = document.createElement('div');
    banContainer.className = 'tt-ban-container';
    banContainer.innerHTML = `<div class="tt-ban-badge ${cssClass}">${icon} <span>${label}</span></div>`;
    const archAnchor = getEl('tooltip-archetype-row');
    if (archAnchor) archAnchor.after(banContainer);
    else if (nameElement) nameElement.after(banContainer);
    else tt.prepend(banContainer);
  }
  let infoHtml = `<div style="display: flex; flex-direction: column; gap: 8px; width: 100%;">`;
  const gpRawTt =
    card && card.genesys_points != null
      ? card.genesys_points
      : card && card.misc_info && card.misc_info[0] && card.misc_info[0].genesys_points != null
        ? card.misc_info[0].genesys_points
        : null;
  const gpValTt = gpRawTt == null ? null : Number(gpRawTt);
  if (Number.isFinite(gpValTt) && gpValTt > 0) {
    infoHtml += `<div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap; font-size:11px; font-weight:800; letter-spacing:.03em;">
                            <span style="display:inline-flex; align-items:center; gap:6px; padding:3px 8px; border-radius:999px; border:1px solid rgba(255,255,255,0.18); background:rgba(0,0,0,0.18);">
                                <i class="fa-solid fa-star" style="color:var(--accent); font-size:12px;"></i>
                                <span style="color:#fff;">${!siteUiIsPt() ? 'GENESYS POINTS' : 'PONTOS GENESYS'}:</span>
                                <span style="color:var(--accent);">${Math.trunc(gpValTt)}</span>
                            </span>
                        </div>`;
  }
  const mdRarityTt = pickMasterDuelRarity(card);
  if (mdRarityTt) {
    const mdIcon = masterDuelRarityIconUrl(mdRarityTt);
    const mdBg =
      mdRarityTt === 'UR'
        ? 'rgba(168, 85, 247, 0.18)'
        : mdRarityTt === 'SR'
          ? 'rgba(249, 115, 22, 0.18)'
          : mdRarityTt === 'R'
            ? 'rgba(59, 130, 246, 0.18)'
            : 'rgba(148, 163, 184, 0.18)';
    const mdBd =
      mdRarityTt === 'UR'
        ? 'rgba(168, 85, 247, 0.38)'
        : mdRarityTt === 'SR'
          ? 'rgba(249, 115, 22, 0.38)'
          : mdRarityTt === 'R'
            ? 'rgba(59, 130, 246, 0.38)'
            : 'rgba(148, 163, 184, 0.38)';
    infoHtml += `<div style="display:flex; align-items:center; gap:8px; flex-wrap:wrap; font-size:11px; font-weight:900; letter-spacing:.03em;">
                            <span style="display:inline-flex; align-items:center; gap:8px; padding:3px 10px; border-radius:999px; border:1px solid ${mdBd}; background:${mdBg};">
                                <span style="opacity:.9;">MASTER DUEL</span>
                                <span style="display:inline-flex; align-items:center; gap:6px; background:rgba(0,0,0,0.18); border:1px solid rgba(255,255,255,0.14); padding:2px 8px; border-radius:999px; font-variant-numeric:tabular-nums;">
                                    <img src="${escAttr(mdIcon)}" alt="${escAttr(mdRarityTt)}" style="width:16px;height:16px;object-fit:contain;vertical-align:-2px;">
                                    <span>${escapeHtml(mdRarityTt)}</span>
                                </span>
                            </span>
                        </div>`;
  }
  // (MD) Tooltip: manter só a primeira linha (Master Duel).
  const ft = getFrameType(card);
  const cardTypeRawTt = String(card.type || '');
  const cardTypeUTt = cardTypeRawTt.toUpperCase();
  const cardTypeLTt = cardTypeRawTt.toLowerCase();
  const isLinkTt = frameTypeIsLink(ft) || cardTypeLTt.includes('link');
  if (
    card.attribute ||
    frameTypeIsSpell(ft) ||
    frameTypeIsTrap(ft) ||
    cardTypeRawTt.includes('Spell') ||
    cardTypeRawTt.includes('Trap')
  ) {
    let iconUrl =
      frameTypeIsSpell(ft) || cardTypeRawTt.includes('Spell')
        ? STATIC_ICON_SPELL_FRAME_SVG
        : frameTypeIsTrap(ft) || cardTypeRawTt.includes('Trap')
          ? STATIC_ICON_TRAP_FRAME_SVG
          : ygoAttribIconUrl(sanitizeYgoCdnAttribFileSegment(card.attribute));
    let labelText =
      frameTypeIsSpell(ft) || cardTypeRawTt.includes('Spell')
        ? T('ui.spell_attr')
        : frameTypeIsTrap(ft) || cardTypeRawTt.includes('Trap')
          ? T('ui.trap_attr')
          : attrDisplayName(card.attribute ? card.attribute.toUpperCase() : '');
    infoHtml += `<div style="display: flex; align-items: center; flex-wrap: wrap; gap: 8px;">
                            <div style="display: flex; align-items: center; gap: 4px; color: #ffffff;">
                                <img src="${escAttr(iconUrl)}" style="width:20px; height:20px; object-fit:contain;">
                                <span>${escapeHtml(labelText)}</span>
                            </div>`;
    if (cardHasPendulumScale(card)) {
      infoHtml += getPendulumScaleHtml(card.scale, isMobile ? 16 : 15);
    }
    if ((card.level || card.rank) && !isLinkTt) {
      infoHtml += `<div style="display: flex; align-items: center; gap: 4px; color: #ffffff; margin-left: 5px;">
                                <img src="${escAttr(starIcon)}" style="width:16px; height:16px; ${frameTypeIsXyz(ft) || cardTypeUTt.includes('XYZ') ? 'filter:invert(1) brightness(0.5);' : ''}">
                                <span>${escapeHtml(String(card.level != null ? card.level : card.rank != null ? card.rank : ''))}</span>
                            </div>`;
    }
    if (isLinkTt && card.linkmarkers && card.linkmarkers.length) {
      infoHtml += `<div style="display: flex; align-items: center; margin-left: 4px;">${getLinkMarkersHtml(card.linkmarkers, isMobile ? 17 : 16)}</div>`;
    }
    infoHtml += `</div>`;
  }
  let tipoTexto = formatCardTypeForUi(card.type);
  const raceTraduzida = !siteUiIsPt()
    ? card.race || T('ui.race_unknown')
    : RACE_PT_LABEL[card.race] || card.race || T('ui.race_unknown');
  infoHtml += `<div class="card-race-type-row" style="color: #ffffff; font-size: 11px; margin-bottom: 8px;">
                        <span>[</span>
                        <span class="card-race-type-group card-race-type-group--with-slash">
                        <img src="${escAttr(ygoRaceIconUrl(card.race))}" style="width: 14px; height: 14px;" onerror="this.style.display='none'">
                        <span>${escapeHtml(String(raceTraduzida ?? ''))}</span>
                        </span>
                        <span class="card-race-type-group">
                        <img src="${escAttr(ygoMonsterTypeIconUrl(card.type))}" style="width: 14px; height: 14px; border-radius: 2px;" onerror="this.style.display='none'">
                        <span>${escapeHtml(String(tipoTexto ?? ''))}</span>
                        </span>
                        <span> ]</span>
                    </div>`;
  if (card.atk !== undefined) {
    infoHtml += `
            <div style="display: flex; gap: 15px; margin-bottom: 8px; font-size: 13px; font-weight: bold;">
                <div style="display: flex; align-items: center; gap: 5px;">
                    <i class="fas fa-fist-raised" style="color: #4d94ff;"></i>
                    <span style="color: #4d94ff;">ATK/</span>
                    <span style="color: #ffffff;">${escapeHtml(String(card.atk != null ? card.atk : ''))}</span>
                </div>
                ${
                  !isLinkTt
                    ? `
                    <div style="display: flex; align-items: center; gap: 5px;">
                        <i class="fas fa-shield-alt" style="color: #ff4d4d;"></i>
                        <span style="color: #ff4d4d;">DEF/</span>
                        <span style="color: #ffffff;">${escapeHtml(String(card.def != null ? card.def : ''))}</span>
                    </div>
                `
                    : `
                    <div style="display: flex; align-items: center; gap: 5px; color: #ffffff;">
                        <span>LINK-${escapeHtml(String(card.linkval != null ? card.linkval : ''))}</span>
                    </div>
                `
                }
            </div>`;
  }
  infoHtml += `</div>`;
  setHtml('tooltip-info-rows', infoHtml);
  let tcgDate = 'N/A',
    ocgDate = 'N/A';
  if (card.misc_info && card.misc_info[0]) {
    tcgDate =
      typeof formatDateBR !== 'undefined'
        ? formatDateBR(card.misc_info[0].tcg_date)
        : card.misc_info[0].tcg_date;
    ocgDate =
      typeof formatDateBR !== 'undefined'
        ? formatDateBR(card.misc_info[0].ocg_date)
        : card.misc_info[0].ocg_date;
  }
  const p = getCardPricesFirst(card) || {};
  const formatP = (val) => (!val || floatNum(val, NaN) === 0 ? T('price.not_found') : `$${val}`);
  const cardIdDisplay = card.id !== undefined && card.id !== null ? String(card.id) : '—';
  const konamiRaw =
    card.misc_info &&
    card.misc_info[0] &&
    card.misc_info[0].konami_id != null &&
    card.misc_info[0].konami_id !== ''
      ? String(card.misc_info[0].konami_id)
      : '';
  const konamiDisplay = konamiRaw ? escapeHtml(konamiRaw) : '—';
  const idHtml = `<div class="tt-card-id-row">
            <span class="tt-card-id-pair"><span class="tt-card-id-label">ID</span><span class="tt-card-id-value">${escapeHtml(String(cardIdDisplay))}</span></span>
            <span class="tt-card-id-pair"><span class="tt-konami-id-label">Konami</span><span class="tt-konami-id-value">${konamiDisplay}</span></span>
        </div>`;
  const gpRaw =
    card && card.genesys_points != null
      ? card.genesys_points
      : card && card.misc_info && card.misc_info[0] && card.misc_info[0].genesys_points != null
        ? card.misc_info[0].genesys_points
        : null;
  const gpVal = gpRaw == null ? null : Number(gpRaw);
  const genesysHtml =
    Number.isFinite(gpVal) && gpVal > 0
      ? `<div class="tt-card-id-row" style="margin-top:6px;">
                   <span class="tt-card-id-pair">
                       <span class="tt-card-id-label">${!siteUiIsPt() ? 'Genesys Points' : 'Pontos Genesys'}</span>
                       <span class="tt-card-id-value">${Math.trunc(gpVal)}</span>
                   </span>
               </div>`
      : '';
  const rawFormats =
    card.misc_info && card.misc_info[0] && Array.isArray(card.misc_info[0].formats)
      ? card.misc_info[0].formats
      : Array.isArray(card.formats)
        ? card.formats
        : null;
  let formatsHtml = '';
  if (rawFormats && rawFormats.length) {
    const seen = new Set();
    const list = [];
    for (const f of rawFormats) {
      const s = String(f == null ? '' : f).trim();
      if (!s || seen.has(s)) continue;
      seen.add(s);
      list.push(s);
    }
    if (list.length) {
      const chips = list
        .map(
          (s, i) => `<span class="tt-format-chip tt-format-chip--c${i % 8}">${escapeHtml(s)}</span>`
        )
        .join('');
      formatsHtml = `<div class="tt-tooltip-formats">
                    <span style="color:var(--accent);font-weight:600;">${escapeHtml(T('ui.tooltip_formats'))}</span>
                    <div class="tt-formats-badges">${chips}</div>
                </div>`;
    }
  }
  const datesHtml = `<div class="tt-tooltip-dates"><span>📅 TCG: ${escapeHtml(String(tcgDate))}</span><span>📅 OCG: ${escapeHtml(String(ocgDate))}</span></div>`;
  const separatorHtml = `<hr style="border: 0; border-top: 1px solid #444; margin: 4px 0; opacity: 1;">`;
  const pricesHtml = `<div style="margin-top: 4px; display: flex; flex-wrap: wrap; gap: 8px; font-size: 11px; color: #fff; font-weight: 500;">
            <span title="TCGPlayer"><i class="fa-solid fa-store" style="color:var(--accent); font-size: 11px;"></i> TCG: ${escapeHtml(formatP(p.tcgplayer_price))}</span>
            <span title="Cardmarket"><i class="fa-solid fa-m" style="color:var(--accent); font-size: 11px;"></i> CM: ${escapeHtml(formatP(p.cardmarket_price))}</span>
            <span title="CoolStuffInc"><i class="fa-solid fa-bag-shopping" style="color:var(--accent); font-size: 11px;"></i> CSI: ${escapeHtml(formatP(p.coolstuffinc_price))}</span>
            <span title="eBay"><i class="fa-brands fa-ebay" style="color:var(--accent); font-size: 14px;"></i> ${escapeHtml(formatP(p.ebay_price))}</span>
            <span title="Amazon"><i class="fa-brands fa-amazon" style="color:var(--accent); font-size: 13px;"></i> ${escapeHtml(formatP(p.amazon_price))}</span>
        </div>`;
  const ygoRefUrl = __tooltipShowYgoprodeckRef ? getYgoprodeckCardUrl(card) : '';
  const ygoRefHtml = ygoRefUrl
    ? `<div style="margin-top: 10px; display:flex; justify-content:flex-end;">
                    <a href="${escAttr(ygoRefUrl)}" target="_blank" rel="noopener noreferrer" style="display:inline-flex; align-items:center; gap:8px; font-size:11px; color: var(--accent); text-decoration:none; font-weight:600;">
                        <i class="fa-solid fa-arrow-up-right-from-square"></i>
                        <span>${!siteUiIsPt() ? 'View on YGOPRODeck' : 'Ver no YGOPRODeck'}</span>
                    </a>
               </div>`
    : '';
  let setsBlock = '';
  if (card.card_sets && card.card_sets.length) {
    const nSets = card.card_sets.length;
    const setsCountLabel =
      nSets > TOOLTIP_CARDSETS_MAX
        ? T('ui.sets_partial', { max: TOOLTIP_CARDSETS_MAX, total: nSets })
        : String(nSets);
    const lines = formatCardSetsLinesHtml(card, TOOLTIP_CARDSETS_MAX);
    const printsHead = `${T('ui.prints_sets_head')} `;
    if (isMobile) {
      setsBlock = `<div class="tt-cardsets-block">
                    <div class="tt-cardsets-head">
                        <span style="font-weight:bold;color:var(--accent);"><i class="fa-solid fa-layer-group"></i> ${printsHead}<span style="opacity:0.85;font-weight:600;">(${setsCountLabel})</span></span>
                    </div>
                    <div class="tt-cardsets-scroll" tabindex="0" role="region" aria-label="${escAttr(T('ui.csp_scroll_aria'))}">${lines}</div>
                </div>`;
    } else {
      const gridInner = formatCardSetsTooltipGridHtml(card, TOOLTIP_CARDSETS_MAX);
      setsBlock = `<div class="tt-cardsets-block tt-cardsets-block--compact"><div class="tt-cardsets-head"><span style="font-weight:bold;color:var(--accent);"><i class="fa-solid fa-layer-group"></i> ${printsHead}<span style="opacity:0.85;font-weight:600;">(${setsCountLabel})</span></span></div><div class="tt-cardsets-grid" role="list" aria-label="${escAttr(T('ui.csp_prints_aria'))}">${gridInner}</div></div>`;
    }
  }
  let formattedDescription = escapeHtml(description).replace(/\n/g, '<br>');
  formattedDescription = formattedDescription.replace(/(?:<br\s*\/?>|\s)+$/gi, '');
  setHtml(
    'tooltip-text',
    `<div class="tt-tooltip-desc" style="word-wrap: break-word;">${formattedDescription}</div>${setsBlock}${idHtml}${genesysHtml}${formatsHtml}${datesHtml}${separatorHtml}${pricesHtml}${ygoRefHtml}`
  );
}

/**
 * Posiciona `#card-tooltip` junto ao cursor (offset fixo), invertendo para caber na viewport — ignorado em viewport &lt; 900.
 *
 * @param {MouseEvent|{ clientX: number, clientY: number }} e Evento com coordenadas de cliente.
 * @returns {void}
 */
function moveTooltip(e) {
  if (window.innerWidth < 900) return;
  const tt = getEl('card-tooltip');
  if (!tt) return;
  if (tt.style.display !== 'block') return;
  const ttHeight = tt.offsetHeight;
  const ttWidth = tt.offsetWidth;
  let x = e.clientX + 25;
  let y = e.clientY + 15;
  if (x + ttWidth > window.innerWidth) x = e.clientX - ttWidth - 25;
  if (y + ttHeight > window.innerHeight) y = window.innerHeight - ttHeight - 15;
  if (y < 10) y = 10;
  tt.style.left = x + 'px';
  tt.style.top = y + 'px';
}

/**
 * Oculta o tooltip e restaura overflow de `html`/`body` após modo mobile fullscreen.
 *
 * @returns {void}
 */
function hideTooltip() {
  const tt = getEl('card-tooltip');
  if (tt) tt.style.display = 'none';
  document.documentElement.style.overflow = '';
  document.body.style.overflow = '';
  document.body.style.overflowX = 'hidden';
}

/** Listener Escape do modal de detalhes. */
let tooltipDetailsModalEscHandler = null;
/** `{ parent, nextSibling }` para devolver `#card-tooltip` ao DOM original em {@link closeTooltipDetailsModal}. */
let tooltipDetailsModalRestoreCtx = null;
/** Último elemento focado antes de abrir o modal (restauro de acessibilidade). */
let tooltipDetailsModalRestoreFocusEl = null;

/**
 * Move o mesmo nó `#card-tooltip` para dentro do modal, repreenche dados e bloqueia scroll do `body`.
 *
 * @param {object|null|undefined} card Carta cujo tooltip se mostra em formato expandido.
 * @returns {void}
 */
function openTooltipDetailsModal(card) {
  if (!card) return;
  const modal = getEl('tooltip-details-modal');
  const backdrop = getEl('tooltip-details-modal-backdrop');
  const closeBtn = getEl('tooltip-details-modal-close');
  const body = getEl('tooltip-details-modal-body');
  const tt = getEl('card-tooltip');
  if (!modal || !backdrop || !closeBtn || !body || !tt) return;

  hideTooltip();
  tooltipDetailsModalRestoreFocusEl =
    document.activeElement instanceof HTMLElement ? document.activeElement : null;

  if (!tooltipDetailsModalRestoreCtx) {
    tooltipDetailsModalRestoreCtx = {
      parent: tt.parentNode,
      nextSibling: tt.nextSibling,
    };
  }

  body.innerHTML = '';
  body.appendChild(tt);
  tt.classList.add('tt-in-modal');
  tt.style.display = 'block';
  tt.style.pointerEvents = 'auto';
  tt.style.position = 'static';
  tt.style.top = '';
  tt.style.left = '';
  tt.style.transform = '';
  tt.style.margin = '0';
  tt.style.width = '100%';
  tt.style.maxWidth = 'none';
  tt.style.height = 'auto';
  tt.style.maxHeight = 'none';

  fillTooltipData(card);

  modal.classList.add('is-open');
  modal.setAttribute('aria-hidden', 'false');
  // 'inert' previne foco/interação quando fechado (e evita warning de aria-hidden com foco)
  modal.inert = false;
  document.body.style.overflow = 'hidden';

  /**
   * Fecha o modal de detalhes do tooltip (mesmo fluxo que botão fechar e backdrop).
   * @returns {void}
   */
  const onClose = () => closeTooltipDetailsModal();
  backdrop.onclick = onClose;
  closeBtn.onclick = onClose;

  if (tooltipDetailsModalEscHandler)
    document.removeEventListener('keydown', tooltipDetailsModalEscHandler);
  /**
   * Listener global `keydown`: Escape fecha o tooltip expandido se o modal estiver aberto.
   *
   * @param {KeyboardEvent} ev Evento de teclado.
   * @returns {void}
   */
  tooltipDetailsModalEscHandler = (ev) => {
    if (!modal.classList.contains('is-open')) return;
    if (ev.key === 'Escape') {
      ev.preventDefault();
      closeTooltipDetailsModal();
    }
  };
  document.addEventListener('keydown', tooltipDetailsModalEscHandler);
  closeBtn.focus();
}

/**
 * Fecha o modal, reparenta o tooltip, limpa estilos `tt-in-modal` e restaura foco/overflow.
 *
 * @returns {void}
 */
function closeTooltipDetailsModal() {
  const modal = getEl('tooltip-details-modal');
  const body = getEl('tooltip-details-modal-body');
  const tt = getEl('card-tooltip');
  if (!modal || !body || !tt) return;
  if (!modal.classList.contains('is-open')) return;

  // Antes de esconder/inertar, tira o foco de dentro do modal
  const active = document.activeElement;
  if (active && modal.contains(active)) {
    if (tooltipDetailsModalRestoreFocusEl && tooltipDetailsModalRestoreFocusEl.isConnected) {
      tooltipDetailsModalRestoreFocusEl.focus();
    } else {
      document.body.focus?.();
    }
  }

  modal.classList.remove('is-open');
  modal.setAttribute('aria-hidden', 'true');
  modal.inert = true;
  tooltipSetShowYgoprodeckRef(false);

  tt.classList.remove('tt-in-modal');
  tt.style.display = 'none';
  tt.style.pointerEvents = '';
  tt.style.position = '';
  tt.style.top = '';
  tt.style.left = '';
  tt.style.transform = '';
  tt.style.margin = '';
  tt.style.width = '';
  tt.style.maxWidth = '';
  tt.style.height = '';
  tt.style.maxHeight = '';

  if (tooltipDetailsModalRestoreCtx && tooltipDetailsModalRestoreCtx.parent) {
    const { parent, nextSibling } = tooltipDetailsModalRestoreCtx;
    if (nextSibling && nextSibling.parentNode === parent) parent.insertBefore(tt, nextSibling);
    else parent.appendChild(tt);
  }
  body.innerHTML = '';

  document.body.style.overflow = '';
  document.body.style.overflowX = 'hidden';
  document.documentElement.style.overflow = '';

  if (tooltipDetailsModalEscHandler) {
    document.removeEventListener('keydown', tooltipDetailsModalEscHandler);
    tooltipDetailsModalEscHandler = null;
  }
}

/**
 * Handler HTML: abre modal de detalhe expandido do tooltip da carta.
 * @type {typeof openTooltipDetailsModal}
 */
window.openTooltipDetailsModal = openTooltipDetailsModal;
/**
 * Handler HTML: fecha o modal de detalhe do tooltip.
 * @type {typeof closeTooltipDetailsModal}
 */
window.closeTooltipDetailsModal = closeTooltipDetailsModal;

/**
 * Colunas efetivas da `grid` em modo lista de sugestões (definidas por {@link fitResultsListLayoutAfterRender}).
 */
let resultsListColsOverride = null;
/**
 * Itens por “página” em modo lista quando o layout foi ajustado ao contêiner ({@link fitResultsListLayoutAfterRender}).
 */
let resultsItemsPerPageOverride = null;
/** Evita reentrância ao medir DOM durante o ajuste de lista. */
let __fittingResultsListLayout = false;
/**
 * Chave estável do layout (painéis + dimensões) para não recalcular colunas/itens a cada paginação sem mudança real.
 */
let __resultsListLayoutKey = null;
/** Marcação para re-render pendente após ajuste de colunas/itens. */
let __resultsListRerenderQueued = false;
/** Tentativas de correção pós-fullscreen para evitar cortar última linha da lista. */
let __resultsListFullscreenFixTries = 0;

/** Teto de colunas no modo lista (evita cartas estreitas demais em telas largas). */
const RESULTS_LIST_MAX_COLS = 6;

/**
 * Classe CSS do contentor `#results-view` conforme modo de vista (lista vs grelha, listagem recortada).
 *
 * @param {string|undefined} [viewModeOpt] Modo ({@link currentView} se omitido).
 * @returns {string} Classes em cadeia (`results-view`, sufixos de layout).
 */
function buildMainResultsViewClassName(viewModeOpt) {
  const vMode = normalizeViewMode4(viewModeOpt ?? currentView, 'list');
  const vLayout = viewModeLayout(vMode);
  const croppedListClass = vLayout === 'list' && viewModeIsCropped(vMode) ? ' cropped-list' : '';
  return `results-view ${vLayout}-mode${croppedListClass}`;
}

/**
 * Largura mínima desejada por coluna ao calcular `repeat(N, minmax(...))` na lista.
 *
 * @returns {number} Pixels.
 */
function getResultsListMinColPx() {
  return 260;
}

/**
 * Altura-alvo de cada cartão na lista para estimar linhas por página (alinhar a CSS `--list-suggestion-art-max-h` + padding).
 *
 * @returns {number} Pixels.
 */
function getResultsListTargetItemH() {
  if (viewModeLayout(currentView) !== 'list') return 133;
  return viewModeIsCropped(currentView) ? 156 : 133;
}

/**
 * Conta colunas efetivas da grelha CSS de `#results-view` a partir de `grid-template-columns`.
 *
 * @param {HTMLElement|null|undefined} rv Elemento vista de resultados.
 * @returns {number} Pelo menos 1.
 */
function getResultsViewColumnCount(rv) {
  if (!rv) return 1;
  const rvStyle = window.getComputedStyle(rv);
  const colsRaw = String(rvStyle.gridTemplateColumns || '').trim();
  if (!colsRaw) return 1;
  return Math.max(1, countWhitespaceSeparatedTokens(colsRaw) || 1);
}

/**
 * Define `grid-template-columns` em `rv` e grava {@link resultsListColsOverride} (limitado por {@link RESULTS_LIST_MAX_COLS}).
 *
 * @param {HTMLElement|null|undefined} rv Contentor lista.
 * @param {number} cols Número de colunas desejado.
 * @returns {void}
 */
function applyResultsListCols(rv, cols) {
  if (!rv) return;
  const c = Math.max(1, Math.min(RESULTS_LIST_MAX_COLS, int10(cols, 1) || 1));
  resultsListColsOverride = c;
  rv.style.gridTemplateColumns = `repeat(${c}, minmax(${getResultsListMinColPx()}px, 1fr))`;
}

/**
 * Remove overrides de grelha e estado de fitting (ex.: ao sair do modo lista).
 *
 * @param {HTMLElement|null|undefined} rv Contentor vista de resultados.
 * @returns {void}
 */
function clearResultsListOverrides(rv) {
  resultsListColsOverride = null;
  resultsItemsPerPageOverride = null;
  __resultsListLayoutKey = null;
  __resultsListFullscreenFixTries = 0;
  if (rv) rv.style.gridTemplateColumns = '';
}

/**
 * Chave string do contexto visual atual (filtros/deck ocultos ou largos, crop, dimensões) para memoizar layout.
 *
 * @returns {string}
 */
function getResultsListLayoutKey() {
  const rv = getEl('results-view');
  const layout = getEl('app-layout');
  const filtersHidden = !!(layout && layout.classList.contains('filters-col-hidden'));
  const deckHidden = !!(layout && layout.classList.contains('deck-col-hidden'));
  const deckWide = !!(layout && layout.classList.contains('deck-col-wide'));
  const w = rv ? Math.round(rv.clientWidth) : 0;
  const h = rv ? Math.round(rv.clientHeight) : 0;
  return [
    'list',
    filtersHidden ? 'fh1' : 'fh0',
    deckHidden ? 'dh1' : 'dh0',
    deckWide ? 'dw1' : 'dw0',
    viewModeIsCropped(currentView) ? 'cr1' : 'cr0',
    'w' + w,
    'h' + h,
  ].join('|');
}

/**
 * Após render, calcula colunas e itens por página da lista para preencher o contêiner sem scroll (com teto de segurança).
 *
 * @returns {boolean} `true` se colunas ou `perPage` mudaram e convém re-renderizar.
 */
function fitResultsListLayoutAfterRender() {
  if (__fittingResultsListLayout) return false;
  const rv = getEl('results-view');
  if (!rv) return false;
  if (viewModeLayout(currentView) !== 'list') {
    clearResultsListOverrides(rv);
    return false;
  }
  const rvStyle = window.getComputedStyle(rv);
  if (rvStyle.display !== 'grid') return false;
  const sample = rv.querySelector('.suggestion-item');
  if (!sample) return false;

  const layoutKey = getResultsListLayoutKey();
  // Se o layout mudou (resize/painéis), libera recálculo. Caso contrário, mantém estável entre páginas.
  const layoutChanged = __resultsListLayoutKey !== layoutKey;
  if (layoutChanged) {
    resultsListColsOverride = null;
    resultsItemsPerPageOverride = null;
    __resultsListLayoutKey = layoutKey;
  }

  // Se já temos overrides para este layout, não recalcula de novo a cada mudança de página.
  if (!layoutChanged && resultsListColsOverride != null && resultsItemsPerPageOverride != null)
    return false;

  __fittingResultsListLayout = true;
  try {
    // 1) Colunas: baseado em largura mínima por card (estável e legível).
    const rvStyle = window.getComputedStyle(rv);
    const colGap = floatNum(rvStyle.columnGap || rvStyle.gap || '0', NaN) || 0;
    const availW = rv.clientWidth;
    const minColPx = getResultsListMinColPx();
    let cols = Math.floor((availW + colGap) / (minColPx + colGap));
    cols = Math.max(1, Math.min(RESULTS_LIST_MAX_COLS, cols || 1));

    // 2) Altura: calcula rows por altura-alvo (estável entre páginas e aproveita melhor o espaço).
    const rowGap = floatNum(rvStyle.rowGap || rvStyle.gap || '0', NaN) || 0;
    const availH = rv.clientHeight;
    // margem de segurança evita cortar a última linha (especialmente em fullscreen/zoom)
    const safeH = Math.max(0, availH - 24);
    const targetItemH = getResultsListTargetItemH();
    let rows = Math.max(1, Math.floor((safeH + rowGap) / (targetItemH + rowGap)));
    // Evita "1 linha" quando claramente cabe 2.
    if (rows < 2 && safeH >= targetItemH * 2 + rowGap) rows = 2;
    rows = Math.max(1, Math.min(6, rows));
    const maxLimit = 300;
    let perPage = Math.min(maxLimit, Math.max(cols, cols * rows));

    // Caso a lista atual não tenha itens suficientes para preencher (última página), não força grow aqui.
    const prevCols = resultsListColsOverride;
    const prevPerPage = resultsItemsPerPageOverride;
    applyResultsListCols(rv, cols);
    resultsItemsPerPageOverride = perPage;

    // Correção: em fullscreen, qualquer overflow corta a última linha (sem scrollbar).
    // O ajuste final (reduzir 1 linha) é aplicado no pós-render (ver renderResults),
    // porque aqui ainda estamos durante o mesmo ciclo de render.
    return layoutChanged || prevCols !== cols || prevPerPage !== perPage;
  } finally {
    __fittingResultsListLayout = false;
  }
}

/**
 * Quantidade de cartas por página na vista de sugestões (`#results-view`).
 * Em modo lista, após {@link fitResultsListLayoutAfterRender}, usa {@link resultsItemsPerPageOverride} quando definido.
 * Caso contrário combina ciclo da coluna do deck, filtros ocultos, fullscreen, medição opcional da grelha no desktop,
 * vista lista vs grelha e regras mobile/desktop (teto 300).
 *
 * @returns {number} Pelo menos 1; no máximo 300.
 */
function getItemsPerPage() {
  if (viewModeLayout(currentView) === 'list' && resultsItemsPerPageOverride != null) {
    const n = int10(resultsItemsPerPageOverride, NaN);
    if (Number.isFinite(n) && n >= 1) return Math.min(300, n);
  }
  /**
   * Colunas efetivas por estado de layout (lista vs grelha, filtros ocultos, ciclo do deck).
   *
   * @param {boolean} isMobile Viewport menor que 900 px (regras compartilhadas com desktop neste helper).
   * @param {number} d `deckColumnCycle` (0 = deck oculto, 1 = normal, 2 = wide).
   * @param {boolean} filtersHidden Se `.filters-col-hidden` está ativo em `#app-layout`.
   * @param {string} currentView Vista atual (`list`, `grid`, …) — para lista usa ramo próprio.
   * @returns {number} Itens por linha (aproximação para cálculo de página).
   */
  function getItemsPerRowForCurrentLayout(isMobile, d, filtersHidden, currentView) {
    if (currentView === 'list') {
      // A "lista" aqui é uma grade de linhas; 1 linha extra em fullscreen = +colunas.
      if (filtersHidden) {
        // Desktop: deck oculto = 6 col; deck normal = 5 col; deck wide = 3 col.
        // Mobile: mantemos a mesma regra para não depender de medir DOM.
        if (d === 0) return 6;
        if (d === 1) return 5;
        return 3;
      }
      // Sem filtros ocultos: deck oculto = 5 col; deck normal = 3 col; deck wide = 2 col.
      if (d === 0) return 5;
      if (d === 1) return 3;
      return 2;
    }

    // Grid: colunas desktop já estão descritas no comentário (10/7/5).
    // Com filtros ocultos, a UI aumenta a grade (9/12/7 etc.), mas o "bonus" atual já cobre a troca de colunas.
    // Para o incremento de fullscreen queremos sempre "mais 1 linha", então usamos as colunas efetivas por estado.
    if (filtersHidden) {
      if (d === 0) return 12; // filters hidden + deck hidden
      if (d === 1) return 9; // filters hidden + deck normal
      return 7; // filters hidden + deck wide
    }
    if (d === 0) return 10;
    if (d === 1) return 7;
    return 5;
  }

  /**
   * Mede colunas/altura na grelha real de `#results-view` para estimar itens por página (desktop).
   *
   * @param {boolean} isMobile Em mobile este caminho é desativado (`null`).
   * @returns {number|null} Produto colunas×linhas cabíveis ou `null` se não for grelha/medida válida.
   */
  function tryComputeItemsPerPageFromViewport(isMobile) {
    if (isMobile) return null;
    const rv = getEl('results-view');
    if (!rv) return null;
    const rvStyle = window.getComputedStyle(rv);
    if (rvStyle.display !== 'grid') return null;

    // Quantas colunas a grade está efetivamente usando agora.
    const colsRaw = String(rvStyle.gridTemplateColumns || '').trim();
    if (!colsRaw) return null;
    const cols = countWhitespaceSeparatedTokens(colsRaw) || 1;

    // Altura real de um item (inclui variações por device/zoom/texto).
    const sample = rv.querySelector('.suggestion-item');
    if (!sample) return null;
    const itemH = sample.getBoundingClientRect().height;
    if (!Number.isFinite(itemH) || itemH < 10) return null;

    const rowGap = floatNum(rvStyle.rowGap || rvStyle.gap || '0', NaN) || 0;
    const availH = rv.clientHeight;
    if (!Number.isFinite(availH) || availH < 40) return null;

    const rows = Math.max(1, Math.floor((availH + rowGap) / (itemH + rowGap)));
    const perPage = cols * rows;
    if (!Number.isFinite(perPage) || perPage < 1) return null;
    return Math.min(300, Math.max(cols, perPage));
  }

  const d = deckColumnCycle;
  const layout = getEl('app-layout');
  const filtersHidden = !!(layout && layout.classList.contains('filters-col-hidden'));
  const curLayout = viewModeLayout(currentView);
  const isCroppedGrid = curLayout === 'grid' && viewModeIsCropped(currentView);
  const bonus = filtersHidden ? (curLayout === 'list' ? 4 : 6) : 0;
  const fs = !!getFullscreenElement();
  const isMobile = window.innerWidth < 900;
  const perRow = fs ? getItemsPerRowForCurrentLayout(isMobile, d, filtersHidden, curLayout) : 0;
  const extraRow = isCroppedGrid
    ? getItemsPerRowForCurrentLayout(isMobile, d, filtersHidden, 'grid')
    : 0;
  const measured = tryComputeItemsPerPageFromViewport(isMobile);
  // Mobile
  if (isMobile) {
    if (curLayout === 'list') {
      // Regras específicas quando os filtros estão ocultos (modo lista).
      if (filtersHidden) {
        if (d === 1) return 20 + perRow;
        if (d === 2) return 9 + perRow;
      }
      if (d === 0) return 20 + bonus + perRow;
      if (d === 1) return 16 + bonus + perRow;
      return 12 + bonus + perRow;
    }
    if (d === 0) return Math.min(300, 24 + bonus + perRow + extraRow);
    if (d === 1) return Math.min(300, 22 + bonus + perRow + extraRow);
    return Math.min(300, 16 + bonus + perRow + extraRow);
  }
  // Desktop List Mode
  if (curLayout === 'list') {
    // Regras específicas quando os filtros estão ocultos (modo lista).
    if (filtersHidden) {
      if (d === 1) return measured ?? 20 + perRow;
      if (d === 2) return measured ?? 12 + perRow;
    }
    if (d === 0) return measured ?? 20 + bonus + perRow;
    if (d === 1) return measured ?? 12 + bonus + perRow;
    return measured ?? 8 + bonus + perRow;
  }
  // Desktop Grid Mode
  if (d === 0) return Math.min(300, (measured ?? 30 + bonus + perRow) + extraRow);
  if (d === 1) return Math.min(300, (measured ?? 21 + bonus + perRow) + extraRow);
  return Math.min(300, (measured ?? 15 + bonus + perRow) + extraRow);
}

/**
 * Restaura preferências persistentes antes dos init pesados de layout: ciclo da coluna do deck, vista da fila,
 * validação desativada, escala PDF, tooltip, sincronização do toggle da fila e modo ajuda.
 *
 * @returns {void}
 */
function restoreCookieBackedUiStateEarly() {
  try {
    const dc = int10(getUiPref(UI_PREF_KEYS.deckColCycle), NaN);
    if (dc === 0 || dc === 1 || dc === 2) deckColumnCycle = dc;
  } catch (_) {}
  try {
    const qv = getUiPref(UI_PREF_KEYS.queueView);
    if (qv === 'list' || qv === 'list_cropped' || qv === 'grid' || qv === 'grid_cropped')
      queueView = qv;
  } catch (_) {}
  try {
    deckValidationDisabled = getUiPref(UI_PREF_KEYS.deckValidateOff) === '1';
  } catch (_) {}
  try {
    const scRaw = getUiPref(UI_PREF_KEYS.pdfScale);
    const sc = floatNum(scRaw, NaN);
    const el = getEl('print-scale');
    if (el && Number.isFinite(sc) && sc >= 40 && sc <= 250) el.value = sc.toFixed(1);
  } catch (_) {}
  try {
    applyTooltipFromPref();
  } catch (_) {}
  try {
    syncQueueViewToggleUi();
  } catch (_) {}
  try {
    uiHelpEnabled = getUiPref(UI_PREF_KEYS.help) === '1';
    document.documentElement.classList.toggle('help-enabled', isHelpEnabled());
  } catch (_) {}
}

/**
 * Handler `window.onload`: datas iniciais dos filtros, restauração massiva de prefs (tema, vista resultados, ordenação, idioma cartas),
 * fullscreen opcional com gate de feedback, scroll horizontal na lista via roda do rato, atalhos de filtros e catálogo cardinfo tardio.
 *
 * @returns {void}
 */
window.onload = () => {
  const hoje = new Date().toISOString().split('T')[0];
  setVal('date-start', FIRST_KNOWN_RELEASE_ISO.ocg);
  setVal('date-end', hoje);

  // Restaura preferências de UI (cookies; fallback localStorage).
  try {
    const themePref = getUiPref(UI_PREF_KEYS.theme);
    if (themePref) {
      const root = document.documentElement;
      const utcPref = UI_THEME_CLASSES;
      for (let ti = 0; ti < utcPref.length; ti++) root.classList.remove(utcPref[ti]);
      root.classList.add(themePref);
      const sel = getEl('theme-selector');
      if (sel) sel.value = themePref;
    }
  } catch (_) {}
  try {
    const viewPref = getUiPref(UI_PREF_KEYS.view);
    if (
      viewPref === 'list' ||
      viewPref === 'list_cropped' ||
      viewPref === 'grid' ||
      viewPref === 'grid_cropped'
    ) {
      currentView = viewPref;
      syncResultsViewToggleUi();
    }
  } catch (_) {}
  try {
    const sortPref = getUiPref(UI_PREF_KEYS.resultsSort);
    const sel = getEl('sort-by');
    if (sel && sortPref && selectHasOptionValue(sel, sortPref)) setVal('sort-by', sortPref);
  } catch (_) {}
  try {
    const dirPref = int10(getUiPref(UI_PREF_KEYS.resultsSortDir), NaN);
    if (dirPref === 1 || dirPref === -1) {
      sortDirection = dirPref;
      const icon = getEl('order-icon');
      if (icon) icon.className = 'fas ' + (sortDirection === 1 ? 'fa-arrow-up' : 'fa-arrow-down');
    }
  } catch (_) {}
  try {
    const deckSortPref = getUiPref(UI_PREF_KEYS.deckSort);
    const sel = getEl('deck-sort-by');
    if (sel && deckSortPref && selectHasOptionValue(sel, deckSortPref)) {
      setVal('deck-sort-by', deckSortPref);
      deckSortCriterionPinned = deckSortPref;
    }
  } catch (_) {}
  try {
    const deckDirPref = int10(getUiPref(UI_PREF_KEYS.deckSortDir), NaN);
    if (deckDirPref === 1 || deckDirPref === -1) {
      deckSortDirection = deckDirPref;
      updateDeckSortOrderIcon();
    }
  } catch (_) {}

  // Idioma do texto das cartas: en | pt | fr | de | it (par\u00e2metro &language= na API, exceto en).
  try {
    const langPref = getUiPref(UI_PREF_KEYS.lang);
    uiLang = normalizeApiCardLangPref(langPref);
  } catch (_) {
    uiLang = 'pt';
  }
  updateCardLangSelect();
  applyUiLanguage();
  try {
    const ri0 = getEl('result-info');
    if (ri0) ri0.textContent = T('results.loading');
  } catch (_) {}
  try {
    const selLang = getEl('select-api-card-lang');
    if (selLang) selLang.onchange = () => setApiCardLang(selLang.value);
  } catch (_) {}

  try {
    const bHelp = getEl('btn-help-toggle');
    if (bHelp) bHelp.onclick = () => setHelpEnabled(!isHelpEnabled());
    const bMouse = getEl('btn-help-mouse');
    if (bMouse) bMouse.onclick = () => openHelpMouseModal();
    applyHelpUi();
  } catch (_) {}

  try {
    if (getUiPref(UI_PREF_KEYS.fullscreen) === '1') {
      const el = document.documentElement;
      const req =
        el.requestFullscreen ||
        el.webkitRequestFullscreen ||
        el.mozRequestFullScreen ||
        el.msRequestFullscreen;
      if (req) req.call(el).catch(() => {});
    }
  } catch (_) {}
  persistFullscreenPref = true;
  __uiFsSurfaceGateUntil = Date.now() + 2200;
  __uiFsWasFullscreen = !!getFullscreenElement();

  const resultsViewEl = getEl('results-view');
  if (resultsViewEl)
    resultsViewEl.addEventListener(
      'wheel',
      function (e) {
        const panel = getEl('card-sets-panel');
        if (panel && panel.classList.contains('is-open')) return;
        const tt = getEl('card-tooltip');
        const desktopTt = tt && tt.style.display === 'block' && window.innerWidth >= 900;
        if (desktopTt) {
          const tRect = tt.getBoundingClientRect();
          if (
            e.clientX >= tRect.left &&
            e.clientX <= tRect.right &&
            e.clientY >= tRect.top &&
            e.clientY <= tRect.bottom
          ) {
            e.preventDefault();
            return;
          }
        }
        e.preventDefault();
        if (e.deltaY > 0) changePage(1);
        else changePage(-1);
      },
      { passive: false }
    );
  const cspBack = getEl('card-sets-panel-backdrop');
  const cspClose = getEl('card-sets-panel-close');
  if (cspBack) cspBack.addEventListener('click', closeCardSetsPanel);
  if (cspClose) cspClose.addEventListener('click', closeCardSetsPanel);
  const _dateInpIds = ['date-start', 'date-end'];
  for (let _di = 0; _di < _dateInpIds.length; _di++)
    getEl(_dateInpIds[_di])?.addEventListener('change', triggerSearch);
  document.addEventListener('DOMContentLoaded', () => {
    updateBanlistDates();
  });
  scheduleCardinfoCatalogBuild();
  const fAdd = getEl('filter-cardset-add');
  const fClr = getEl('filter-cardset-clear');
  const fInp = getEl('filter-cardset-input');
  if (fAdd) fAdd.onclick = () => tryAddCardsetFromInput();
  if (fClr)
    fClr.onclick = () => {
      window.selectedCardsetNames = [];
      if (fInp) fInp.value = '';
      renderCardsetFilterChips();
      currentPage = 1;
      performSearch(true);
    };
  if (fInp)
    fInp.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        tryAddCardsetFromInput();
      }
    });
  if (fInp) {
    fInp.addEventListener('input', (e) => {
      if (e.inputType === 'insertReplacementText') tryAddCardsetFromInput();
    });
    fInp.addEventListener('change', () => {
      if (comboInputMatchesDatalistPick(fInp)) tryAddCardsetFromInput();
    });
  }
  const scAdd = getEl('filter-setcode-add');
  const scClr = getEl('filter-setcode-clear');
  const scInp = getEl('filter-setcode-input');
  if (scAdd) scAdd.onclick = () => tryAddSetcodeFromInput();
  if (scClr)
    scClr.onclick = () => {
      window.selectedSetCodes = [];
      if (scInp) scInp.value = '';
      renderSetcodeFilterChips();
      currentPage = 1;
      performSearch(true);
    };
  if (scInp)
    scInp.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        tryAddSetcodeFromInput();
      }
    });
  const prefetchCardinfoIfFilterTarget = (e) => {
    const t = e.target;
    if (!t || t.nodeType !== 1) return;
    switch (/** @type {HTMLElement} */ (t).id) {
      case 'filter-setcode-input':
      case 'filter-rarity-input':
      case 'filter-subtype-input':
      case 'filter-race-input':
        void ensureCardinfoCatalogFromApi();
        break;
      default:
    }
  };
  if (document.body)
    document.body.addEventListener('focusin', prefetchCardinfoIfFilterTarget, true);

  if (scInp) {
    scInp.addEventListener('input', (e) => {
      if (e.inputType === 'insertReplacementText') tryAddSetcodeFromInput();
    });
    scInp.addEventListener('change', () => {
      if (comboInputMatchesDatalistPick(scInp)) tryAddSetcodeFromInput();
    });
  }
  const rAdd = getEl('filter-rarity-add');
  const rClr = getEl('filter-rarity-clear');
  const rInp = getEl('filter-rarity-input');
  if (rAdd) rAdd.onclick = () => tryAddRarityFromInput();
  if (rClr)
    rClr.onclick = () => {
      window.selectedRarities = [];
      if (rInp) rInp.value = '';
      renderRarityFilterChips();
      currentPage = 1;
      performSearch(true);
    };
  if (rInp)
    rInp.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        tryAddRarityFromInput();
      }
    });
  if (rInp) {
    rInp.addEventListener('input', (e) => {
      if (e.inputType === 'insertReplacementText') tryAddRarityFromInput();
    });
    rInp.addEventListener('change', () => {
      if (comboInputMatchesDatalistPick(rInp)) tryAddRarityFromInput();
    });
  }
  const rndBtn = getEl('btn-random-filter-card');
  if (rndBtn) {
    rndBtn.onclick = () => pickRandomFilteredCard();
    updateRandomPickButtonUi();
  }
  renderSetcodeFilterChips();
  renderRarityFilterChips();
  wireComboFilterControls();
  paintAllMultiTextChips();
  const fNameAdd = getEl('filter-fname-add-chip');
  const fNameClr = getEl('filter-fname-clear-chips');
  const fNameInp = getEl('search-input');
  if (fNameAdd) fNameAdd.onclick = () => tryAddFnameChip();
  if (fNameClr) fNameClr.onclick = () => clearMultiTextGroup('fname');
  if (fNameInp)
    fNameInp.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        tryAddFnameChip();
      }
    });
  const dAdd = getEl('filter-desc-add-chip');
  const dClr = getEl('filter-desc-clear-chips');
  const dInp = getEl('filter-desc');
  if (dAdd) dAdd.onclick = () => tryAddDescChip();
  if (dClr) dClr.onclick = () => clearMultiTextGroup('desc');
  if (dInp)
    dInp.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        tryAddDescChip();
      }
    });
  const atkAdd = getEl('filter-atk-add-chip');
  const atkClr = getEl('filter-atk-clear-chips');
  if (atkAdd) atkAdd.onclick = () => tryAddAtkChip();
  if (atkClr) atkClr.onclick = () => clearMultiTextGroup('atk');
  const atkInp = getEl('filter-atk');
  if (atkInp)
    atkInp.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        tryAddAtkChip();
      }
    });
  const defAdd = getEl('filter-def-add-chip');
  const defClr = getEl('filter-def-clear-chips');
  if (defAdd) defAdd.onclick = () => tryAddDefChip();
  if (defClr) defClr.onclick = () => clearMultiTextGroup('def');
  const defInp = getEl('filter-def');
  if (defInp)
    defInp.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        tryAddDefChip();
      }
    });
  const pAdd = getEl('filter-price-add-chip');
  const pClr = getEl('filter-price-clear-chips');
  if (pAdd) pAdd.onclick = () => tryAddPriceRangeChip();
  if (pClr) pClr.onclick = () => clearMultiTextGroup('price');
  const pMinInp = getEl('filter-price-min');
  const pMaxInp = getEl('filter-price-max');
  const _priceKeyEls = [pMinInp, pMaxInp];
  for (let _pk = 0; _pk < _priceKeyEls.length; _pk++) {
    const el = _priceKeyEls[_pk];
    if (!el) continue;
    el.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        e.preventDefault();
        tryAddPriceRangeChip();
      }
    });
  }
  void (async () => {
    try {
      const u = new URL(window.location.href);
      const sp = u.searchParams;
      if (sp.has(filterUrlParamKey('cs')) || sp.has(filterUrlParamKey('ar'))) {
        await Promise.all([
          sp.has(filterUrlParamKey('cs')) ? loadCardsetsCatalog() : Promise.resolve(),
          sp.has(filterUrlParamKey('ar')) ? loadArchetypesCatalog() : Promise.resolve(),
        ]);
      } else {
        loadCardsetsCatalog();
        loadArchetypesCatalog();
      }
      void refreshYgoprodeckDbVersion();
      filterUrlSyncSuspended = true;
      applyDeckbuilderFiltersFromUrl(sp);
    } catch (e) {
      console.warn('Filtros na URL:', e);
    } finally {
      filterUrlSyncSuspended = false;
    }
    performSearch(true);
  })();
  let resizeItemsPerPageTimer;
  window.addEventListener('resize', () => {
    clearTimeout(resizeItemsPerPageTimer);
    resizeItemsPerPageTimer = setTimeout(() => {
      const items = getItemsPerPage();
      if (searchResults.length > 0) {
        const maxPage = Math.max(1, Math.ceil(searchResults.length / items));
        if (currentPage > maxPage) currentPage = maxPage;
      }
      requestCardSurfaceFeedback('silent');
      renderResults();
    }, 150);
  });

  // Quando classes do layout mudam (deck/filtros), refaz o ajuste do modo lista imediatamente.
  try {
    const layout = getEl('app-layout');
    let moTimer = null;
    if (layout) {
      const scheduleRefit = () => {
        if (viewModeLayout(currentView) !== 'list') return;
        const rv = getEl('results-view');
        clearResultsListOverrides(rv);
        try {
          requestCardSurfaceFeedback('silent');
        } catch (_) {}
        renderResults();
      };
      const obs = new MutationObserver(() => {
        if (viewModeLayout(currentView) !== 'list') return;
        clearTimeout(moTimer);
        moTimer = setTimeout(() => {
          // 1) imediato (para trocar cols/perPage já)
          scheduleRefit();
          // 2) após a transição de largura do grid (deck-col-wide etc.)
          setTimeout(() => scheduleRefit(), 360);
        }, 50);
      });
      obs.observe(layout, { attributes: true, attributeFilter: ['class'] });

      // Alguns browsers não disparam mutation no timing ideal durante transições;
      // reforça com transitionend do container.
      layout.addEventListener(
        'transitionend',
        (ev) => {
          if (viewModeLayout(currentView) !== 'list') return;
          const prop = String(ev && ev.propertyName ? ev.propertyName : '');
          if (prop && !/grid-template-columns|width|max-width|min-width/.test(prop)) return;
          scheduleRefit();
        },
        true
      );
    }
  } catch (_) {}
};

/**
 * Sincroniza rótulos/ícone do botão de alternância da vista de **resultados** (`currentView` → próximo modo em ciclo).
 * @returns {void}
 */
function syncResultsViewToggleUi() {
  const btn = getEl('btn-toggle-results-view');
  const lab = getEl('label-toggle-results-view');
  const icon = getEl('icon-toggle-results-view');
  if (!btn || !lab) return;
  const next = nextViewMode4(currentView);
  const nextLayout = viewModeLayout(next);
  const nextCropped = viewModeIsCropped(next);
  const labelKey =
    nextLayout === 'grid'
      ? nextCropped
        ? 'ui.grid_cropped_label'
        : 'ui.grid_label'
      : nextCropped
        ? 'ui.list_cropped_label'
        : 'ui.list_label';
  const titleKey =
    nextLayout === 'grid'
      ? nextCropped
        ? 'ui.grid_cropped_title'
        : 'ui.grid_title'
      : nextCropped
        ? 'ui.list_cropped_title'
        : 'ui.list_title';
  lab.textContent = T(labelKey);
  const t = T(titleKey);
  btn.setAttribute('title', t);
  btn.setAttribute('aria-label', t);
  if (icon) icon.className = nextLayout === 'grid' ? 'fas fa-th-large' : 'fas fa-list';
}

