// ==================== MÓDULO OCR - VERSÃO CORRIGIDA ====================
/** Worker Tesseract (`Tesseract.createWorker()`); `null` até o primeiro scan bem-sucedido. */
let ocrWorker = null;
/** Quando verdadeiro, o loop {@link processOcrFrame} continua ativo. */
let isOcrActive = false;
/** Evita sobreposição de OCR no mesmo instante. */
let isProcessing = false;
/** Último nome de carta aceito como match (dedupe de toast/UI). */
let lastMatchedText = '';
let lastMatchTime = 0;
/** Cartas distintas reconhecidas na sessão atual do scanner. */
let scannerFoundCards = [];
let scannerFoundCardIds = new Set();
/** Mapa `id` → objeto carta API para o botão “adicionar” (`forceAddToQueue`). */
let scannerFoundCardById = new Map();
/** Cooldown curto após match para não inundar a API. */
let processingCooldown = false;
/** Texto da última query `smartSearch` (throttle ~900 ms). */
let lastApiSearchCleaned = '';
let lastApiSearchTime = 0;
/** Buffer circular de eventos de debug OCR (export JSON). */
const ocrDebugBuffer = [];
const OCR_DEBUG_MAX = 400;
/** Última entrada de {@link pushOcrDebug} (screenshot overlay). */
let lastOcrDebugSnapshot = null;
/** Tipo de carta inferido no último frame processado (UI). */
let lastDetectedCardType = null;
let lastScanHapticKey = '';
let lastScanHapticTime = 0;

/**
 * Pulso visual verde na caixa `#scanner-visual` quando há match.
 * @returns {void}
 */
function pulseScanMatchVisual() {
  const el = getEl('scanner-visual');
  if (!el) return;
  el.style.transition = 'box-shadow 0.12s ease-out';
  el.style.boxShadow = '0 0 0 4px #2ecc71, 0 0 28px rgba(46,204,113,0.75)';
  setTimeout(() => {
    el.style.boxShadow = '';
  }, 280);
}

/**
 * Bip curto via Web Audio (880 Hz) ao reconhecer carta; ignora falhas silenciosamente.
 * @returns {void}
 */
function playOcrMatchBeep() {
  try {
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    const actx = window.__ocrBeepCtx || (window.__ocrBeepCtx = new Ctx());
    if (actx.state === 'suspended') actx.resume().catch(() => {});
    const o = actx.createOscillator();
    const g = actx.createGain();
    o.type = 'sine';
    o.frequency.value = 880;
    o.connect(g);
    g.connect(actx.destination);
    g.gain.setValueAtTime(0.0001, actx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.1, actx.currentTime + 0.025);
    g.gain.exponentialRampToValueAtTime(0.0001, actx.currentTime + 0.14);
    o.start(actx.currentTime);
    o.stop(actx.currentTime + 0.15);
  } catch (e) {}
}

/**
 * Feedback háptico + visual + som ao detectar `cardId` (debounce ~1,4 s por ID).
 * @param {string|number} cardId ID da carta na API.
 * @returns {void}
 */
function triggerScanHaptic(cardId) {
  const now = Date.now();
  const key = String(cardId);
  if (key === lastScanHapticKey && now - lastScanHapticTime < 1400) return;
  lastScanHapticKey = key;
  lastScanHapticTime = now;
  pulseScanMatchVisual();
  try {
    if (__hasUserGesture && navigator.vibrate) navigator.vibrate(200);
  } catch (e) {}
  playOcrMatchBeep();
}

// ==================== FUNÇÕES AUXILIARES ====================

/**
 * Heurística para descartar strings OCR improváveis de serem nomes (comprimento, vogais, repetições).
 * @param {string} text Texto bruto ou normalizado.
 * @returns {boolean} `true` se deve ser ignorado.
 */
function isGarbageText(text) {
  if (!text || text.length < 3) return true;
  if (text.length < 3 || text.length > 45) return true;
  const letters = text.replace(/[^A-Z]/g, '');
  if (letters.length < 3) return true;
  const vowels = (text.match(/[AEIOU]/gi) || []).length;
  const consonants = letters.length - vowels;
  if (consonants > vowels * 2.5 && letters.length > 6) return true;
  if (/([A-Z])\1{4,}/.test(text)) return true;
  return false;
}

/** Palavras curtas (≤2 letras) mantidas na normalização OCR. */
const SMART_NORMALIZE_VALID_SHORT = new Set(['OF', 'TO', 'A', 'DE', 'DO']);
/** Atributos de carta Yu-Gi-Oh que o OCR costuma ler no frame e não fazem parte do nome. */
const SMART_NORMALIZE_BAD_WORDS = new Set([
  'LUZ',
  'TREVAS',
  'FOGO',
  'ÁGUA',
  'VENTO',
  'TERRA',
  'DIVINO',
]);

/**
 * Normaliza texto OCR: maiúsculas, remove ruído, corta até ~6 tokens úteis (alinhado a `mobile_camera.html`).
 * @param {string} text
 * @returns {string}
 */
function smartNormalize(text) {
  if (!text) return '';
  let clean = text.toUpperCase().replace(/[^A-Z0-9 ,:\u00C0-\u00FF\-']/g, ' ');
  clean = clean.replace(/(.)\1{2,}/g, '$1');
  // IMPORTANTE: não remover palavras como MONSTER/SPELL/TRAP etc. porque elas existem em nomes reais
  // (ex.: "MONSTER GATE", "TRAP HOLE", "SPELL ABSORPTION").
  const parts = clean.split(' ');
  const out = [];
  for (let i = 0; i < parts.length; i++) {
    const w = parts[i];
    if (!w) continue;
    if (w.length <= 2 && !SMART_NORMALIZE_VALID_SHORT.has(w)) continue;
    if (SMART_NORMALIZE_BAD_WORDS.has(w)) continue;
    if (w.length < 2) continue;
    out.push(w);
    if (out.length >= 6) break;
  }
  if (out.length === 0) return '';
  return out.join(' ').replace(/\s+/g, ' ').trim();
}

/**
 * Similaridade 0–1 derivada da distância de Levenshtein (normalizada pelo comprimento maior).
 * @param {string} str1
 * @param {string} str2
 * @returns {number}
 */
function calculateSimilarity(str1, str2) {
  let m = str1.length,
    n = str2.length;
  if (m === 0 || n === 0) return 0;
  if (m > n) [str1, str2, m, n] = [str2, str1, n, m];
  let prev = new Array(m + 1);
  for (let i = 0; i <= m; i++) prev[i] = i;
  let curr = new Array(m + 1);
  for (let j = 1; j <= n; j++) {
    curr[0] = j;
    for (let i = 1; i <= m; i++) {
      const cost = str1[i - 1] === str2[j - 1] ? 0 : 1;
      curr[i] = Math.min(prev[i] + 1, curr[i - 1] + 1, prev[i - 1] + cost);
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }
  return (Math.max(m, n) - prev[m]) / Math.max(m, n);
}

/**
 * Valores aceitos em `cardinfo.php?language=` (inglês = omitir parâmetro; ver guia YGOPRODeck).
 * @type {ReadonlySet<string>}
 */
const CARDINFO_LANGUAGE_PARAMS = new Set(['pt', 'fr', 'de', 'it']);

/** Cache nome normalizado + língua → melhor carta ou `null` ({@link fetchCardByName}). */
const cardCacheAPI = new Map();
/** Cache token `fname` + língua → array de cartas cruas da API. */
const fnameRawCache = new Map();
const FNAME_RAW_CACHE_MAX = 120;

/** A API costuma não aceitar (ou não achar) fname com várias palavras; usamos 1 token forte por requisição. */
function fnameTokensForApi(name) {
  const parts = normalizeForSim(name).split(' ');
  const seen = new Set();
  const uniq = [];
  for (let pi = 0; pi < parts.length; pi++) {
    const tok = parts[pi];
    if (!tok || tok.length < 3) continue;
    if (seen.has(tok)) continue;
    seen.add(tok);
    uniq.push(tok);
  }
  uniq.sort((a, b) => b.length - a.length);
  const n = uniq.length;
  if (!n) return [];
  if (n <= 3) return uniq;
  return [uniq[0], uniq[1], uniq[2]];
}

/**
 * `GET cardinfo.php?fname=…` com saneamento e LRU em `fnameRawCache`.
 * @param {string} fnameToken Um token (≥3 chars após strip).
 * @param {string|null|undefined} lang `pt`|`fr`|`de`|`it` ou omitido para padrão inglês.
 * @returns {Promise<object[]>} Lista de cartas (vazia em erro).
 */
async function fetchCardDataByFname(fnameToken, lang) {
  const ft = stripSqlDangerousSequences(
    stripDangerousUnicodeAndControls(String(fnameToken || ''))
  ).trim();
  if (!ft || ft.length < 3) return [];
  const ck = `${ft}|${lang || 'def'}`;
  if (fnameRawCache.has(ck)) return fnameRawCache.get(ck);
  try {
    let url = `https://db.ygoprodeck.com/api/v7/cardinfo.php?fname=${encodeURIComponent(ft)}&misc=yes`;
    if (lang && CARDINFO_LANGUAGE_PARAMS.has(String(lang))) url += `&language=${lang}`;
    const r = await deckbuilderPublicApiFetch(url);
    if (!r.ok) {
      fnameRawCache.set(ck, []);
      if (fnameRawCache.size > FNAME_RAW_CACHE_MAX)
        fnameRawCache.delete(fnameRawCache.keys().next().value);
      return [];
    }
    const j = await r.json();
    const data = j.error || !j.data || !j.data.length ? [] : j.data;
    fnameRawCache.set(ck, data);
    if (fnameRawCache.size > FNAME_RAW_CACHE_MAX)
      fnameRawCache.delete(fnameRawCache.keys().next().value);
    return data;
  } catch (err) {
    fnameRawCache.set(ck, []);
    return [];
  }
}

/**
 * Mescla cartas num `Map` por `id`, preenchendo `name_pt` / `name_en` quando faltam.
 * @param {Map<number, object>} intoMap
 * @param {object[]} cards
 * @returns {void}
 */
function mergeCardsById(intoMap, cards) {
  for (const c of cards) {
    const id = c.id;
    if (!intoMap.has(id)) {
      intoMap.set(id, c);
      continue;
    }
    const o = intoMap.get(id);
    if (!o.name_pt && c.name_pt) o.name_pt = c.name_pt;
    if (!o.name_en && c.name_en) o.name_en = c.name_en;
  }
}

/**
 * Pontuação 0–1: melhor similaridade entre nomes da carta (PT/EN/beta) e texto OCR já em minúsculas normalizado.
 * @param {object} card Objeto API YGOPRODeck.
 * @param {string} ocrNormLower Saída de `normalizeForSim(name).toLowerCase()`.
 * @returns {number}
 */
function scoreCardAgainstOcr(card, ocrNormLower) {
  const qNorm = ocrNormLower;
  const cNorms = [];
  if (card.name_pt) cNorms.push(normalizeForSim(card.name_pt).toLowerCase());
  if (card.name) cNorms.push(normalizeForSim(card.name).toLowerCase());
  if (card.name_en) cNorms.push(normalizeForSim(card.name_en).toLowerCase());
  const mx = card.misc_info && card.misc_info[0];
  if (card.beta_name) cNorms.push(normalizeForSim(card.beta_name).toLowerCase());
  if (card.treated_as) cNorms.push(normalizeForSim(card.treated_as).toLowerCase());
  if (mx && mx.beta_name) cNorms.push(normalizeForSim(mx.beta_name).toLowerCase());
  if (mx && mx.treated_as) cNorms.push(normalizeForSim(mx.treated_as).toLowerCase());
  const uniq = [];
  const seen = new Set();
  for (const raw of cNorms) {
    if (!raw) continue;
    if (seen.has(raw)) continue;
    seen.add(raw);
    uniq.push(raw);
  }
  const qTokU = [];
  pushAsciiSpaceDelimitedSegmentsUpperMinLen(qNorm, 5, qTokU);
  const multiTokenBoost = qTokU.length >= 2;
  let score = 0;
  for (const cNorm of uniq) {
    let s = calculateSimilarity(qNorm, cNorm);
    if (multiTokenBoost) {
      const cNormU = cNorm.toUpperCase();
      let tw = 0;
      for (let ti = 0; ti < qTokU.length; ti++) {
        if (ocrTokenMatchesCardName(qTokU[ti], cNormU)) tw++;
      }
      s = Math.max(s, Math.min(1, s + tw * 0.04));
    }
    score = Math.max(score, s);
  }
  return score;
}

/**
 * Busca fuzzy: vários tokens × (`language` escolhido) → inglês padrão (sem `language=`).
 * `lang`: en | pt | fr | de | it (alinhado ao seletor do deckbuilder quando disponível).
 *
 * @param {string} name Nome ou fragmento a resolver (normalizado internamente).
 * @param {string|null|undefined} lang Código de idioma da cadeia de `fetchCardDataByFname` ou vazio para cadeia padrão.
 * @returns {Promise<object|null>} Melhor carta por similaridade ou `null` (query curta, sem candidatos, erro ou score baixo).
 */
async function fetchCardByName(name, lang) {
  const qNorm = normalizeForSim(name).toLowerCase();
  if (qNorm.length < 3) return null;
  const lk = lang == null || lang === '' ? null : String(lang).toLowerCase();
  const cacheKey = `${qNorm}__${lk || 'all'}`;
  if (cardCacheAPI.has(cacheKey)) return cardCacheAPI.get(cacheKey);

  const tokens = fnameTokensForApi(name);
  if (!tokens.length) return null;

  const langChains = {
    en: [null],
    pt: ['pt', null],
    fr: ['fr', null],
    de: ['de', null],
    it: ['it', null],
    null: [null, 'pt'],
  };
  const chain = lk && langChains[lk] ? langChains[lk] : langChains.null;

  try {
    const merged = new Map();
    const cn = chain.length;
    for (const tok of tokens) {
      const batchPromises = new Array(cn);
      for (let li = 0; li < cn; li++) batchPromises[li] = fetchCardDataByFname(tok, chain[li]);
      const batches = await Promise.all(batchPromises);
      for (let bi = 0; bi < batches.length; bi++) mergeCardsById(merged, batches[bi]);
    }

    const candidates = arrayFromMapValues(merged);
    if (!candidates.length) {
      cardCacheAPI.set(cacheKey, null);
      return null;
    }

    let best = null;
    let bestScore = 0;
    const scoreCap = candidates.length < 80 ? candidates.length : 80;
    for (let ci = 0; ci < scoreCap; ci++) {
      const card = candidates[ci];
      const sc = scoreCardAgainstOcr(card, qNorm);
      if (sc > bestScore) {
        bestScore = sc;
        best = card;
      }
    }
    const nGe2 = countAsciiSpaceDelimitedSegmentsMinLen(qNorm, 2);
    const minSim = nGe2 >= 3 ? 0.36 : 0.4;
    const result = bestScore > minSim ? best : null;
    cardCacheAPI.set(cacheKey, result);
    return result;
  } catch (err) {
    console.warn('fetchCardByName error:', err);
    cardCacheAPI.set(cacheKey, null);
    return null;
  }
}

/** Palavras genéricas demais para tentar como query isolada em `smartSearch`. */
const SMART_SEARCH_IGNORE_WORDS = new Set([
  'DRAGÃO',
  'DRAGAO',
  'MÁGICA',
  'MAGICA',
  'ARMADILHA',
  'TOKEN',
  'FUSÃO',
  'FUSAO',
  'EFFECT',
  'EFEITO',
]);

/**
 * Busca em cascata na API (nome inteiro, colado, bigramas, palavras longas) com throttle e filtro opcional “match forte”.
 *
 * @param {string} fullText Texto OCR já limpo (`smartNormalize`).
 * @param {boolean} [bypassThrottle] Se `true`, ignora dedupe temporal da última query.
 * @param {string|null} [ocrContextForStrongMatch] Se definido, só aceita carta que passe {@link isStrongMatch}.
 * @returns {Promise<object|null>} Carta API ou `null`.
 */
async function smartSearch(fullText, bypassThrottle = false, ocrContextForStrongMatch = null) {
  if (!fullText || fullText.length < 3) return null;
  if (!bypassThrottle && lastApiSearchCleaned === fullText && Date.now() - lastApiSearchTime < 900)
    return null;

  const accept = (card) => {
    if (!card) return false;
    if (!ocrContextForStrongMatch) return true;
    // Se o contexto foi passado, só aceita se for match forte; caso contrário, segue tentando outras queries.
    return isStrongMatch(ocrContextForStrongMatch, card);
  };
  const tryPair = async (query) => {
    if (!query || query.length < 4) return null;
    // fetchCardByName já encadeia PT → EN → padrão e mescla candidatos por token fname.
    return await fetchCardByName(query, getUiLang());
  };

  let card = await tryPair(fullText);
  if (accept(card)) {
    lastApiSearchCleaned = fullText;
    lastApiSearchTime = Date.now();
    return card;
  }

  const noSpaces = fullText.replace(/\s+/g, '');
  if (noSpaces.length > 4) {
    card = await tryPair(noSpaces);
    if (accept(card)) {
      lastApiSearchCleaned = fullText;
      lastApiSearchTime = Date.now();
      return card;
    }
  }

  const seqParts = fullText.split(/\s+/);
  const seqWords = [];
  for (let si = 0; si < seqParts.length; si++) {
    const sw = seqParts[si];
    if (sw.length >= 4 && !SMART_SEARCH_IGNORE_WORDS.has(sw)) seqWords.push(sw);
  }
  for (let i = 0; i < seqWords.length - 1; i++) {
    const phrase = `${seqWords[i]} ${seqWords[i + 1]}`;
    if (phrase.length < 9) continue;
    card = await tryPair(phrase);
    if (accept(card)) {
      lastApiSearchCleaned = fullText;
      lastApiSearchTime = Date.now();
      return card;
    }
  }

  const wParts = fullText.split(' ');
  const words = [];
  for (let wi = 0; wi < wParts.length; wi++) {
    const w = wParts[wi];
    if (w.length >= 6 && !SMART_SEARCH_IGNORE_WORDS.has(w)) words.push(w);
  }
  const sorted = words.slice();
  sorted.sort((a, b) => b.length - a.length);
  if (sorted.length >= 2) {
    const a = sorted[0],
      b = sorted[1];
    if (a !== b) {
      card = await tryPair(`${a} ${b}`);
      if (accept(card)) {
        lastApiSearchCleaned = fullText;
        lastApiSearchTime = Date.now();
        return card;
      }
    }
  }
  const sortedCap = sorted.length < 3 ? sorted.length : 3;
  for (let wi = 0; wi < sortedCap; wi++) {
    const word = sorted[wi];
    card = await tryPair(word);
    if (accept(card)) {
      lastApiSearchCleaned = fullText;
      lastApiSearchTime = Date.now();
      return card;
    }
    if (word.length >= 9) {
      card = await tryPair(word.substring(0, 5));
      if (accept(card)) {
        lastApiSearchCleaned = fullText;
        lastApiSearchTime = Date.now();
        return card;
      }
    }
  }
  return null;
}

/**
 * Normaliza string para comparação: NFD sem diacríticos, A–Z e dígitos, espaços colapsados.
 * @param {string} s
 * @returns {string}
 */
function normalizeForSim(s) {
  // Remove acentos/diacríticos para comparação PT/EN (ex.: DRAGÃO ~= DRAGAO)
  const base = (s || '').normalize('NFD').replace(/\p{Diacritic}/gu, '');
  return base
    .toUpperCase()
    .replace(/[^A-Z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Token do OCR presente no nome da carta (substring, prefixo truncado ou similaridade). */
function ocrTokenMatchesCardName(ocrTok, cardNorm) {
  if (!ocrTok || !cardNorm) return false;
  if (cardNorm.includes(ocrTok)) return true;
  const o = ocrTok.toLowerCase();
  const parts = cardNorm.split(' ');
  for (let pi = 0; pi < parts.length; pi++) {
    const p = parts[pi];
    if (!p) continue;
    const pl = p.toLowerCase();
    if (ocrTok.length >= 4 && p.length >= ocrTok.length + 3 && pl.startsWith(o)) return true;
    if (pl.includes(o) || o.includes(pl)) {
      const L = Math.min(ocrTok.length, p.length);
      if (L >= 5 && calculateSimilarity(o, pl) >= 0.55) return true;
    }
    if (ocrTok.length >= 5 && p.length >= 5 && calculateSimilarity(o, pl) >= 0.66) return true;
  }
  return false;
}

const OCR_STOP_WORDS = new Set(['THE', 'OF', 'TO', 'A', 'DE', 'DO', 'AND', 'OR']);
/** Partes já de `normalizeForSim(...).split(' ')` (podem conter `''` entre espaços). */
/**
 * @param {string[]} parts Partes de `normalizeForSim(...).split(' ')`.
 * @param {number} [minLen=6] Comprimento mínimo da palavra.
 * @returns {string[]}
 */
function goodTokensFromNormalizedParts(parts, minLen = 6) {
  const out = [];
  for (let i = 0; i < parts.length; i++) {
    const w = parts[i];
    if (!w) continue;
    if (w.length >= minLen && !OCR_STOP_WORDS.has(w)) out.push(w);
  }
  return out;
}

/** `normUpper` = saída de `normalizeForSim` (já upper / sem acentos). */
/**
 * @param {string} normUpper Já em maiúsculas / sem acentos (saída típica de `normalizeForSim`).
 * @param {number} [minLen=6]
 * @returns {string[]}
 */
function goodTokensFromNormalized(normUpper, minLen = 6) {
  return goodTokensFromNormalizedParts(normUpper.split(' '), minLen);
}

/**
 * Lista única de nomes normalizados (`normalizeForSim`) para a carta (nomes + aliases misc).
 * @param {object} card
 * @returns {string[]}
 */
function cardNormalizedNames(card) {
  const out = [];
  if (card?.name_pt) out.push(normalizeForSim(card.name_pt));
  if (card?.name) out.push(normalizeForSim(card.name));
  if (card?.name_en) out.push(normalizeForSim(card.name_en));
  const mx = card.misc_info && card.misc_info[0];
  if (card?.beta_name) out.push(normalizeForSim(card.beta_name));
  if (card?.treated_as) out.push(normalizeForSim(card.treated_as));
  if (mx?.beta_name) out.push(normalizeForSim(mx.beta_name));
  if (mx?.treated_as) out.push(normalizeForSim(mx.treated_as));
  const seen = new Set();
  const uniq = [];
  for (const v of out) {
    if (!v) continue;
    if (seen.has(v)) continue;
    seen.add(v);
    uniq.push(v);
  }
  return uniq;
}

/**
 * Match “forte” do OCR contra um único nome normalizado `b` (tokens, similaridade, palavras genéricas).
 * @param {string} ocrCleaned Texto OCR (pode ter caixa mista; será normalizado dentro).
 * @param {string} b Nome de carta já `normalizeForSim`.
 * @returns {boolean}
 */
function isStrongMatchAgainstB(ocrCleaned, b) {
  if (!b || b.length < 4) return false;
  const a = normalizeForSim(ocrCleaned);
  if (a.length < 6) return false;

  const sim = calculateSimilarity(a.toLowerCase(), b.toLowerCase());
  const aParts = a.split(' ');
  let good = goodTokensFromNormalizedParts(aParts, 6);
  if (good.length >= 2) {
    for (let i = 0; i < aParts.length; i++) {
      const w = aParts[i];
      if (!w || w.length !== 5) continue;
      if (!good.includes(w)) good.push(w);
    }
  }
  let hits = 0;
  for (const tok of good) if (ocrTokenMatchesCardName(tok, b)) hits++;

  let meaningfulWordCount = 0;
  for (let i = 0; i < aParts.length; i++) {
    const w = aParts[i];
    if (w && w.length >= 3) meaningfulWordCount++;
  }
  let cardWordCount = 0;
  const bParts = b.split(' ');
  for (let bi = 0; bi < bParts.length; bi++) {
    if (bParts[bi]) cardWordCount++;
  }

  if (good.length >= 2) {
    if (good.length === 2) {
      if (hits < 2) return false;
    } else {
      if (hits < 2 || sim < 0.45) return false;
    }
    return true;
  }

  let longest = '';
  for (let li = 0; li < aParts.length; li++) {
    const w = aParts[li];
    if (!w) continue;
    if (w.length > longest.length) longest = w;
  }
  const RISKY_ONE = new Set([
    'DRAGON',
    'MAGIC',
    'MAGICA',
    'SPELL',
    'TRAP',
    'STAR',
    'RING',
    'CORE',
    'KNIGHT',
    'LORD',
    'KING',
    'SOUL',
    'MAN',
  ]);
  if (good.length === 1 && RISKY_ONE.has(longest) && sim < 0.82) return false;
  if (good.length === 1 && cardWordCount >= 2 && meaningfulWordCount < 2 && sim < 0.72)
    return false;
  if (
    good.length === 1 &&
    cardWordCount === 1 &&
    b.startsWith(a) &&
    b.length > a.length + 1 &&
    sim < 0.93
  )
    return false;
  if (
    good.length === 1 &&
    cardWordCount >= 2 &&
    b.includes(a) &&
    b.length > a.length + 3 &&
    a.length >= 5
  )
    return false;

  // Se o token mais longo é curto (< 5 letras), requer similaridade bem mais alta
  // Ex: "FFTE GATE" (longest=4) não deve aceitar "CASTLE GATE" com sim≈0.63
  if (longest.length < 5 && sim < 0.82) return false;

  // Sem nenhum token longo (≥6 chars) em nome de carta multi-palavra: requer sim alta
  // Ex: "JMNER GATE" (good=[]) não deve aceitar "Counter Gate" (sim≈0.67 < 0.80)
  if (good.length === 0 && cardWordCount >= 2 && sim < 0.8) return false;

  const hasLongToken = longest.length >= 7 && ocrTokenMatchesCardName(longest, b);
  if (sim >= 0.62) return true;
  if (sim >= 0.55 && hasLongToken) return true;
  return false;
}

/**
 * Verdadeiro se qualquer variante de nome da carta satisfaz {@link isStrongMatchAgainstB}.
 * @param {string} ocrCleaned
 * @param {object|null|undefined} card
 * @returns {boolean}
 */
function isStrongMatch(ocrCleaned, card) {
  if (!card) return false;
  const names = cardNormalizedNames(card);
  if (!names.length) return false;
  for (const b of names) {
    if (isStrongMatchAgainstB(ocrCleaned, b)) return true;
  }
  return false;
}

/**
 * Acrescenta linha no painel `#ocr-log` (máx. ~40 filhos).
 * @param {string} msg
 * @returns {void}
 */
function addOcrLog(msg) {
  const logBox = getEl('ocr-log');
  if (!logBox) return;
  const t = new Date().toLocaleTimeString('pt-BR', { hour12: false });
  const div = document.createElement('div');
  div.style.cssText =
    'border-bottom:1px solid #333; padding:2px; font-size:11px; color:#2ecc71; font-family:monospace;';
  div.textContent = `[${t}] ${msg}`;
  logBox.prepend(div);
  if (logBox.childElementCount > 40) logBox.removeChild(logBox.lastChild);
}

/**
 * Insere evento no início de {@link ocrDebugBuffer} (cap {@link OCR_DEBUG_MAX}) e atualiza {@link lastOcrDebugSnapshot}.
 * @param {object} entry
 * @returns {void}
 */
function pushOcrDebug(entry) {
  try {
    ocrDebugBuffer.unshift(entry);
    if (ocrDebugBuffer.length > OCR_DEBUG_MAX) ocrDebugBuffer.pop();
    lastOcrDebugSnapshot = entry;
  } catch (e) {}
}

/**
 * Regista evento estruturado (debug + log visível).
 * @param {string} event Identificador curto (ex.: `match`, `ocr_pass`).
 * @param {string} msg Texto humano.
 * @param {object} [data] Payload JSON-serializável.
 * @returns {void}
 */
function addOcrEvent(event, msg, data = {}) {
  const ts = new Date().toISOString();
  pushOcrDebug({ ts, event, msg, data });
  addOcrLog(msg);
}

/**
 * Download de ficheiro texto/JSON (OCR debug); revoga URL após ~2 s (variante local de {@link downloadTextBlob}).
 * @param {string} filename
 * @param {string} text
 * @param {string} [mime='text/plain']
 * @returns {void}
 */
function downloadTextFile(filename, text, mime = 'text/plain') {
  const blob = new Blob([text], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  try {
    a.referrerPolicy = 'no-referrer';
  } catch (_) {}
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 2000);
}

/**
 * @param {number} n
 * @param {number} [d=2] Casas decimais.
 * @returns {number|null} `null` se não finito.
 */
function safeRound(n, d = 2) {
  if (typeof n !== 'number' || !isFinite(n)) return null;
  const k = Math.pow(10, d);
  return Math.round(n * k) / k;
}

/**
 * Atualiza rótulo `#vision-label` (tipo/raridade ou estado da visão).
 * @param {string} text
 * @returns {void}
 */
function setVisionStatus(text) {
  const el = getEl('vision-label');
  if (el) el.innerText = text;
}

/**
 * Toast flutuante temporário com nome da carta reconhecida.
 * @param {string} cardName Texto já escapado para HTML no caller ou confiável.
 * @returns {void}
 */
function showScannerToast(cardName) {
  const toast = document.createElement('div');
  toast.style.cssText = `
        position: fixed; bottom: 100px; left: 50%; transform: translateX(-50%);
        background: #27ae60; color: white; padding: 8px 16px; border-radius: 30px;
        font-weight: bold; z-index: 1000003; font-size: 12px;
        animation: fadeIn 0.2s;
    `;
  toast.innerHTML = `<i class="fas fa-check-circle"></i> ${escapeHtml(cardName)}`;
  document.body.appendChild(toast);
  setTimeout(() => {
    toast.style.opacity = '0';
    setTimeout(() => toast.remove(), 500);
  }, 2000);
}

/**
 * Reconstrói sugestões em `#search-results` a partir de {@link scannerFoundCards} (imagem, preço, botão adicionar).
 * @returns {void}
 */
function updateScannerResultsUI() {
  const container = getEl('search-results');
  if (!container) return;
  if (container.innerHTML.includes('Scanner ativo') || container.innerHTML.includes('Aponte')) {
    container.innerHTML = '';
  }
  for (let sci = 0; sci < scannerFoundCards.length; sci++) {
    const card = scannerFoundCards[sci];
    const cardName = displayNameForApiCard(card);
    const cidNum = sanitizeYuGiOhCardId(card.id);
    if (cidNum == null) continue;
    const usdOcr = getTcgplayerPriceUsd(card);
    const priceOcrStr = usdOcr > 0 ? `$${usdOcr.toFixed(2)}` : 'N/A';
    const smallUrl = String(card.card_images[0].image_url_small || '')
      .trim()
      .slice(0, 2048);
    const div = document.createElement('div');
    div.className = 'suggestion-item';
    div.style.borderLeft = '3px solid #2ecc71';
    div.style.marginBottom = '8px';
    div.style.padding = '8px';
    div.innerHTML = `
            <img src="${escAttr(smallUrl)}" style="width: 60px;">
            <div class="card-info-box">
                <div class="card-name" style="color:#2ecc71; font-size:14px;">${escapeHtml(cardName)}</div>
                <div class="info-row" style="font-size:11px;">💰 ${escapeHtml(priceOcrStr)}</div>
                <button type="button" onclick="forceAddToQueue(${cidNum})" style="background:#2ecc71; color:#000; border:none; border-radius:4px; padding:4px 12px; margin-top:6px; cursor:pointer; font-weight:bold;">${escapeHtml(T('ui.queue_add_ocr'))}</button>
            </div>
        `;
    bindSuggestionItemDnD(div, { id: card.id, imgId: card.card_images[0].id, name: cardName });
    container.appendChild(div);
  }
}

// ==================== PRÉ-PROCESSAMENTO (base mobile_camera.html + calibrador opcional) ====================

/** Largura lógica do canvas enviado ao Tesseract (faixa do nome). */
const OCR_CANVAS_W = 1000;
/** Altura do canvas OCR (faixa horizontal do nome). */
const OCR_CANVAS_H = 110;
/** Deslocamento X do recorte do nome no canvas (px). */
const OCR_NAME_DST_X = 50;
const OCR_NAME_DST_Y = 10;
const OCR_NAME_DST_W = 900;
const OCR_NAME_DST_H = 85;

/**
 * Filtros baseados na versão Mobile_proxies_cards.html (que lia melhor Armadilha/Fusão/Efeito).
 * Prioridade: tipo manual > heurística RGB.
 *
 * @param {string} cardType Rótulo de tipo vindo da UI / deteção (ex.: `Magia`, `Monstro Link`).
 * @returns {string|null} Valor de `filter` CSS ou `null` para cair na heurística {@link cssFilterFromRgb}.
 */
function forcedCssFilterByCardType(cardType) {
  if (cardType === 'Magia') return 'grayscale(1) contrast(2.6) brightness(1.15)';
  if (cardType === 'Armadilha') return 'grayscale(1) contrast(1.4) brightness(1.5) saturate(0)';
  if (cardType === 'Monstro Fusão') return 'grayscale(1) contrast(1.4) brightness(1.5) saturate(0)';
  if (cardType === 'Monstro Sincro') return 'grayscale(1) invert(1) contrast(1.6) brightness(1.0)';
  if (cardType === 'Monstro Link') return 'grayscale(1) contrast(2.2) brightness(1.25)';
  // Efeito e demais monstros laranja/coloridos
  if (String(cardType || '').startsWith('Monstro'))
    return 'grayscale(1) contrast(1.8) brightness(1.2)';
  return null;
}

/** Tipos que recebem passes OCR extra (fusão/armadilha/efeito). */
const HARD_OCR_CARD_TYPES = new Set(['Armadilha', 'Monstro Fusão', 'Monstro Efeito']);

/**
 * Heurística RGB (alinhada com Mobile_proxies_cards.html V70, com detecção teal aprimorada) → string `filter` CSS.
 * @param {number} avgR
 * @param {number} avgG
 * @param {number} avgB
 * @returns {string}
 */
function cssFilterFromRgb(avgR, avgG, avgB) {
  // Verde ou teal (g+b altos, r baixo) = Magia / Spell
  const isTeal = (avgG > avgR + 20 || avgB > avgR + 20) && avgR < 130 && avgG + avgB > avgR * 2.2;
  if (isTeal) return 'grayscale(1) contrast(2.6) brightness(1.15)';
  if (avgR > 170 && avgG > 170 && avgB > 170)
    return 'grayscale(1) invert(1) contrast(1.6) brightness(1.0)'; // prata = Sincro
  if (avgR > avgG && avgB > avgG) return 'grayscale(1) contrast(1.4) brightness(1.5) saturate(0)'; // roxo = Fusão/Armadilha
  // Link/Xyz escuro (r, g, b todos baixos)
  if (avgR < 90 && avgG < 90 && avgB < 100) return 'grayscale(1) contrast(2.2) brightness(1.25)';
  return 'grayscale(1) contrast(1.8) brightness(1.2)'; // laranja = Monstro
}

/**
 * Inversão pixel a pixel RGB (mantém alpha implícito do buffer).
 * @param {CanvasRenderingContext2D} ctx
 * @param {HTMLCanvasElement} canvas
 * @returns {void}
 */
function applyPixelInvert(ctx, canvas) {
  const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const data = imgData.data;
  for (let i = 0; i < data.length; i += 4) {
    data[i] = 255 - data[i];
    data[i + 1] = 255 - data[i + 1];
    data[i + 2] = 255 - data[i + 2];
  }
  ctx.putImageData(imgData, 0, 0);
}

/**
 * Binarização global ou adaptativa (média de luminância) no canvas atual.
 * @param {CanvasRenderingContext2D} ctx
 * @param {HTMLCanvasElement} canvas
 * @param {{ threshold: number, adaptiveThreshold?: boolean }} settings
 * @returns {void}
 */
function applyThresholdBinarize(ctx, canvas, settings) {
  const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const data = imgData.data;
  let threshold = settings.threshold;
  if (settings.adaptiveThreshold) {
    let total = 0;
    for (let i = 0; i < data.length; i += 4) total += data[i];
    threshold = total / (data.length / 4);
  }
  for (let i = 0; i < data.length; i += 4) {
    const val = data[i] > threshold ? 255 : 0;
    data[i] = data[i + 1] = data[i + 2] = val;
  }
  ctx.putImageData(imgData, 0, 0);
}

/**
 * Média RGB subsampling na região do nome ({@link OCR_NAME_DST_X}…).
 * @param {CanvasRenderingContext2D} ctx
 * @returns {{ avgR: number, avgG: number, avgB: number }}
 */
function sampleNameStripAverages(ctx) {
  const imgData = ctx.getImageData(
    OCR_NAME_DST_X,
    OCR_NAME_DST_Y,
    OCR_NAME_DST_W,
    OCR_NAME_DST_H
  ).data;
  let r = 0,
    g = 0,
    b = 0;
  for (let i = 0; i < imgData.length; i += 100) {
    r += imgData[i];
    g += imgData[i + 1];
    b += imgData[i + 2];
  }
  const n = imgData.length / 100;
  return { avgR: r / n, avgG: g / n, avgB: b / n };
}

/**
 * Núcleo compartilhado com o calibrador: mesma geometria e filtros que mobile_camera.html.
 *
 * @param {CanvasImageSource} media Frame de vídeo, `Image` ou canvas com a carta.
 * @param {{ x: number, y: number, width: number, height: number }} cropRect Recorte da faixa do nome no espaço da mídia.
 * @param {{
 *   useColorAdaptive?: boolean,
 *   grayscale?: boolean,
 *   contrast?: number,
 *   brightness?: number,
 *   invert?: boolean,
 *   useBinarization?: boolean,
 *   threshold?: number|null,
 *   adaptiveThreshold?: boolean
 * }} settings Opções de pré-processamento antes do Tesseract.
 * @param {string} cardType Tipo de carta (afeta fundo, largura do texto e filtro forçado).
 * @returns {Promise<null|{
 *   text: string,
 *   confidence: number,
 *   avgR: number,
 *   avgG: number,
 *   avgB: number,
 *   cssFilter: string,
 *   appliedThreshold: number|null
 * }>} Texto/confiança e metadados de cor ou `null` sem worker ou em erro de reconhecimento.
 */
async function runOcrWithSettings(media, cropRect, settings, cardType) {
  if (!ocrWorker) return null;
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  canvas.width = OCR_CANVAS_W;
  canvas.height = OCR_CANVAS_H;
  ctx.filter = 'none';
  // Magia usa fundo branco: Tesseract é treinado para texto escuro em fundo claro.
  // Outros tipos (Sincro com invert, Fusão/Armadilha escuros) funcionam melhor com preto.
  ctx.fillStyle = cardType === 'Magia' ? 'white' : 'black';
  ctx.fillRect(0, 0, OCR_CANVAS_W, OCR_CANVAS_H);
  // Magia: margens laterais maiores (100px) — mais espaço branco ao redor do texto
  // ajuda o Tesseract PSM 7 a delimitar a linha corretamente (idêntico ao mobile_camera.html)
  const dstX = cardType === 'Magia' ? 100 : OCR_NAME_DST_X;
  const dstW = cardType === 'Magia' ? 800 : OCR_NAME_DST_W;
  ctx.drawImage(
    media,
    cropRect.x,
    cropRect.y,
    cropRect.width,
    cropRect.height,
    dstX,
    OCR_NAME_DST_Y,
    dstW,
    OCR_NAME_DST_H
  );

  const { avgR, avgG, avgB } = sampleNameStripAverages(ctx);
  let cssFilter;
  if (settings.useColorAdaptive !== false) {
    cssFilter = forcedCssFilterByCardType(cardType) || cssFilterFromRgb(avgR, avgG, avgB);
  } else {
    let fs = '';
    if (settings.grayscale) fs += 'grayscale(1) ';
    if (settings.contrast !== 1.0) fs += `contrast(${settings.contrast}) `;
    if (settings.brightness !== 1.0) fs += `brightness(${settings.brightness}) `;
    cssFilter = fs.trim() || 'none';
  }
  ctx.filter = cssFilter;
  ctx.drawImage(canvas, 0, 0);
  ctx.filter = 'none';

  if (settings.invert) applyPixelInvert(ctx, canvas);
  let appliedThreshold = null;
  if (settings.useBinarization === true) {
    appliedThreshold = settings.threshold;
    if (settings.adaptiveThreshold) {
      const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imgData.data;
      let total = 0;
      for (let i = 0; i < data.length; i += 4) total += data[i];
      appliedThreshold = total / (data.length / 4);
    }
    applyThresholdBinarize(ctx, canvas, { ...settings, threshold: appliedThreshold });
  }

  const preview = getEl('preview-canvas');
  if (preview) {
    preview.width = canvas.width;
    preview.height = canvas.height;
    preview.getContext('2d').drawImage(canvas, 0, 0);
  }

  try {
    const result = await ocrWorker.recognize(canvas);
    const conf = typeof result.data.confidence === 'number' ? result.data.confidence : 0;
    return {
      text: result.data.text,
      confidence: conf,
      avgR,
      avgG,
      avgB,
      cssFilter,
      appliedThreshold,
    };
  } catch (err) {
    return null;
  }
}

/**
 * Pipeline completo: detetar tipo (manual ou imagem), carregar calibração, {@link runOcrWithSettings} e devolver metadados.
 *
 * @param {HTMLVideoElement|HTMLImageElement|HTMLCanvasElement} video Mídia de origem.
 * @param {{ x: number, y: number, width: number, height: number }} cropRect Recorte no espaço do vídeo.
 * @param {object|null} [settingsOverride] Sobrescreve campos do preset (passes de fallback).
 * @param {string|null} [cardTypeFixed] Força tipo de carta (ex.: calibrador).
 * @returns {Promise<null|{ text: string, confidence: number, settings: object, cardType: string, rarity: string, avgR: number, avgG: number, avgB: number, cssFilter: string, appliedThreshold: number|null }>}
 */
async function processImageWithColorFilter(
  video,
  cropRect,
  settingsOverride = null,
  cardTypeFixed = null
) {
  let cardType;
  let rarity = 'Comum';
  const manualTypeSelect = getEl('manual-card-type');
  const manualRaritySelect = getEl('manual-rarity');
  if (manualTypeSelect && manualRaritySelect) {
    if (manualTypeSelect.value === 'AUTO') {
      cardType =
        cardTypeFixed != null ? cardTypeFixed : await detectCardTypeFromImage(video, cropRect);
    } else {
      cardType = manualTypeSelect.value;
    }
    rarity = manualRaritySelect.value;
  } else {
    cardType =
      cardTypeFixed != null ? cardTypeFixed : await detectCardTypeFromImage(video, cropRect);
  }

  const baseSettings = calibrator
    ? calibrator.getCalibration(cardType, rarity)
    : {
        grayscale: true,
        contrast: 1.3,
        brightness: 1,
        invert: false,
        useBinarization: false,
        useColorAdaptive: true,
        threshold: 128,
        adaptiveThreshold: false,
      };
  const settings = settingsOverride ? { ...baseSettings, ...settingsOverride } : baseSettings;

  const o = await runOcrWithSettings(video, cropRect, settings, cardType);
  if (!o) return null;
  return {
    text: o.text,
    confidence: o.confidence,
    settings,
    cardType,
    rarity,
    avgR: o.avgR,
    avgG: o.avgG,
    avgB: o.avgB,
    cssFilter: o.cssFilter,
    appliedThreshold: o.appliedThreshold,
  };
}

/**
 * Vários passes de pré-processamento por tipo de carta; em match forte atualiza calibração e devolve carta.
 *
 * @param {HTMLVideoElement} video
 * @param {{ x: number, y: number, width: number, height: number }} cropRect
 * @returns {Promise<null|{ pack: object, cleaned: string, card: object|null }>}
 */
async function processFrameWithFallbackPasses(video, cropRect) {
  let cardType = 'Monstro Efeito';
  let rarity = 'Comum';
  const manualTypeSelect = getEl('manual-card-type');
  const manualRaritySelect = getEl('manual-rarity');
  if (manualTypeSelect && manualRaritySelect) {
    if (manualTypeSelect.value === 'AUTO') {
      cardType = await detectCardTypeFromImage(video, cropRect);
    } else {
      cardType = manualTypeSelect.value;
    }
    rarity = manualRaritySelect.value;
  } else {
    cardType = await detectCardTypeFromImage(video, cropRect);
  }
  lastDetectedCardType = cardType;
  setVisionStatus(`TIPO: ${cardType} | RARIDADE: ${rarity}`);

  const base = calibrator
    ? calibrator.getCalibration(cardType, rarity)
    : { useBinarization: false };
  let passes;
  if (HARD_OCR_CARD_TYPES.has(cardType)) {
    passes = [
      null,
      {
        useBinarization: false,
        useColorAdaptive: false,
        grayscale: true,
        contrast: 1.78,
        brightness: 1.08,
      },
      {
        useBinarization: false,
        useColorAdaptive: false,
        grayscale: true,
        contrast: 1.45,
        brightness: 1.18,
      },
      { useBinarization: false, useColorAdaptive: true, invert: true },
      { useBinarization: true, adaptiveThreshold: false, invert: false },
      { useBinarization: true, adaptiveThreshold: true, invert: false },
    ];
    if (base.useBinarization === true) {
      passes.unshift({
        useBinarization: true,
        adaptiveThreshold: !!base.adaptiveThreshold,
        invert: false,
      });
      passes = passes.slice(0, 7);
    }
  } else if (cardType === 'Magia') {
    // Magia: fundo branco + filtros suaves funcionam melhor à distância (baseado em mobile_camera.html).
    // Binarização destrói o canal teal; useColorAdaptive:false permite contraste/brilho explícitos.
    passes = [
      {
        useBinarization: false,
        useColorAdaptive: false,
        grayscale: true,
        contrast: 1.6,
        brightness: 0.9,
      }, // pass 0: idêntico ao mobile_camera.html — melhor para distância
      null, // pass 1: filtro forçado (2.6/1.15) via forcedCssFilterByCardType
      {
        useBinarization: false,
        useColorAdaptive: false,
        grayscale: true,
        contrast: 2.6,
        brightness: 1.4,
      }, // mais brilho
      {
        useBinarization: false,
        useColorAdaptive: false,
        grayscale: true,
        contrast: 3.5,
        brightness: 1.1,
      }, // alto contraste (bom de perto)
      {
        useBinarization: false,
        useColorAdaptive: false,
        grayscale: true,
        contrast: 2.0,
        brightness: 1.55,
      }, // brilho máximo
    ];
  } else {
    passes = [
      null,
      { useBinarization: true, adaptiveThreshold: false },
      { useBinarization: true, adaptiveThreshold: true },
    ];
    if (base.useBinarization === true) {
      passes[0] = { useBinarization: true, adaptiveThreshold: !!base.adaptiveThreshold };
      passes[1] = { useBinarization: true, adaptiveThreshold: false };
      passes[2] = { useBinarization: true, adaptiveThreshold: true };
    }
  }
  let best = null;
  for (let pi = 0; pi < passes.length; pi++) {
    const ov = passes[pi];
    const pack = await processImageWithColorFilter(video, cropRect, ov, cardType);
    if (!pack || !pack.text) continue;
    const cleaned = smartNormalize(pack.text);
    if (!cleaned || cleaned.length < 4 || isGarbageText(cleaned)) continue;
    pushOcrDebug({
      ts: new Date().toISOString(),
      event: 'ocr_pass',
      msg: `pass=${pi} type=${cardType} rarity=${rarity}`,
      data: {
        pass: pi,
        cardType,
        rarity,
        cropRect: {
          x: safeRound(cropRect.x, 1),
          y: safeRound(cropRect.y, 1),
          width: safeRound(cropRect.width, 1),
          height: safeRound(cropRect.height, 1),
        },
        dstRect: {
          x: OCR_NAME_DST_X,
          y: OCR_NAME_DST_Y,
          width: OCR_NAME_DST_W,
          height: OCR_NAME_DST_H,
        },
        settings: pack.settings,
        confidence: safeRound(pack.confidence, 1),
        avgRGB: {
          r: safeRound(pack.avgR, 1),
          g: safeRound(pack.avgG, 1),
          b: safeRound(pack.avgB, 1),
        },
        cssFilter: pack.cssFilter,
        appliedThreshold: safeRound(pack.appliedThreshold, 1),
        rawText: pack.text,
        cleaned,
      },
    });
    const card = await smartSearch(cleaned, pi > 0, cleaned);
    const strong = card ? isStrongMatch(cleaned, card) : false;
    if (card && !strong) {
      pushOcrDebug({
        ts: new Date().toISOString(),
        event: 'match_rejected',
        msg: 'candidate rejected by strong-match gate',
        data: {
          pass: pi,
          ocr: cleaned,
          candidate: displayNameForApiCard(card),
        },
      });
    }
    if (card && strong) {
      const merged = { ...pack.settings, ...(ov || {}) };
      calibrator?.setCalibration(pack.cardType, pack.rarity, merged);
      addOcrEvent(
        'match',
        ov
          ? '🎯 Match com binarização — calibração atualizada'
          : '🎯 Match — calibração confirmada',
        {
          pass: pi,
          cardType: pack.cardType,
          rarity: pack.rarity,
          ocr: cleaned,
          matchedName: displayNameForApiCard(card),
          confidence: safeRound(pack.confidence, 1),
          cssFilter: pack.cssFilter,
          appliedThreshold: safeRound(pack.appliedThreshold, 1),
          settingsSaved: merged,
        }
      );
      return { pack, cleaned, card };
    }
    if (!best || pack.confidence > best.pack.confidence) best = { pack, cleaned };
  }
  if (best) return { pack: best.pack, cleaned: best.cleaned, card: null };
  return null;
}

// ==================== PROCESSAMENTO DO FRAME ====================

/**
 * Um ciclo do loop de OCR: mapeia `#scanner-visual` para coordenadas do vídeo, processa e atualiza lista/toasts.
 * @returns {Promise<void>}
 */
async function processOcrFrame() {
  if (!isOcrActive || isProcessing || processingCooldown) {
    requestAnimationFrame(processOcrFrame);
    return;
  }
  const video = getEl('ocr-video');
  if (!video || video.videoWidth === 0) {
    requestAnimationFrame(processOcrFrame);
    return;
  }
  isProcessing = true;
  try {
    const visualBox = getEl('scanner-visual');
    const vRect = video.getBoundingClientRect();
    const mRect = visualBox.getBoundingClientRect();
    const vW = video.videoWidth,
      vH = video.videoHeight;
    const s = vW / vH > vRect.width / vRect.height ? vH / vRect.height : vW / vRect.width;
    const xO = (vW - vRect.width * s) / 2;
    const yO = (vH - vRect.height * s) / 2;
    const cropRect = {
      x: (mRect.left - vRect.left) * s + xO,
      y: (mRect.top - vRect.top) * s + yO,
      width: mRect.width * s,
      height: mRect.height * s,
    };

    const outcome = await processFrameWithFallbackPasses(video, cropRect);
    if (outcome && outcome.cleaned) {
      if (outcome.cleaned !== lastMatchedText) addOcrLog(`📖 "${outcome.cleaned}"`);
      if (outcome.card) {
        const cardName = displayNameForApiCard(outcome.card);
        triggerScanHaptic(outcome.card.id);
        if (!scannerFoundCardIds.has(outcome.card.id)) {
          scannerFoundCardIds.add(outcome.card.id);
          scannerFoundCardById.set(String(outcome.card.id), outcome.card);
          scannerFoundCards.push(outcome.card);
          lastMatchedText = cardName;
          lastMatchTime = Date.now();
          showScannerToast(cardName);
          addOcrLog(`✅ ${cardName}`);
          updateScannerResultsUI();
          processingCooldown = true;
          setTimeout(() => {
            processingCooldown = false;
          }, 1200);
        }
      }
    }
  } catch (err) {
    console.error('Frame error:', err);
  }
  isProcessing = false;
  setTimeout(() => {
    if (isOcrActive) requestAnimationFrame(processOcrFrame);
  }, 400);
}

// ==================== INICIAR SCANNER ====================

/**
 * Mostra UI OCR, pede `getUserMedia`, inicializa Tesseract se necessário e inicia {@link processOcrFrame}.
 * @returns {Promise<void>}
 */
async function startScanner() {
  const container = getEl('ocr-container');
  const video = getEl('ocr-video');
  if (container) container.style.display = 'block';
  scannerFoundCards = [];
  scannerFoundCardIds = new Set();
  scannerFoundCardById = new Map();
  lastMatchedText = '';
  lastApiSearchCleaned = '';
  lastScanHapticKey = '';
  lastScanHapticTime = 0;
  cardCacheAPI.clear();
  fnameRawCache.clear();
  const resultsContainer = getEl('search-results');
  if (resultsContainer) {
    resultsContainer.innerHTML =
      '<div style="text-align:center; padding:30px; color:#2ecc71;">🎯 Aponte a mira no NOME da carta</div>';
  }
  try {
    addOcrLog('🎥 Iniciando câmera...');
    const stream = await navigator.mediaDevices.getUserMedia({
      video: { facingMode: 'environment', width: { ideal: 1280 } },
    });
    video.srcObject = stream;
    await video.play();
    try {
      const track = stream.getVideoTracks()[0];
      const capabilities = track.getCapabilities();
      if (capabilities.focusMode) {
        if (capabilities.focusMode.includes('continuous')) {
          await track.applyConstraints({ advanced: [{ focusMode: 'continuous' }] });
          addOcrLog('🎯 Foco contínuo');
        } else if (capabilities.focusMode.includes('auto')) {
          await track.applyConstraints({ advanced: [{ focusMode: 'auto' }] });
          addOcrLog('🎯 Foco automático');
        }
      }
      if (capabilities.zoom) {
        const maxZoom = capabilities.zoom.max;
        const zoom = Math.min(maxZoom, 1.5);
        await track.applyConstraints({ advanced: [{ zoom: zoom }] });
        addOcrLog(`🔍 Zoom: ${zoom}x`);
      }
    } catch (e) {}
    video.addEventListener('click', async (e) => {
      try {
        const track = stream.getVideoTracks()[0];
        if (track && track.applyConstraints) {
          await track.applyConstraints({ advanced: [{ focusMode: 'manual', focusDistance: 1.0 }] });
          addOcrLog('🔍 Foco manual');
          setTimeout(async () => {
            try {
              await track.applyConstraints({ advanced: [{ focusMode: 'continuous' }] });
            } catch (e) {}
          }, 3000);
        }
      } catch (e) {}
    });
    if (!ocrWorker) {
      addOcrLog('🧠 Carregando Tesseract...');
      ocrWorker = await Tesseract.createWorker();
      await ocrWorker.loadLanguage('eng');
      await ocrWorker.initialize('eng');
      await ocrWorker.setParameters({
        tessedit_char_whitelist: 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 ,:ÁÉÍÓÚÂÊÎÔÛÃÕÇ',
        tessedit_pageseg_mode: '7',
      });
      addOcrLog('✅ OCR pronto!');
    }
    isOcrActive = true;
    addOcrLog('🔍 Escaneando...');
    requestAnimationFrame(processOcrFrame);
  } catch (err) {
    addOcrLog(`❌ Erro: ${err.message}`);
  }
}

/**
 * Encerra loop OCR, para tracks do vídeo e limpa `srcObject`.
 * @returns {void}
 */
function stopScanner() {
  isOcrActive = false;
  const video = getEl('ocr-video');
  if (video && video.srcObject) {
    const tk = video.srcObject.getTracks();
    for (let tki = 0; tki < tk.length; tki++) tk[tki].stop();
    video.srcObject = null;
  }
}

// ==================== FUNÇÕES DE UI ====================

/**
 * Handler HTML (`onclick` nas sugestões OCR): adiciona `qty` cópias da carta reconhecida à construção.
 * @param {string|number} cardId ID numérico Yu-Gi-Oh (lookup em {@link scannerFoundCardById}).
 * @returns {void}
 */
window.forceAddToQueue = (cardId) => {
  const card = scannerFoundCardById ? scannerFoundCardById.get(String(cardId)) : null;
  if (card) {
    const qtyEl = getEl('search-qty');
    const qty = Math.max(1, int10(qtyEl && qtyEl.value, 1) || 1);
    for (let i = 0; i < qty; i++) {
      cardQueue.push({
        id: card.id,
        name: displayNameForApiCard(card),
        imgId: card.card_images[0].id,
      });
    }
    updateUI();
    showToast(T('toast.added_qty', { qty, name: displayNameForApiCard(card) }));
    if (__hasUserGesture && navigator.vibrate) navigator.vibrate(50);
  }
};

/**
 * Copia texto bruto de `#ocr-log` para a área de transferência.
 * @returns {void}
 */
window.copyLogs = () => {
  const logElement = getEl('ocr-log');
  if (logElement) {
    navigator.clipboard.writeText(logElement.innerText);
    showToast(T('toast.logs_copied'));
  }
};

/**
 * Descarrega JSON com buffer de debug OCR e último snapshot (`ocr_debug_<timestamp>.json`).
 * @returns {void}
 */
window.exportOcrDebug = () => {
  const payload = {
    exportedAt: new Date().toISOString(),
    userAgent: navigator.userAgent,
    lastSnapshot: lastOcrDebugSnapshot,
    entries: ocrDebugBuffer,
  };
  downloadTextFile(
    `ocr_debug_${Date.now()}.json`,
    JSON.stringify(payload, null, 2),
    'application/json'
  );
  showToast(T('toast.debug_exported'));
};

/**
 * Gera PNG composto (pré-visualização + trecho de log + snapshot) e também chama {@link window.exportOcrDebug}.
 * @returns {void}
 */
window.takeScreenshot = () => {
  const previewCanvas = getEl('preview-canvas');
  const canvas = document.createElement('canvas');
  canvas.width = previewCanvas?.width || 500;
  canvas.height = 260;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  if (previewCanvas) {
    ctx.drawImage(previewCanvas, 0, 0, canvas.width, 80);
  }
  ctx.fillStyle = '#0f0';
  ctx.font = '10px monospace';
  const topLogs = getEl('ocr-log')?.innerText.split('\n').slice(0, 10) || [];
  const snap = lastOcrDebugSnapshot;
  const header = snap ? `[${snap.ts}] ${snap.event}: ${snap.msg || ''}` : '(sem snapshot)';
  const details = snap?.data ? JSON.stringify(snap.data).slice(0, 240) : '';
  const lines = [
    header,
    details ? `data: ${details}${details.length >= 240 ? '...' : ''}` : '',
    ...topLogs,
  ].filter(Boolean);
  let y = 100;
  for (const line of lines.slice(0, 14)) {
    ctx.fillText(line, 10, y);
    y += 12;
  }
  const link = document.createElement('a');
  link.download = `ocr_${Date.now()}.png`;
  link.href = canvas.toDataURL('image/png');
  try {
    link.referrerPolicy = 'no-referrer';
  } catch (_) {}
  link.click();
  // Também exporta o JSON junto (mais útil pra análise)
  window.exportOcrDebug?.();
  showToast(T('toast.screenshot_saved'));
};

// ==================== EVENT LISTENERS ====================

/**
 * Clona `#btn-open-calibrator` para remover listeners antigos e abrir {@link openCalibrator} ao clique.
 * @returns {void}
 */
function setupCalibratorButton() {
  const calibratorBtn = getEl('btn-open-calibrator');
  if (calibratorBtn) {
    const newBtn = calibratorBtn.cloneNode(true);
    calibratorBtn.parentNode.replaceChild(newBtn, calibratorBtn);
    newBtn.addEventListener('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      console.log('🔧 Botão CALIBRAR OCR clicado!');
      openCalibrator(); // chama a calibração automática
    });
  }
}

document.addEventListener('click', (e) => {
  if (e.target.id === 'btn-open-scanner' || e.target.closest('#btn-open-scanner')) {
    e.preventDefault();
    const resultsView = getEl('results-view');
    if (resultsView)
      resultsView.innerHTML =
        '<div style="grid-column:1/-1; text-align:center; color:#2ecc71; padding:20px;">🤖 ' +
        T('ocr.scanner_active') +
        '</div>';
    scannerFoundCards = [];
    lastMatchedText = '';
    startScanner();
    setTimeout(setupCalibratorButton, 1000);
  }
  if (e.target.id === 'btn-close-ocr' || e.target.closest('#btn-close-ocr')) {
    stopScanner();
    const c = getEl('ocr-container');
    if (c) c.style.display = 'none';
    if (scannerFoundCards.length > 0) {
      clearRandomPickState();
      searchResults = scannerFoundCards.map((card) => ({
        ...card,
        current_image: card.card_images[0],
        variant_idx: 0,
        is_variant: card.card_images.length > 1,
      }));
      currentPage = 1;
      if (typeof sortAndRender === 'function') sortAndRender();
      showToast(T('toast.scanner_cards', { n: scannerFoundCards.length }));
    } else {
      const resultsView = getEl('results-view');
      if (resultsView) {
        resultsView.innerHTML =
          "<div style='grid-column:1/-1; text-align:center; padding:20px; color:#e74c3c;'>🤖 " +
          T('ocr.no_cards') +
          '</div>';
      }
    }
  }
});

document.addEventListener('DOMContentLoaded', () => {
  setupCalibratorButton();
});

