// ==================== CALIBRADOR DE OCR ====================

/**
 * Persistência em `localStorage` (`ocr_calibrations`, schema `5`) de filtros por par tipo+raridade;
 * {@link autoOptimize} varre combinações e grava a melhor via {@link setCalibration}.
 */
class OCRCalibrator {
  /**
   * Inicializa estado em memória, flags de fluxo e {@link loadCalibrations}.
   * @returns {void}
   */
  constructor() {
    /** @type {Record<string, object>} */
    this.calibrations = this.loadCalibrations();
    this.isCalibrating = false;
    this.currentTestCard = null;
    /** @type {object[]} */
    this.testResults = [];
    this.cancelRequested = false;
  }

  /**
   * Objeto base de flags de filtro antes de presets tipo/raridade.
   * @returns {object} Clonável por spreads em {@link getCalibration} / variações.
   */
  getDefaultFilters() {
    return {
      grayscale: true,
      contrast: 1.3,
      brightness: 1.0,
      sharpen: 0,
      threshold: 128,
      adaptiveThreshold: false,
      invert: false,
      useBinarization: false,
      useColorAdaptive: true,
      denoise: false,
      erode: false,
      dilate: false,
    };
  }

  /**
   * Ajustes sugeridos por tipo de carta (chave = valor do `<select>` manual).
   * @returns {Object<string, object>} Mapa tipo → subset de flags sobreposto ao default.
   */
  getTypePresets() {
    return {
      'Monstro Normal': { contrast: 1.4, brightness: 0.95, threshold: 130, invert: false },
      'Monstro Efeito': { contrast: 1.48, brightness: 1.02, threshold: 126, invert: false },
      'Monstro Ritual': { contrast: 1.35, brightness: 0.98, threshold: 125, invert: false },
      'Monstro Fusão': { contrast: 1.42, brightness: 1.05, threshold: 124, invert: false },
      'Monstro Sincro': { contrast: 1.6, brightness: 1.0, threshold: 115, invert: true },
      'Monstro Xyz': { contrast: 1.4, brightness: 0.92, threshold: 125, invert: false },
      'Monstro Link': { contrast: 1.45, brightness: 0.93, threshold: 120, invert: false },
      'Monstro Pêndulo': { contrast: 1.4, brightness: 0.94, threshold: 125, invert: false },
      Magia: { contrast: 1.35, brightness: 0.97, threshold: 115, invert: false },
      Armadilha: { contrast: 1.42, brightness: 1.04, threshold: 122, invert: false },
      Ficha: { contrast: 1.3, brightness: 0.96, threshold: 120, invert: false },
    };
  }

  /**
   * Ajustes sugeridos por raridade física (aproximação para OCR).
   * @returns {Object<string, object>} Mapa raridade → subset de flags.
   */
  getRarityPresets() {
    return {
      Comum: { contrast: 1.35, brightness: 0.96, threshold: 125 },
      Rara: { contrast: 1.4, brightness: 0.95, threshold: 128 },
      'Super Rara': { contrast: 1.45, brightness: 0.93, threshold: 130 },
      'Ultra Rara': { contrast: 1.5, brightness: 0.92, threshold: 132 },
      Secreta: { contrast: 1.55, brightness: 0.9, threshold: 135, invert: true },
      Platina: { contrast: 1.5, brightness: 0.91, threshold: 133 },
      Starlight: { contrast: 1.6, brightness: 0.88, threshold: 140, invert: true },
      Ouro: { contrast: 1.45, brightness: 0.94, threshold: 128 },
      Prata: { contrast: 1.4, brightness: 0.95, threshold: 125 },
    };
  }

  /**
   * Lê `localStorage`; se schema ≠ `5`, limpa dados antigos.
   * @returns {Record<string, object>} Mapa chave `tipo|raridade` → settings persistidos.
   */
  loadCalibrations() {
    const schema = localStorage.getItem('ocr_calib_schema');
    if (schema !== '5') {
      try {
        localStorage.removeItem('ocr_calibrations');
        localStorage.setItem('ocr_calib_schema', '5');
      } catch (e) {}
      return {};
    }
    const saved = localStorage.getItem('ocr_calibrations');
    if (saved) {
      const o = safeJsonParse(saved, null);
      if (o && typeof o === 'object' && !Array.isArray(o)) return o;
    }
    return {};
  }

  /**
   * Persiste `this.calibrations` em JSON no `localStorage`.
   * @returns {void}
   */
  saveCalibrations() {
    localStorage.setItem('ocr_calibrations', JSON.stringify(this.calibrations));
  }

  /**
   * Preset mesclado: defaults + tipo + raridade + override salvo (força `useColorAdaptive: true`).
   * @param {string} cardType Valor do select manual (ex.: `Monstro Efeito`, `Magia`).
   * @param {string} rarity Raridade física aproximada (ex.: `Comum`, `Secreta`).
   * @returns {object} Settings completos passíveis de {@link runOcrWithSettings}.
   */
  getCalibration(cardType, rarity) {
    const key = `${cardType}|${rarity}`;
    const typePreset = this.getTypePresets()[cardType] || {};
    const rarityPreset = this.getRarityPresets()[rarity] || {};
    const base = { ...this.getDefaultFilters(), ...typePreset, ...rarityPreset };
    if (this.calibrations[key]) {
      const saved = this.calibrations[key];
      // Garante que filtro de cor adaptativo nunca é desligado por calibração salva
      return { ...base, ...saved, useColorAdaptive: true };
    }
    return base;
  }

  /**
   * Grava override para o par `cardType|rarity` (ignora `useColorAdaptive: false` ao salvar).
   * @param {string} cardType Chave de tipo (mesmo vocabulário de {@link getTypePresets}).
   * @param {string} rarity Chave de raridade (mesmo vocabulário de {@link getRarityPresets}).
   * @param {object} settings Flags a persistir; `useColorAdaptive` forçado a `true` na gravação.
   * @returns {void}
   */
  setCalibration(cardType, rarity, settings) {
    const key = `${cardType}|${rarity}`;
    // Nunca salvar useColorAdaptive=false: mantém o filtro de cor automático ativo
    // (evita que uma calibração específica bloqueie o filtro para outras cartas do mesmo tipo)
    const { useColorAdaptive: _ignored, ...rest } = settings;
    this.calibrations[key] = { ...rest, useColorAdaptive: true };
    this.saveCalibrations();
  }

  /**
   * Aplica filtros CSS + opcional invert/binarização no mesmo canvas (uso UI calibrador).
   * @param {CanvasRenderingContext2D} ctx Contexto do canvas de pré-visualização.
   * @param {HTMLCanvasElement} canvas Superfície já desenhada com o recorte OCR.
   * @param {object} settings Mesmo shape que {@link getDefaultFilters} + overrides.
   * @returns {{ filterString: string, threshold: number }} Cadeia `filter` aplicada e limiar efetivo pós-adaptativo.
   */
  applyFilters(ctx, canvas, settings) {
    ctx.filter = 'none';
    let filterString = '';
    if (settings.grayscale) filterString += 'grayscale(1) ';
    if (settings.contrast !== 1.0) filterString += `contrast(${settings.contrast}) `;
    if (settings.brightness !== 1.0) filterString += `brightness(${settings.brightness}) `;
    if (settings.sharpen > 0) filterString += `sharpen(${settings.sharpen}) `;
    ctx.filter = filterString;
    ctx.drawImage(canvas, 0, 0);
    if (settings.invert) {
      const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imgData.data;
      for (let i = 0; i < data.length; i += 4) {
        data[i] = 255 - data[i];
        data[i + 1] = 255 - data[i + 1];
        data[i + 2] = 255 - data[i + 2];
      }
      ctx.putImageData(imgData, 0, 0);
    }
    let threshold = settings.threshold;
    if (settings.useBinarization === true) {
      const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const data = imgData.data;
      if (settings.adaptiveThreshold) {
        let total = 0;
        for (let i = 0; i < data.length; i += 4) total += data[i];
        threshold = total / (data.length / 4);
      }
      for (let i = 0; i < data.length; i += 4) {
        const val = data[i] > threshold ? 255 : 0;
        data[i] = data[i + 1] = data[i + 2] = val;
      }
      ctx.putImageData(imgData, 0, 0);
    }
    return { filterString, threshold };
  }

  /**
   * Uma execução OCR de teste com {@link runOcrWithSettings} e validação {@link isGarbageText}.
   *
   * @param {CanvasImageSource} imageElement Frame ou imagem com a carta alinhada ao recorte.
   * @param {{ x: number, y: number, width: number, height: number }} cropRect Faixa do nome no espaço da imagem.
   * @param {object} settings Flags de pré-processamento (mescla de presets + overrides).
   * @param {string} [cardType] Tipo manual para filtros; default interno `Monstro Efeito` se omitido em chamadas internas.
   * @returns {Promise<{ success: boolean, text?: string, cleaned?: string, settings?: object, error?: string }>}
   */
  async testConfiguration(imageElement, cropRect, settings, cardType) {
    if (!ocrWorker) return { success: false, error: 'ocrWorker not ready' };
    if (
      !cropRect ||
      isNaN(cropRect.x) ||
      isNaN(cropRect.y) ||
      cropRect.width <= 0 ||
      cropRect.height <= 0
    ) {
      return { success: false, error: 'invalid crop rect' };
    }
    try {
      const o = await runOcrWithSettings(
        imageElement,
        cropRect,
        settings,
        cardType || 'Monstro Efeito'
      );
      if (!o) return { success: false, error: 'ocr failed' };
      const cleaned = smartNormalize(o.text);
      return {
        text: o.text,
        cleaned,
        settings,
        success: !!(cleaned && cleaned.length >= 4 && !isGarbageText(cleaned)),
      };
    } catch (err) {
      console.error('testConfiguration error:', err);
      return { success: false, error: err.message };
    }
  }

  /**
   * Varre {@link generateVariations}, pontua por match API + confiança e grava melhor calibração.
   *
   * @param {CanvasImageSource} imageElement Mídia usada nos testes OCR.
   * @param {{ x: number, y: number, width: number, height: number }} cropRect Recorte do nome.
   * @param {string} cardType Tipo da carta sob calibração.
   * @param {string} rarity Raridade física associada ao preset.
   * @returns {Promise<object|null>} Melhor resultado (inclui `cleaned`, `settings`, opcionalmente `matchedName`) ou `null`.
   */
  async autoOptimize(imageElement, cropRect, cardType, rarity) {
    console.log('🚀 autoOptimize iniciado');
    this.isCalibrating = true;
    this.cancelRequested = false;
    this.testResults = [];

    const baseSettings = this.getCalibration(cardType, rarity);
    const variations = this.generateVariations(baseSettings, cardType);
    console.log(`🔧 Variações geradas: ${variations.length}`);
    if (variations.length === 0) return null;

    let bestResult = null;
    let bestScore = -1;
    let currentTest = 0;

    for (const settings of variations) {
      if (this.cancelRequested) break;
      currentTest++;
      console.log(
        `🔬 Teste ${currentTest}/${variations.length}: contraste=${settings.contrast}, brilho=${settings.brightness}, threshold=${settings.threshold}`
      );
      window.dispatchEvent(
        new CustomEvent('calibrationProgress', {
          detail: { current: currentTest, total: variations.length },
        })
      );

      try {
        const result = await this.testConfiguration(imageElement, cropRect, settings, cardType);
        this.testResults.push(result);
        if (result.success && result.cleaned) {
          // Pontua por match real na API (evita calibrar em texto "bonito" mas errado)
          let score = 0;
          let matched = null;
          try {
            matched = await smartSearch(result.cleaned, true, result.cleaned);
          } catch (e) {}
          if (matched && isStrongMatch(result.cleaned, matched)) {
            score =
              1000 +
              (typeof result.confidence === 'number' ? result.confidence : 0) +
              result.cleaned.length;
            // Achou match forte: pode encerrar cedo
            bestScore = score;
            bestResult = { ...result, matchedName: displayNameForApiCard(matched) };
            addOcrEvent('calibration_hit', `🎯 Calibração achou match: ${bestResult.matchedName}`, {
              cleaned: result.cleaned,
            });
            break;
          } else {
            // fallback: maximize legibilidade, mas com peso baixo
            score =
              (typeof result.confidence === 'number' ? result.confidence : 0) +
              result.cleaned.length * 2;
            if (score > bestScore) {
              bestScore = score;
              bestResult = result;
              console.log(`   🏆 Nova melhor pontuação: ${score}`);
            }
          }
        }
      } catch (err) {
        console.error(`   ❌ Erro no teste ${currentTest}:`, err);
      }
      await new Promise((r) => setTimeout(r, 140)); // pausa maior (evita travar no mobile)
    }

    if (bestResult) {
      this.setCalibration(cardType, rarity, bestResult.settings);
      addOcrLog(`✅ Calibração otimizada para ${cardType} (${rarity})`);
      addOcrLog(`📖 Melhor leitura: "${bestResult.cleaned}"`);
      return bestResult;
    }
    return null;
  }

  /**
   * Lista limitada (24–28) de variações de contraste/brilho/limiar para não travar mobile.
   *
   * @param {object} baseSettings Ponto de partida (tipicamente {@link getCalibration}).
   * @param {string} cardType Controla ramo “hard” em {@link HARD_OCR_CARD_TYPES} (mais variações).
   * @returns {Array<object>} Lista curta de objetos settings para testar em sequência.
   */
  generateVariations(baseSettings, cardType) {
    const variations = [];
    const b = { ...baseSettings };
    const hard = typeof HARD_OCR_CARD_TYPES !== 'undefined' && HARD_OCR_CARD_TYPES.has(cardType);
    // Menos variações = menos travamento no celular. Mantém diversidade suficiente.
    for (const contrast of [1.25, 1.45, 1.65])
      variations.push({ ...b, contrast, useBinarization: false, useColorAdaptive: true });
    for (const brightness of [0.9, 0.98, 1.06])
      variations.push({ ...b, brightness, useBinarization: false, useColorAdaptive: true });
    for (const threshold of [120, 135, 150]) {
      variations.push({ ...b, threshold, useBinarization: true, adaptiveThreshold: false });
      variations.push({ ...b, threshold, useBinarization: true, adaptiveThreshold: true });
    }
    variations.push({ ...b, invert: true, useBinarization: false, useColorAdaptive: true });
    variations.push({
      ...b,
      invert: false,
      useBinarization: false,
      useColorAdaptive: true,
      contrast: 1.55,
      brightness: 1.1,
    });
    variations.push({
      ...b,
      invert: false,
      useBinarization: false,
      useColorAdaptive: true,
      contrast: 1.22,
      brightness: 1.08,
    });
    variations.push({
      ...b,
      useColorAdaptive: false,
      grayscale: true,
      contrast: 1.6,
      brightness: 1.0,
      useBinarization: false,
    });
    variations.push({
      ...b,
      threshold: 105,
      useBinarization: true,
      adaptiveThreshold: false,
      invert: false,
    });
    variations.push({
      ...b,
      threshold: 152,
      useBinarization: true,
      adaptiveThreshold: true,
      invert: false,
    });
    if (hard) {
      variations.push({
        ...b,
        useBinarization: false,
        useColorAdaptive: false,
        grayscale: true,
        contrast: 1.78,
        brightness: 1.1,
      });
      variations.push({
        ...b,
        useBinarization: false,
        useColorAdaptive: false,
        grayscale: true,
        contrast: 1.48,
        brightness: 1.18,
      });
      variations.push({ ...b, useBinarization: false, useColorAdaptive: true, invert: true });
      variations.push({
        ...b,
        useBinarization: false,
        useColorAdaptive: true,
        contrast: 1.85,
        brightness: 0.95,
      });
    }
    return variations.slice(0, hard ? 28 : 24);
  }
}

/** Instância global usada por {@link processImageWithColorFilter} e {@link autoCalibrate}. */
const calibrator = new OCRCalibrator();

// ==================== CALIBRADOR AUTOMÁTICO ====================

/**
 * Heurística de cor média no recorte do vídeo → rótulo de tipo (`Magia`, `Armadilha`, famílias de monstro…).
 * @param {HTMLVideoElement} video
 * @param {{ x: number, y: number, width: number, height: number }} cropRect
 * @returns {Promise<string>}
 */
function detectCardTypeFromImage(video, cropRect) {
  return new Promise((resolve) => {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    canvas.width = 100;
    canvas.height = 50;
    ctx.drawImage(video, cropRect.x, cropRect.y, cropRect.width, cropRect.height, 0, 0, 100, 50);
    const imgData = ctx.getImageData(0, 0, 100, 50).data;
    let r = 0,
      g = 0,
      b = 0;
    let sampleCount = 0;
    for (let i = 0; i < imgData.length; i += 100) {
      r += imgData[i];
      g += imgData[i + 1];
      b += imgData[i + 2];
      sampleCount++;
    }
    const avgR = r / sampleCount,
      avgG = g / sampleCount,
      avgB = b / sampleCount;
    const lum = (avgR + avgG + avgB) / 3;
    const spread = Math.max(avgR, avgG, avgB) - Math.min(avgR, avgG, avgB);

    // Verde ou teal (verde+azul) -> Magia (fundo pode ser verde puro ou verde-azulado)
    const isTeal = (avgG > avgR + 20 || avgB > avgR + 20) && avgR < 130 && avgG + avgB > avgR * 2.2;
    if ((avgG > avgR + 30 && avgG > avgB + 30 && avgG > 100) || isTeal) {
      resolve('Magia');
    }
    // Laranja/marrom -> Monstro Normal
    else if (avgR > avgG && avgR > avgB && avgR > 150 && avgG > 100) {
      resolve('Monstro Normal');
    }
    // Roxo/rosa -> Armadilha
    else if (avgR > avgG && avgB > avgG && avgR > 100 && avgB > 100) {
      resolve('Armadilha');
    }
    // Cinza/prata brilhante -> Monstro Sincro
    else if (avgR > 180 && avgG > 180 && avgB > 180) {
      resolve('Monstro Sincro');
    }
    // Prata/cinza sob luz quente (RGB ~120–170): mesmo padrão neutro que o Sincro, antes caía em Efeito
    else if (
      lum > 118 &&
      lum < 188 &&
      spread < 48 &&
      avgR > 92 &&
      avgG > 88 &&
      avgB > 80 &&
      avgG < avgR + 35 &&
      avgB < avgR + 40
    ) {
      resolve('Monstro Sincro');
    }
    // Preto/azul escuro -> Monstro Xyz ou Link
    else if (avgR < 80 && avgG < 80 && avgB > 100) {
      resolve('Monstro Xyz');
    }
    // Roxo forte (Fusão)
    else if (avgR > 150 && avgG < 100 && avgB > 150) {
      resolve('Monstro Fusão');
    }
    // Azul claro (Ritual)
    else if (avgB > avgR + 30 && avgB > avgG + 30 && avgB > 120) {
      resolve('Monstro Ritual');
    } else {
      resolve('Monstro Efeito');
    }
  });
}

/**
 * Placeholder: sempre resolve `'Comum'` (raridade vem do `<select>` manual).
 * @param {HTMLVideoElement} video Não usado (assinatura alinhada a {@link detectCardTypeFromImage}).
 * @param {{ x: number, y: number, width: number, height: number }} cropRect Não usado.
 * @returns {Promise<string>}
 */
function detectRarityFromImage(video, cropRect) {
  return new Promise((resolve) => {
    resolve('Comum');
  });
}

/**
 * Pausa o scanner, corre {@link OCRCalibrator#autoOptimize} no frame atual e retoma ou mostra toasts de resultado.
 * @returns {Promise<void>}
 */
async function autoCalibrate() {
  if (!calibrator) {
    addOcrLog('⏳ Calibrador ainda não inicializado. Tente novamente.');
    return;
  }

  addOcrLog('🔧 Iniciando calibração automática...');
  showToast(T('toast.ocr_calibrating'));

  const video = getEl('ocr-video');
  if (!video || video.videoWidth === 0) {
    addOcrLog('❌ Câmera não está ativa');
    showToast(T('toast.scanner_enable'));
    return;
  }

  // Obtém tipo e raridade manuais (ou fallback); `let` porque `AUTO` substitui por deteção.
  let cardType = String(getVal('manual-card-type', 'Monstro Efeito')) || 'Monstro Efeito';
  const rarity = String(getVal('manual-rarity', 'Comum')) || 'Comum';

  // Pausa o scanner
  const wasActive = isOcrActive;
  if (wasActive) isOcrActive = false;

  // Calcula cropRect (igual ao que você já tem)
  const visualBox = getEl('scanner-visual');
  const vRect = video.getBoundingClientRect();
  const mRect = visualBox.getBoundingClientRect();
  const vW = video.videoWidth,
    vH = video.videoHeight;
  const s = vW / vH > vRect.width / vRect.height ? vH / vRect.height : vW / vRect.width;
  const xO = (vW - vRect.width * s) / 2;
  const yO = (vH - vRect.height * s) / 2;
  const cropRect = {
    x: (mRect.left - vRect.left) * s + xO,
    y: (mRect.top - vRect.top) * s + yO,
    width: mRect.width * s,
    height: mRect.height * s,
  };

  if (cardType === 'AUTO') {
    try {
      const detected = await detectCardTypeFromImage(video, cropRect);
      addOcrEvent('type_detected', `🧭 Tipo detectado: ${detected}`, { detected });
      cardType = detected;
    } catch (e) {
      cardType = 'Monstro Efeito';
      addOcrEvent('type_detected', `🧭 Tipo detectado: ${cardType} (fallback)`, {
        detected: cardType,
      });
    }
  }
  setVisionStatus(`CALIBRANDO | TIPO: ${cardType} | RARIDADE: ${rarity}`);
  addOcrLog(`📋 Tipo selecionado: ${cardType}, Raridade: ${rarity}`);

  // Toast de progresso
  const progressToast = document.createElement('div');
  progressToast.style.cssText = `position:fixed; bottom:150px; left:50%; transform:translateX(-50%); background:#2c3e50; color:#2ecc71; padding:8px 16px; border-radius:20px; font-size:11px; z-index:1000003; font-family:monospace; white-space:nowrap;`;
  progressToast.innerHTML = `🔧 Testando configurações... (toque para cancelar)`;
  document.body.appendChild(progressToast);
  progressToast.addEventListener(
    'click',
    () => {
      try {
        calibrator.cancelRequested = true;
        // Evita spam por múltiplos toques
        if (progressToast.dataset.cancelled !== '1') {
          progressToast.dataset.cancelled = '1';
          addOcrEvent('calibration_cancel', '🛑 Calibração cancelada pelo usuário', {});
        }
        progressToast.innerHTML = `🛑 Cancelando... (aguarde o teste atual)`;
        progressToast.style.pointerEvents = 'none';
        // Failsafe: retoma scanner em alguns segundos mesmo se o OCR demorar
        setTimeout(() => {
          try {
            if (!isOcrActive) {
              isOcrActive = true;
              isProcessing = false;
              processingCooldown = false;
              requestAnimationFrame(processOcrFrame);
              addOcrLog('🔄 Scanner retomado após cancelamento');
            }
          } catch (e) {}
        }, 2200);
      } catch (e) {}
    },
    { passive: true }
  );

  const onProgress = (e) => {
    progressToast.innerHTML = `🔧 Testando configurações... ${e.detail.current}/${e.detail.total}`;
  };
  window.addEventListener('calibrationProgress', onProgress);

  let result = null;
  try {
    result = await calibrator.autoOptimize(video, cropRect, cardType, rarity);
  } catch (err) {
    addOcrLog(`❌ Erro durante calibração: ${err.message}`);
  } finally {
    if (progressToast && progressToast.parentNode) progressToast.remove();
    window.removeEventListener('calibrationProgress', onProgress);
    if (wasActive) {
      isOcrActive = true;
      isProcessing = false;
      processingCooldown = false;
      setTimeout(() => requestAnimationFrame(processOcrFrame), 100);
    }
  }

  if (result) {
    addOcrLog(`✅ Calibração concluída!`);
    addOcrLog(
      `📊 Melhor configuração: Contraste=${result.settings.contrast}, Brilho=${result.settings.brightness}, Limiar=${result.settings.threshold}`
    );
    addOcrLog(`📖 Leitura obtida: "${result.cleaned}"`);
    showToast(T('toast.ocr_ok', { text: result.cleaned }));
  } else {
    addOcrLog(`⚠️ Não foi possível encontrar uma configuração ideal`);
    showToast(T('toast.ocr_bad'));
  }
}

// Debug opcional (evita “poluir” o console em uso normal)
const __DEBUG_CALIBRATOR = false;

/**
 * Entrada do botão calibrador: exige scanner ativo e worker OCR pronto, depois {@link autoCalibrate}.
 * @returns {void}
 */
function openCalibrator() {
  if (__DEBUG_CALIBRATOR) console.log('🔧 openCalibrator chamado!');
  if (!isOcrActive) {
    addOcrLog("❌ Ative o scanner primeiro! Clique em 'Escanear Carta'");
    showToast(T('toast.scanner_enable'));
    return;
  }
  if (!ocrWorker) {
    addOcrLog('⚠️ OCR ainda não carregou, aguarde alguns segundos...');
    showToast(T('toast.ocr_wait'));
    return;
  }
  autoCalibrate();
}

if (__DEBUG_CALIBRATOR) console.log('🔍 Verificando calibrador...');
if (__DEBUG_CALIBRATOR) console.log('calibrator:', calibrator);
// console.log("openCalibrationUI:", typeof calibrator.openCalibrationUI);

/**
 * Atalho de consola/HTML: mesmo fluxo que o botão calibrador (`alert` se scanner inativo).
 * @returns {void}
 */
window.testCalibrator = function () {
  console.log('🧪 Teste manual do calibrador');
  if (!isOcrActive) {
    alert(T('alert.scanner_first'));
    return;
  }
  autoCalibrate();
};

